// --- File shares / folder sync ---

/// One share as both frontends see it. The domain type is deliberately not
/// serializable, so this DTO keeps the FRB and web JSON shapes identical.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct MobileShare {
    /// Stable id shared with peers on the wire.
    pub share_id: String,
    /// Verified id of the owning account.
    pub owner_user_id: String,
    /// Human-readable share name.
    pub name: String,
    /// `private` or `public`.
    pub kind: String,
    /// Whether a public share accepts writes.
    pub public_write: bool,
    /// Real local directory bound to this share, if any.
    pub local_root: Option<String>,
    /// Current manifest revision.
    pub revision: i64,
}

impl From<crate::shares::Share> for MobileShare {
    fn from(share: crate::shares::Share) -> Self {
        Self {
            share_id: share.share_id,
            owner_user_id: share.owner_user_id,
            name: share.name,
            kind: crate::shares::kind_label(share.kind).to_string(),
            public_write: share.public_write,
            local_root: share.local_root,
            revision: i64::try_from(share.revision).unwrap_or(i64::MAX),
        }
    }
}

/// One target user's permission on a share.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct MobileShareGrant {
    /// Verified target user id.
    pub user_id: String,
    /// `readonly` or `readwrite`.
    pub mode: String,
}

impl From<crate::shares::ShareGrant> for MobileShareGrant {
    fn from(grant: crate::shares::ShareGrant) -> Self {
        Self {
            user_id: grant.user_id,
            mode: crate::shares::mode_label(grant.mode).to_string(),
        }
    }
}

fn parse_share_kind(kind: &str) -> Result<crate::shares::ShareKind, String> {
    match kind {
        "private" => Ok(crate::shares::ShareKind::Private),
        "public" => Ok(crate::shares::ShareKind::Public),
        other => Err(format!("invalid share kind: {other}")),
    }
}

fn parse_share_mode(mode: &str) -> Result<crate::shares::ShareMode, String> {
    match mode {
        "readonly" => Ok(crate::shares::ShareMode::ReadOnly),
        "readwrite" => Ok(crate::shares::ShareMode::ReadWrite),
        other => Err(format!("invalid share mode: {other}")),
    }
}

fn local_share_owner() -> Result<String, String> {
    get_my_user_id()?.ok_or_else(|| "local user is not provisioned".to_string())
}

/// Input for [`create_share`]. Grouping the optional native path keeps the FRB
/// signature stable while letting the wrapper consume every owned argument.
#[derive(Debug, Clone)]
pub struct CreateShareParams {
    /// Human-readable share name.
    pub name: String,
    /// `private` or `public`.
    pub kind: String,
    /// Whether a public share accepts writes.
    pub public_write: bool,
    /// Real local directory bound to this share, if any.
    pub local_root: Option<String>,
}

/// Create a share owned by this install's verified user.
///
/// # Errors
/// Returns an error for an invalid name/kind, a missing local user, or a DB failure.
pub fn create_share(params: CreateShareParams) -> Result<MobileShare, String> {
    let CreateShareParams {
        name,
        kind,
        public_write,
        local_root,
    } = params;
    let owner = local_share_owner()?;
    let share = crate::shares::create_share(
        &name,
        &owner,
        parse_share_kind(&kind)?,
        public_write,
        local_root.as_deref(),
    )
    .map_err(|error| error.to_string())?;
    Ok(share.into())
}

/// List every locally known share, owned or accepted from a peer.
///
/// # Errors
/// Returns an error if the share table cannot be read.
pub fn list_shares() -> Result<Vec<MobileShare>, String> {
    let shares = crate::shares::list_shares().map_err(|error| error.to_string())?;
    Ok(shares.into_iter().map(Into::into).collect())
}

/// Load one share by id.
///
/// # Errors
/// Returns an error if the share table cannot be read.
pub fn get_share(share_id: &str) -> Result<Option<MobileShare>, String> {
    let share = crate::shares::get_share(share_id).map_err(|error| error.to_string())?;
    Ok(share.map(Into::into))
}

/// Input for [`bind_share`]. Grouping the optional native path keeps the FRB
/// signature stable while letting the wrapper consume every owned argument.
#[derive(Debug, Clone)]
pub struct BindShareParams {
    /// Share to bind.
    pub share_id: String,
    /// Real local directory, or `None` to clear the binding.
    pub local_root: Option<String>,
}

/// Bind (or clear) the real local folder backing a share.
///
/// # Errors
/// Returns an error for a missing share or a DB failure.
pub fn bind_share(params: BindShareParams) -> Result<(), String> {
    let BindShareParams {
        share_id,
        local_root,
    } = params;
    crate::shares::set_local_root(&share_id, local_root.as_deref())
        .map_err(|error| error.to_string())
}

/// Delete a share row. Blobs and the bound folder are left untouched.
///
/// # Errors
/// Returns an error if the DB delete fails.
pub fn delete_share(share_id: &str) -> Result<(), String> {
    crate::shares::delete_share(share_id).map_err(|error| error.to_string())
}

/// List the per-user grants on a share.
///
/// # Errors
/// Returns an error if the grant table cannot be read.
pub fn list_share_grants(share_id: &str) -> Result<Vec<MobileShareGrant>, String> {
    let grants = crate::shares::list_grants(share_id).map_err(|error| error.to_string())?;
    Ok(grants.into_iter().map(Into::into).collect())
}

/// Grant (or upgrade) one verified user's access to a private share.
///
/// # Errors
/// Returns an error for an invalid mode or a DB failure.
pub fn set_share_grant(share_id: &str, user_id: &str, mode: &str) -> Result<(), String> {
    crate::shares::set_grant(share_id, user_id, parse_share_mode(mode)?)
        .map_err(|error| error.to_string())
}

/// Revoke one user's grant immediately.
///
/// # Errors
/// Returns an error if the DB delete fails.
pub fn remove_share_grant(share_id: &str, user_id: &str) -> Result<(), String> {
    crate::shares::remove_grant(share_id, user_id).map_err(|error| error.to_string())
}

/// Load a share's current versioned manifest.
///
/// # Errors
/// Returns an error if the share has no manifest or the DB read fails.
pub fn load_share_manifest(share_id: &str) -> Result<Option<crate::shares::ShareManifest>, String> {
    match crate::shares::get_share(share_id).map_err(|error| error.to_string())? {
        Some(share) => Ok(share.manifest),
        None => Ok(None),
    }
}

/// Persist a validated manifest and bump the share's revision.
///
/// # Errors
/// Returns an error for an invalid/mismatched manifest or a DB failure.
pub fn save_share_manifest(
    share_id: &str,
    manifest: crate::shares::ShareManifest,
) -> Result<(), String> {
    let manifest = Box::new(manifest);
    crate::shares::save_manifest(share_id, &manifest).map_err(|error| error.to_string())
}

/// Materialise a received offer as a local share row.
///
/// # Errors
/// Returns an error for an invalid offer or a DB failure.
pub fn accept_share_offer(offer: crate::shares::ShareOffer) -> Result<MobileShare, String> {
    let offer = Box::new(offer);
    let share = crate::shares::accept_offer(&offer, None).map_err(|error| error.to_string())?;
    Ok(share.into())
}

/// Snapshot a real local folder into content-addressed blobs and save the
/// resulting manifest. Only native installs can call this with a server path.
///
/// # Errors
/// Returns an error if the folder cannot be read, a blob cannot be stored, or
/// the share is unknown.
pub fn snapshot_share(
    share_id: String,
    root: &str,
) -> Result<crate::shares::ShareManifest, String> {
    let entries = crate::shares::snapshot_tree(std::path::Path::new(root))
        .map_err(|error| error.to_string())?;
    let share = crate::shares::get_share(&share_id)
        .map_err(|error| error.to_string())?
        .ok_or_else(|| format!("unknown share: {share_id}"))?;
    let manifest = crate::shares::ShareManifest {
        share_id,
        name: share.name,
        revision: share.revision.saturating_add(1),
        entries,
    };
    crate::shares::save_manifest(&manifest.share_id, &manifest)
        .map_err(|error| error.to_string())?;
    Ok(manifest)
}

/// Ask a peer for every share we are allowed to read.
///
/// # Errors
/// Returns an error if the node is not running.
pub fn request_peer_shares(peer_id: &str) -> Result<(), String> {
    crate::mobile_node::queue_share_command(crate::SwarmCommand::ListShares {
        peer_id: peer_id.to_string(),
    })
}

/// Ask a share owner for its current manifest.
///
/// # Errors
/// Returns an error if the node is not running.
pub fn request_share_manifest(peer_id: &str, share_id: &str) -> Result<(), String> {
    crate::mobile_node::queue_share_command(crate::SwarmCommand::RequestShareManifest {
        peer_id: peer_id.to_string(),
        share_id: share_id.to_string(),
    })
}

/// Advertise one or more shares to connected peers.
///
/// # Errors
/// Returns an error if the node is not running.
pub fn send_share_offer(
    peer_ids: Vec<String>,
    offer: crate::shares::ShareOffer,
) -> Result<(), String> {
    crate::mobile_node::queue_share_command(crate::SwarmCommand::SendShareOffer {
        peer_ids,
        offer: Box::new(offer),
    })
}

/// Submit a new snapshot based on a specific revision. The owner rejects stale
/// writes so the caller must refresh and retry.
///
/// # Errors
/// Returns an error for a negative base revision or a node that is not running.
pub fn publish_share_snapshot(
    peer_id: &str,
    base_revision: i64,
    manifest: crate::shares::ShareManifest,
) -> Result<(), String> {
    let base_revision = u64::try_from(base_revision)
        .map_err(|_| "base revision must be non-negative".to_string())?;
    crate::mobile_node::queue_share_command(crate::SwarmCommand::PublishShareSnapshot {
        peer_id: peer_id.to_string(),
        base_revision,
        manifest: Box::new(manifest),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use serial_test::serial;

    fn db_lock() -> std::sync::MutexGuard<'static, ()> {
        crate::db::shared_db_test_lock()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    #[test]
    #[serial(db)]
    fn set_peer_local_nickname_validates_and_persists() {
        let _guard = db_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        crate::db::reset_db_url();
        crate::mobile_api::init_mobile_database(
            dir.path().join("api.sqlite").to_string_lossy().into_owned(),
        )
        .expect("mobile init");

        // Valid: persisted and readable back through the canonical getter.
        set_peer_local_nickname("peer-1", "alice-1").expect("valid nickname");
        assert_eq!(
            crate::nickname::get_peer_local_nickname("peer-1")
                .expect("read back")
                .as_deref(),
            Some("alice-1")
        );

        // Invalid input is rejected by the same canonical rules everywhere
        // (empty, over the length cap, non-alphanumeric/dash characters).
        for bad in ["", "a-very-long-nickname-over-20", "has space", "bad!"] {
            assert!(
                set_peer_local_nickname("peer-1", bad).is_err(),
                "expected rejection for {bad:?}"
            );
        }
        // A rejected name never overwrites the stored one.
        assert_eq!(
            crate::nickname::get_peer_local_nickname("peer-1")
                .expect("read back")
                .as_deref(),
            Some("alice-1")
        );
    }

    #[test]
    #[serial(db)]
    fn set_self_nickname_validates_and_persists() {
        let _guard = db_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        crate::db::reset_db_url();
        crate::mobile_api::init_mobile_database(
            dir.path().join("api.sqlite").to_string_lossy().into_owned(),
        )
        .expect("mobile init");

        // Valid: trimmed and readable back through the canonical getter.
        set_self_nickname("  alice-1  ").expect("valid nickname");
        assert_eq!(
            crate::nickname::get_self_nickname()
                .expect("read back")
                .as_deref(),
            Some("alice-1")
        );

        // Invalid input is rejected by the same canonical rules the Flutter and
        // TUI frontends use, and never overwrites the stored nickname.
        for bad in [
            "",
            "a-very-long-nickname-over-20",
            "has space",
            "bad!",
            "Alice👋",
        ] {
            assert!(
                set_self_nickname(bad).is_err(),
                "expected rejection for {bad:?}"
            );
        }
        assert_eq!(
            crate::nickname::get_self_nickname()
                .expect("read back")
                .as_deref(),
            Some("alice-1")
        );
    }

    #[test]
    #[serial(db)]
    fn delete_group_removes_group_and_membership() {
        let _guard = db_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        crate::db::reset_db_url();
        crate::mobile_api::init_mobile_database(
            dir.path().join("api.sqlite").to_string_lossy().into_owned(),
        )
        .expect("mobile init");

        let group = crate::groups::create_public_group("Team Rocket").expect("create group");
        crate::groups::record_group_member(&group.group_id, "peer-1").expect("member");
        assert_eq!(
            crate::groups::get_group_member_count(&group.group_id).expect("count"),
            1
        );

        delete_group(group.group_id.clone()).expect("leave group");

        assert!(
            crate::groups::find_group(&group.group_id)
                .expect("lookup")
                .is_none(),
            "group row must be gone"
        );
        assert_eq!(
            crate::groups::get_group_member_count(&group.group_id).expect("count"),
            0,
            "membership must be gone"
        );

        // Unknown group: idempotent success (nothing to delete).
        delete_group("does-not-exist".to_string()).expect("idempotent leave");
    }

    #[test]
    #[serial(db)]
    fn share_facade_covers_the_full_local_lifecycle() {
        let _guard = db_lock();
        let dir = tempfile::tempdir().expect("tempdir");
        crate::db::reset_db_url();
        crate::mobile_api::init_mobile_database(
            dir.path().join("api.sqlite").to_string_lossy().into_owned(),
        )
        .expect("mobile init");
        let owner = provision_my_user(None, None).expect("provision");

        let created = create_share(CreateShareParams {
            name: "Photos".to_string(),
            kind: "private".to_string(),
            public_write: false,
            local_root: None,
        })
        .expect("create share");
        assert_eq!(created.owner_user_id, owner);
        assert_eq!(created.kind, "private");
        assert_eq!(created.revision, 0);

        assert_eq!(list_shares().expect("list").len(), 1);
        assert_eq!(
            get_share(&created.share_id)
                .expect("get")
                .expect("present")
                .name,
            "Photos"
        );
        assert!(get_share("missing").expect("get missing").is_none());

        let root = dir.path().join("photos");
        std::fs::create_dir(&root).expect("root dir");
        bind_share(BindShareParams {
            share_id: created.share_id.clone(),
            local_root: Some(root.to_string_lossy().into_owned()),
        })
        .expect("bind");
        assert_eq!(
            get_share(&created.share_id)
                .expect("get")
                .expect("present")
                .local_root
                .as_deref(),
            Some(root.to_str().expect("root str"))
        );

        set_share_grant(&created.share_id, "alice", "readwrite").expect("grant");
        let grants = list_share_grants(&created.share_id).expect("grants");
        assert_eq!(grants.len(), 1);
        assert_eq!(grants[0].user_id, "alice");
        assert_eq!(grants[0].mode, "readwrite");
        assert!(set_share_grant(&created.share_id, "alice", "bogus").is_err());
        remove_share_grant(&created.share_id, "alice").expect("revoke");
        assert!(
            list_share_grants(&created.share_id)
                .expect("grants")
                .is_empty()
        );

        let manifest = crate::shares::ShareManifest {
            share_id: created.share_id.clone(),
            name: created.name.clone(),
            revision: 1,
            entries: vec![],
        };
        save_share_manifest(&created.share_id, manifest.clone()).expect("save manifest");
        assert_eq!(
            load_share_manifest(&created.share_id)
                .expect("load manifest")
                .as_ref(),
            Some(&manifest)
        );
        assert!(
            load_share_manifest("missing")
                .expect("load missing")
                .is_none()
        );

        let offer = crate::shares::ShareOffer {
            share_id: "remote-share".to_string(),
            name: "Remote".to_string(),
            kind: crate::shares::ShareKind::Public,
            revision: 3,
            public_write: false,
            owner_user_id: Some("bob".to_string()),
        };
        let accepted = accept_share_offer(offer).expect("accept offer");
        assert_eq!(accepted.share_id, "remote-share");
        // The offer's revision is remote metadata; the local row starts at 0
        // until its manifest is fetched and saved.
        assert_eq!(accepted.revision, 0);

        delete_share(&accepted.share_id).expect("delete");
        assert!(get_share(&accepted.share_id).expect("get").is_none());
    }

    #[test]
    fn share_facade_rejects_invalid_inputs_without_a_node() {
        assert!(parse_share_kind("secret").is_err());
        assert!(parse_share_mode("admin").is_err());
        assert!(
            publish_share_snapshot(
                "peer-1",
                -1,
                crate::shares::ShareManifest {
                    share_id: "s".to_string(),
                    name: "S".to_string(),
                    revision: 1,
                    entries: vec![],
                },
            )
            .unwrap_err()
            .contains("non-negative")
        );
        // Command wrappers fail cleanly when the node is not running.
        assert!(request_peer_shares("peer-1").is_err());
        assert!(request_share_manifest("peer-1", "s").is_err());
    }
}

//! P2P network behavior and protocol definitions

// Stable clippy flags an `unreachable call` inside the NetworkBehaviour derive
// expansion; it is macro-generated, not a hand-written unreachable branch.
#![allow(unreachable_code)]

use crate::files::MessageAttachment;
use crate::network::NetworkSize;
use crate::p2plog_debug;
use crate::reply::ReplyRef;
use libp2p::gossipsub;
use libp2p::ping;
use libp2p::request_response;
use libp2p::swarm::NetworkBehaviour;
use serde::{Deserialize, Serialize};

/// Chat protocol name for direct messages
pub const DM_PROTOCOL_NAME: &str = "/p2p-chat/dm/1.0.0";

/// Device-binding protocol name (identity lane §11).
///
/// One-shot signed claims that bind a device (install keypair) into a remote
/// account's device-set. `intro` requests advertise a device+account; `claim`
/// requests carry the account-key-signed claim that the receiver verifies
/// before binding.
pub const DEVICE_BINDING_PROTOCOL_NAME: &str = "/p2p-chat/device-binding/1.0.0";

/// Call-signaling protocol name (calls lane).
///
/// One-shot JSON signals over a dedicated `request_response` lane, mirroring the
/// device-binding pattern. Kinds: `"invite"` (the callee is asked to ring),
/// `"accept"`/`"reject"` (the callee's answer to an invite), and `"end"`
/// (either side tears the call down). The signaling slice carries no media:
/// `CallSignal::descriptor` is reserved for the later offer/answer payload.
pub const CALL_PROTOCOL_NAME: &str = "/p2p-chat/call/1.0.0";

/// Voice media protocol name (calls lane; US-044).
///
/// One CBOR-encoded μ-law frame per request, with a lightweight ack. A separate
/// lane keeps 50 frames/second from occupying signaling, DM or typing slots.
pub const CALL_MEDIA_PROTOCOL_NAME: &str = "/p2p-chat/call-media/1.0.0";

/// Typing-indicator protocol name (US-009).
///
/// A dedicated `request_response` lane keeps fire-and-forget typing updates out
/// of the DM request slots: each signal occupies its own short-lived stream and
/// is acknowledged immediately. Nothing is persisted — both frontends apply a
/// short TTL to the received signal.
pub const TYPING_PROTOCOL_NAME: &str = "/p2p-chat/typing/1.0.0";

/// Message-reaction protocol name (US-008).
///
/// Reactions are persistent social data, so unlike typing they receive a real
/// ack: the sender applies its change locally and the ack only confirms the peer
/// accepted the signal. A dedicated lane keeps a burst of reacts out of the DM
/// and typing slots.
pub const REACTION_PROTOCOL_NAME: &str = "/p2p-chat/reactions/1.0.0";

/// File-transfer protocol name (files lane §12).
///
/// A dedicated `request_response` lane for content-addressed attachments. The
/// receiver drives every transfer: it requests the metadata (`"meta"`), then
/// pulls fixed-size chunks (`"chunk"`) sequentially until the file is complete.
/// The sender serves purely from its content-addressed store (prepared by
/// `files::store_outgoing_file` before the message is sent, so the blob is
/// already on disk when the receiver asks).
pub const FILE_TRANSFER_PROTOCOL_NAME: &str = "/p2p-chat/files/1.0.0";

/// File-share / folder-sync protocol name (share lane).
///
/// A dedicated `request_response` lane for versioned share manifests and ACL
/// checks. Bytes still move over the attachment file lane; this lane only
/// carries offers, manifest requests, manifests and write submissions.
pub const SHARE_PROTOCOL_NAME: &str = "/p2p-chat/shares/1.0.0";

/// Default chat topic
pub const CHAT_TOPIC: &str = "test-net";

/// Direct message content with timestamp and sender info
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct DirectMessage {
    /// The message content/text
    pub content: String,
    /// Unix timestamp when the message was created
    pub timestamp: i64,
    /// Optional timestamp of when the message was sent to the network
    pub sent_at: Option<f64>,
    /// Optional nickname of the sender
    pub nickname: Option<String>,
    /// Optional unique identifier for this message
    pub msg_id: Option<String>,
    /// Receipt target (delivery acknowledgment only — never a reply id, US-006)
    pub ack_for: Option<String>,
    /// Optional timestamp of when this message was received
    pub received_at: Option<f64>,
    /// Stable `group_id` a private-group DM is attributed to; `None` = plain DM
    pub group_id: Option<String>,
    /// Optional attachment descriptor (files lane §12); the bytes are fetched
    /// separately over the file lane by the receiver.
    pub attachment: Option<MessageAttachment>,
    /// Immutable reply snapshot (US-006); `None` for an ordinary message.
    pub reply_to: Option<ReplyRef>,
    /// Optional end-to-end sealed body (US-042). When present the receiver
    /// opens it and uses the decrypted `content`/`nickname`/`attachment`
    /// instead of the (empty) plaintext fields above.
    pub encrypted: Option<crate::e2e::EncryptedDm>,
}

/// Broadcast message content with timestamp and sender info
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct BroadcastMessage {
    /// The message content/text
    pub content: String,
    /// Optional timestamp of when the message was sent
    pub sent_at: Option<f64>,
    /// Optional nickname of the sender
    pub nickname: Option<String>,
    /// Optional unique identifier for this message
    pub msg_id: Option<String>,
    /// Optional attachment descriptor (files lane §12)
    pub attachment: Option<MessageAttachment>,
    /// Immutable reply snapshot (US-006); `None` for an ordinary message.
    pub reply_to: Option<ReplyRef>,
}

/// Group message content traveling over a per-group gossipsub topic
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct GroupMessage {
    /// The group this message belongs to (must match the topic's group id)
    pub group_id: String,
    /// The message content/text
    pub content: String,
    /// Optional timestamp of when the message was sent
    pub sent_at: Option<f64>,
    /// Optional nickname of the sender
    pub nickname: Option<String>,
    /// Optional unique identifier for this message
    pub msg_id: Option<String>,
    /// Optional attachment descriptor (files lane §12)
    pub attachment: Option<MessageAttachment>,
    /// Immutable reply snapshot (US-006); `None` for an ordinary message.
    pub reply_to: Option<ReplyRef>,
}

/// Backfill request sent on a group's backfill topic on (re)subscribe
/// (backlog §11.5).
///
/// Gossipsub never replays, so a member that was offline — or joined after the
/// group started — misses the gap. On subscribe the member publishes this
/// requesting everything newer than its `after` watermark; **any** online
/// member whose stored history is newer answers by re-publishing the bounded
/// recent messages as ordinary [`GroupMessage`]s on the main group topic, where
/// the `(group_id, msg_id)` unique index (plus the `nil:` synthetic key for
/// messages without an `msg_id`) absorbs every overlap. The request itself is
/// anonymous control traffic — never persisted.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct GroupBackfillRequest {
    /// The group whose gap is being requested (must match the topic's group id).
    pub group_id: String,
    /// Only messages stored with `sent_at` strictly newer than this are asked
    /// for (`0.0` requests the member's full recent history).
    pub after: f64,
}

/// JSON codec for direct message protocol
pub type ChatCodec = libp2p::request_response::json::codec::Codec<DirectMessage, DirectMessage>;

/// File-transfer exchange payload (files lane §12; receiver-driven).
///
/// One wire type, two request `kind`s and one response type:
///
/// * request `"meta"`  — ask for `file_id`'s metadata (name/size/mime/chunking).
/// * request `"chunk"` — pull chunk `chunk_index` of `file_id`.
/// * response         — `kind == "meta"` carries the metadata handshake;
///   `kind == "chunk"` carries `data`; `kind == "error"` carries a `reason`
///   (unknown file, oversized, out-of-range chunk).
///
/// CBOR (not JSON) is used on purpose: chunk payloads are opaque byte strings,
/// which CBOR serializes natively (~1:1) whereas JSON would expand a 1 MiB
/// chunk ~4x into a base64/array text blob.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct FileTransfer {
    /// `"meta"` | `"chunk"`
    pub kind: String,
    /// Content address (SHA-256 hex) of the whole file
    pub file_id: String,
    /// Zero-based chunk index (request `"chunk"` only)
    pub chunk_index: Option<u64>,
}

/// Response to a [`FileTransfer`] request.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct FileTransferResponse {
    /// `"meta"` | `"chunk"` | `"error"`
    pub kind: String,
    /// Content address (SHA-256 hex) of the whole file
    pub file_id: String,
    /// Original filename (`"meta"` only)
    pub name: Option<String>,
    /// Total byte length (`"meta"` only)
    pub size: Option<u64>,
    /// Best-effort MIME type hint (`"meta"` only)
    pub mime: Option<String>,
    /// Number of fixed-size chunks (`"meta"` only; `ceil(size / chunk_size)`)
    pub total_chunks: Option<u64>,
    /// Chunk size in bytes (`"meta"` only)
    pub chunk_size: Option<u64>,
    /// The chunk index echoed back (`"chunk"` only)
    pub chunk_index: Option<u64>,
    /// Raw chunk bytes (`"chunk"` only)
    pub data: Option<Vec<u8>>,
    /// Human-readable failure description (`"error"` only)
    pub reason: Option<String>,
}

/// CBOR codec for the file-transfer protocol
pub type FileTransferCodec =
    libp2p::request_response::cbor::codec::Codec<FileTransfer, FileTransferResponse>;

/// Device-binding exchange payload (identity lane §11; signed claims).
///
/// One wire type, two `kind`s:
///
/// * `"intro"`  — sender advertises its device (and account, once provisioned)
///   so the account holder can decide whether to mint a claim for it.
/// * `"claim"` — a signed device→user claim. `user_id`, `account_pubkey`,
///   `claim_id`, `bound_at` and `signature` are all present. The receiver
///   ([`crate::identity::receive_device_binding_claim`]) checks the claim is
///   about itself, materializes the account root without display data,
///   verifies `signature` over `user_id ‖ device_pubkey ‖ claim_id` against
///   *that user's* stored account pubkey, binds (`save_device_binding`), and
///   only then persists the self-declared display seams. Never auto-mints.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct DeviceBindingRequest {
    /// `"intro"` or `"claim"`
    pub kind: String,
    /// Account the claim/intro is about (`None` for an unprovisioned intro)
    pub user_id: Option<String>,
    /// Account pubkey that signs claims for `user_id` (claim; root of trust)
    pub account_pubkey: Option<Vec<u8>>,
    /// Account's self-declared username (display lane)
    pub self_username: Option<String>,
    /// Account's self-declared nickname (display lane)
    pub self_nickname: Option<String>,
    /// Peer ID of the subject device (intro: sender; claim: the device claimed)
    pub peer_id: String,
    /// Pubkey (protobuf) of the subject device (install keypair)
    pub device_pubkey: Vec<u8>,
    /// Unique claim identifier (present on claim)
    pub claim_id: Option<String>,
    /// Unix seconds when the claim was minted (present on claim; display only)
    pub bound_at: Option<f64>,
    /// Signed claim over `user_id ‖ device_pubkey ‖ claim_id` (present on claim)
    pub signature: Option<Vec<u8>>,
}

/// Ack for a device-binding request (`kind` echoes the request kind).
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct DeviceBindingAck {
    /// Whether the exchange was accepted and (for claims) bound
    pub ok: bool,
    /// Human-readable reason on failure
    pub reason: Option<String>,
}

/// JSON codec for the device-binding protocol
pub type DeviceBindingCodec =
    libp2p::request_response::json::codec::Codec<DeviceBindingRequest, DeviceBindingAck>;

/// Call-signaling exchange payload (calls lane; signaling first, media later).
///
/// One wire type, four `kind`s — the caller mints the end-to-end `call_id`
/// (via `gen_msg_id`) and every side echoes it back, so each side can match
/// signals to its live session.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct CallSignal {
    /// `"invite"` | `"accept"` | `"reject"` | `"end"`
    pub kind: String,
    /// Session id minted by the caller; echoed by every later signal.
    pub call_id: String,
    /// Unix seconds when the signal was sent.
    pub timestamp: f64,
    /// Reserved: media offer/answer descriptor (SDP/ICE) when media lands.
    pub descriptor: Option<String>,
}

impl CallSignal {
    /// Build a signal of the given kind for a session, stamping the current
    /// time and leaving the reserved media descriptor empty.
    #[must_use]
    pub fn new(kind: &str, call_id: String) -> Self {
        Self {
            kind: kind.to_string(),
            call_id,
            timestamp: crate::current_timestamp(),
            descriptor: None,
        }
    }
}

/// Ack for a call-signaling request (`ok` = the signal was understood).
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct CallSignalAck {
    /// Whether the signal was accepted
    pub ok: bool,
    /// Human-readable reason on failure
    pub reason: Option<String>,
}

/// JSON codec for the call-signaling protocol
pub type CallSignalCodec = libp2p::request_response::json::codec::Codec<CallSignal, CallSignalAck>;

/// A transient typing state for one DM conversation (US-009).
///
/// `timestamp` is the sender's `current_timestamp()`; receivers apply their own
/// short TTL, so a delayed or reordered stop can never stick forever.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, Default, PartialEq)]
#[serde(default)]
pub struct TypingSignal {
    /// `true` when the sender is composing, `false` when they stopped.
    pub is_typing: bool,
    /// Sender wall-clock timestamp (seconds since epoch).
    pub timestamp: f64,
}

impl TypingSignal {
    /// Build a typing state stamped with the current time.
    #[must_use]
    pub fn new(is_typing: bool) -> Self {
        Self {
            is_typing,
            timestamp: crate::current_timestamp(),
        }
    }
}

/// Ack for a typing signal. Typing is fire-and-forget from the UI's point of
/// view; the ack only closes the request-response stream promptly.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct TypingAck {
    /// Whether the signal was understood.
    pub ok: bool,
}

/// JSON codec for the typing-indicator protocol.
pub type TypingCodec = libp2p::request_response::json::codec::Codec<TypingSignal, TypingAck>;

/// A reaction added to or removed from a message (US-008).
///
/// `msg_id` is the stable wire id shared by broadcast, DM and group messages;
/// `actor` is the reactor's transport peer id (not spoofable by the receiver,
/// which uses the connection's peer id). `remove` distinguishes a toggle-off
/// from a toggle-on so a replay is idempotent.
#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq, Eq)]
#[serde(default)]
pub struct ReactionSignal {
    /// Stable wire id of the message being reacted to.
    pub msg_id: String,
    /// Emoji token (glyph or shortcode).
    pub emoji: String,
    /// Reactor's transport peer id.
    pub actor: String,
    /// `false` = add the reaction, `true` = remove it.
    pub remove: bool,
}

impl ReactionSignal {
    /// Build a reaction change stamped with the reactor's peer id.
    #[must_use]
    pub const fn new(msg_id: String, emoji: String, actor: String, remove: bool) -> Self {
        Self {
            msg_id,
            emoji,
            actor,
            remove,
        }
    }
}

/// Ack for a reaction signal. The ack only closes the request-response stream;
/// the sender already applied its own change locally before sending.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct ReactionAck {
    /// Whether the signal was accepted.
    pub ok: bool,
}

/// JSON codec for the message-reaction protocol.
pub type ReactionCodec = libp2p::request_response::json::codec::Codec<ReactionSignal, ReactionAck>;

/// One request on the share lane (file share / folder sync).
///
/// `kind` is one of `"offer"` (an unsolicited advertisement), `"list"` (all
/// shares the requester may read), `"manifest"` (one share's current snapshot)
/// or `"publish"` (a read-write peer submitting a new snapshot based on
/// `base_revision`). The requester's identity is taken from the connection's
/// peer id, never from this payload.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct ShareRequest {
    /// `"offer"`, `"list"`, `"manifest"` or `"publish"`.
    pub kind: String,
    /// Share id for `"manifest"` and `"publish"`.
    pub share_id: String,
    /// Revision the submitted manifest was built from (`"publish"` only).
    pub base_revision: u64,
    /// New snapshot (`"publish"` only).
    pub manifest: Option<crate::shares::ShareManifest>,
    /// Advertisement (`"offer"` only).
    pub offer: Option<crate::shares::ShareOffer>,
}

/// Response on the share lane. `kind` echoes the request so the caller can
/// dispatch a manifest back to the right share without extra state.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct ShareResponse {
    /// Whether the request was accepted.
    pub ok: bool,
    /// Echo of the request kind.
    pub kind: String,
    /// Echo of the requested share id.
    pub share_id: String,
    /// Human-readable reason when `ok` is false.
    pub reason: Option<String>,
    /// New/current revision after a successful request.
    pub revision: u64,
    /// Offers returned by a `"list"` request.
    pub offers: Vec<crate::shares::ShareOffer>,
    /// Snapshot returned by a `"manifest"` request.
    pub manifest: Option<crate::shares::ShareManifest>,
}

/// JSON codec for the share protocol.
pub type ShareCodec = libp2p::request_response::json::codec::Codec<ShareRequest, ShareResponse>;

/// Combined network behavior for p2p chat
#[derive(NetworkBehaviour)]
pub struct AppBehaviour {
    /// Gossipsub protocol handler for broadcast messages
    pub gossipsub: gossipsub::Behaviour,
    /// Request-response protocol handler for direct messages
    pub request_response: request_response::Behaviour<ChatCodec>,
    /// Request-response protocol handler for signed device-binding exchanges
    /// (identity lane §11: intro + account-signed claims)
    pub device_binding: request_response::Behaviour<DeviceBindingCodec>,
    /// Request-response protocol handler for call signaling (calls lane:
    /// invite/accept/reject/end).
    pub call_signaling: request_response::Behaviour<CallSignalCodec>,
    /// Request-response protocol handler for voice frames (calls lane, US-044).
    pub call_media: request_response::Behaviour<crate::call_media::MediaCodec>,
    /// Request-response protocol handler for transient DM typing indicators
    /// (US-009): a separate lane so signals never consume a DM request slot.
    pub typing: request_response::Behaviour<TypingCodec>,
    /// Request-response protocol handler for persistent message reactions
    /// (US-008): a separate lane so a burst of reacts cannot starve DMs.
    pub reactions: request_response::Behaviour<ReactionCodec>,
    /// Request-response protocol handler for content-addressed file transfers
    /// (files lane §12): the receiver pulls metadata and chunks, the sender
    /// serves them from its on-disk store.
    pub file_transfer: request_response::Behaviour<FileTransferCodec>,
    /// Request-response protocol handler for versioned file shares / folder
    /// sync (share lane): offers, manifests and revision-checked writes.
    pub shares: request_response::Behaviour<ShareCodec>,
    /// mDNS protocol handler for peer discovery (when mdns feature is enabled)
    #[cfg(feature = "mdns")]
    pub mdns: libp2p::mdns::tokio::Behaviour,
    /// Kademlia DHT for internet-wide peer discovery (when kad feature is enabled)
    #[cfg(feature = "kad")]
    pub kad: libp2p::kad::Behaviour<libp2p::kad::store::MemoryStore>,
    /// Identify protocol: exchanges peer info + listen addresses (needed by kad)
    #[cfg(feature = "kad")]
    pub identify: libp2p::identify::Behaviour,
    /// Circuit-relay server (when relay feature is enabled): lets this node
    /// relay connections for peers behind NAT.
    #[cfg(feature = "relay")]
    pub relay_server: libp2p::relay::Behaviour,
    /// Circuit-relay client (when relay feature is enabled): lets this node
    /// use relay servers to become reachable from behind NAT.
    #[cfg(feature = "relay")]
    pub relay_client: libp2p::relay::client::Behaviour,
    /// `AutoNAT` (when nat feature is enabled): detects whether this node is
    /// publicly reachable.
    #[cfg(feature = "nat")]
    pub autonat: libp2p::autonat::Behaviour,
    /// `DCUtR` (when nat feature is enabled): hole punching through relays.
    #[cfg(feature = "nat")]
    pub dcutr: libp2p::dcutr::Behaviour,
    /// Ping protocol for connection liveness: detects dead peers (e.g. a node
    /// that was killed without closing the connection) and closes the
    /// connection so `ConnectionClosed` fires and the peer is marked offline.
    pub ping: ping::Behaviour,
}

// AppBehaviourEvent is auto-generated by the NetworkBehaviour derive macro

/// Build the gossipsub behaviour, tuning history/heartbeat to network size.
fn build_gossipsub(
    key: &libp2p_identity::Keypair,
    network_size: NetworkSize,
) -> Result<gossipsub::Behaviour, String> {
    // Larger networks need a longer history and a slower heartbeat to avoid
    // redundant re-broadcasts.
    let (history_gossip, history_length, heartbeat_secs) = match network_size {
        NetworkSize::Small => (3, 20, 1),
        NetworkSize::Medium => (6, 30, 2),
        NetworkSize::Large => (12, 50, 5),
    };
    let config = gossipsub::ConfigBuilder::default()
        .max_transmit_size(262_144)
        .history_gossip(history_gossip)
        .history_length(history_length)
        .heartbeat_interval(std::time::Duration::from_secs(heartbeat_secs))
        .build()
        .map_err(|e| format!("invalid gossipsub config: {e}"))?;
    gossipsub::Behaviour::new(gossipsub::MessageAuthenticity::Signed(key.clone()), config)
        .map_err(|e| format!("Failed to create gossipsub behavior: {e}"))
}

/// The eight `request_response` behaviours, one per protocol lane.
type RequestResponseLanes = (
    request_response::Behaviour<ChatCodec>,
    request_response::Behaviour<DeviceBindingCodec>,
    request_response::Behaviour<CallSignalCodec>,
    request_response::Behaviour<crate::call_media::MediaCodec>,
    request_response::Behaviour<TypingCodec>,
    request_response::Behaviour<ReactionCodec>,
    request_response::Behaviour<FileTransferCodec>,
    request_response::Behaviour<ShareCodec>,
);

/// Build the eight `request_response` lanes.
///
/// Each lane has its own protocol name so a burst of transient traffic (typing,
/// reactions, calls, device binding, file chunks) can never occupy a DM request
/// slot.
fn build_request_response_lanes() -> RequestResponseLanes {
    fn lane<C>(protocol: &'static str) -> request_response::Behaviour<C>
    where
        C: libp2p::request_response::Codec<Protocol = libp2p::StreamProtocol>
            + Default
            + Clone
            + Send
            + 'static,
    {
        request_response::Behaviour::new(
            [(
                libp2p::StreamProtocol::new(protocol),
                request_response::ProtocolSupport::Full,
            )],
            request_response::Config::default(),
        )
    }

    (
        lane(DM_PROTOCOL_NAME),
        lane(DEVICE_BINDING_PROTOCOL_NAME),
        lane(CALL_PROTOCOL_NAME),
        lane(CALL_MEDIA_PROTOCOL_NAME),
        lane(TYPING_PROTOCOL_NAME),
        lane(REACTION_PROTOCOL_NAME),
        lane(FILE_TRANSFER_PROTOCOL_NAME),
        lane(SHARE_PROTOCOL_NAME),
    )
}

/// Build the app behavior with appropriate protocols and configurations
///
/// # Arguments
/// * `key` - libp2p identity keypair
/// * `network_size` - Network size enum for tuning behavior parameters
///
/// # Errors
/// Returns an error if any underlying libp2p protocol behavior fails to build
/// (e.g. an invalid gossipsub configuration or mDNS setup).
pub fn build_behaviour(
    key: &libp2p_identity::Keypair,
    network_size: NetworkSize,
    #[cfg(feature = "relay")] relay_client: libp2p::relay::client::Behaviour,
) -> Result<AppBehaviour, String> {
    p2plog_debug(format!(
        "Building behavior for network size: {network_size:?}"
    ));
    // Configure Gossipsub based on network size: larger networks need a longer
    // history and a slower heartbeat to avoid redundant re-broadcasts.
    let gossipsub = build_gossipsub(key, network_size)?;

    let (
        request_response,
        device_binding,
        call_signaling,
        call_media,
        typing,
        reactions,
        file_transfer,
        shares,
    ) = build_request_response_lanes();

    // Liveness checks: ping every 10s, treat a missing pong within 10s as a
    // dead connection. This surfaces killed/disconnected peers within ~10-20s
    // instead of waiting on the (often never-elapsed) idle connection timeout.
    let ping = ping::Behaviour::new(
        ping::Config::new()
            .with_interval(std::time::Duration::from_secs(10))
            .with_timeout(std::time::Duration::from_secs(10)),
    );

    #[cfg(feature = "mdns")]
    let mdns = libp2p::mdns::tokio::Behaviour::new(
        libp2p::mdns::Config::default(),
        libp2p::PeerId::from_public_key(&key.public()),
    )
    .map_err(|e| format!("invalid mdns: {e}"))?;

    #[cfg(feature = "kad")]
    let kad = {
        let store = libp2p::kad::store::MemoryStore::new(key.public().to_peer_id());
        // Join the public (IPFS) Kademlia DHT for peer discovery, but stay in
        // client mode so we never store/serve records for other networks' peers
        // (avoids holding the global DHT's record set in memory).
        let mut kad = libp2p::kad::Behaviour::new(key.public().to_peer_id(), store);
        kad.set_mode(Some(libp2p::kad::Mode::Client));
        kad
    };
    #[cfg(feature = "kad")]
    let identify = libp2p::identify::Behaviour::new(libp2p::identify::Config::new(
        // Use the IPFS identify protocol name so public bootstrap nodes can
        // exchange addresses with us; our own nodes still identify fine.
        "/ipfs/id/1.0.0".to_string(),
        key.public(),
    ));

    #[cfg(feature = "relay")]
    let relay_server = {
        // Do not act as an open relay for the public internet by default: only
        // accept reservations when explicitly opted in via P2P_RELAY_SERVER=1.
        // LAN-only mode (US-051) always disables the server, whatever the env.
        let mut cfg = libp2p::relay::Config::default();
        if std::env::var("P2P_RELAY_SERVER").is_err() || crate::settings::lan_only() {
            cfg.max_reservations = 0;
            cfg.max_reservations_per_peer = 0;
            cfg.max_circuits = 0;
            cfg.max_circuits_per_peer = 0;
        }
        libp2p::relay::Behaviour::new(key.public().to_peer_id(), cfg)
    };

    #[cfg(feature = "nat")]
    let autonat = libp2p::autonat::Behaviour::new(
        key.public().to_peer_id(),
        libp2p::autonat::Config::default(),
    );

    #[cfg(feature = "nat")]
    let dcutr = libp2p::dcutr::Behaviour::new(key.public().to_peer_id());

    Ok(AppBehaviour {
        gossipsub,
        request_response,
        device_binding,
        call_signaling,
        call_media,
        typing,
        reactions,
        file_transfer,
        shares,
        #[cfg(feature = "mdns")]
        mdns,
        #[cfg(feature = "kad")]
        kad,
        #[cfg(feature = "kad")]
        identify,
        #[cfg(feature = "relay")]
        relay_server,
        #[cfg(feature = "relay")]
        relay_client,
        #[cfg(feature = "nat")]
        autonat,
        #[cfg(feature = "nat")]
        dcutr,
        ping,
    })
}

/// Build a fully configured libp2p swarm for chat.
///
/// Sets up TCP (with nodelay), optional QUIC transport, the app behaviour
/// with adaptive network size, and a 60-second idle connection timeout.
///
/// # Errors
/// Returns an error if the libp2p identity cannot be loaded or if the swarm
/// (transport + behaviour) fails to build.
pub fn build_swarm(
    network_size: NetworkSize,
) -> color_eyre::Result<libp2p::swarm::Swarm<AppBehaviour>> {
    use std::time::Duration;

    let key = crate::get_libp2p_identity()?;

    let base = libp2p::SwarmBuilder::with_existing_identity(key)
        .with_tokio()
        .with_tcp(
            libp2p::tcp::Config::default().nodelay(true),
            libp2p::noise::Config::new,
            libp2p::yamux::Config::default,
        )?;

    #[cfg(feature = "quic")]
    let base = base.with_quic();

    #[cfg(feature = "relay")]
    let swarm = base
        .with_relay_client(libp2p::noise::Config::new, libp2p::yamux::Config::default)?
        .with_behaviour(
            |key, relay_client| -> Result<AppBehaviour, Box<dyn std::error::Error + Send + Sync>> {
                build_behaviour(key, network_size, relay_client).map_err(
                    |e| -> Box<dyn std::error::Error + Send + Sync> {
                        Box::new(std::io::Error::other(e))
                    },
                )
            },
        )?
        .with_swarm_config(|c| c.with_idle_connection_timeout(Duration::from_mins(1)))
        .build();

    #[cfg(not(feature = "relay"))]
    let swarm = base
        .with_behaviour(
            |key| -> Result<AppBehaviour, Box<dyn std::error::Error + Send + Sync>> {
                build_behaviour(key, network_size).map_err(
                    |e| -> Box<dyn std::error::Error + Send + Sync> {
                        Box::new(std::io::Error::other(e))
                    },
                )
            },
        )?
        .with_swarm_config(|c| c.with_idle_connection_timeout(Duration::from_mins(1)))
        .build();

    Ok(swarm)
}

