fn update_dm_transcript_labels(
    dm_messages: &mut std::collections::HashMap<String, std::collections::VecDeque<String>>,
    peer_id: &str,
    old_nick: &str,
    new_nick: &str,
) {
    if let Some(dm_msgs) = dm_messages.get_mut(peer_id) {
        p2p_app::tui_helpers::relabel_dm_transcript(dm_msgs, old_nick, new_nick);
    }
}

/// Pure: flip the mouse capture flag. Returns the new state.
const fn flip_mouse_capture_state(state: &mut super::state::AppState) -> bool {
    state.env.mouse_capture = !state.env.mouse_capture;
    state.env.mouse_capture
}

/// Pure: dismiss the popup if one is open. Returns true if a popup was dismissed.
fn dismiss_popup(state: &mut super::state::AppState) -> bool {
    if state.popup.is_some() {
        state.popup = None;
        true
    } else {
        false
    }
}

/// True when a dismissed validation popup should let the key reach its editor.
///
/// A validation hint describes the *previous* commit attempt; typing (or
/// erasing) is the correction, so the first correction key must still edit the
/// text instead of being consumed by the popup. Enter stays popup-owned: with
/// an unchanged invalid editor it only acknowledges the hint, avoiding a
/// redundant failed commit.
const fn popup_dismissal_feeds_editor(
    key_event: &crossterm::event::KeyEvent,
    state: &super::state::AppState,
) -> bool {
    use crossterm::event::KeyCode;

    state.is_modal_editor()
        && matches!(
            key_event.code,
            KeyCode::Char(_) | KeyCode::Backspace | KeyCode::Delete
        )
}

/// True for a bare `?`; Shift is expected (most layouts type `?` as
/// `Shift+/`) but Ctrl/Alt variants must never steal input.
fn is_shortcuts_help_key(key_event: &crossterm::event::KeyEvent) -> bool {
    use crossterm::event::{KeyCode, KeyModifiers};
    key_event.code == KeyCode::Char('?')
        && !key_event.modifiers.contains(KeyModifiers::CONTROL)
        && !key_event.modifiers.contains(KeyModifiers::ALT)
}

/// Pure: extract nickname update data from state. Returns None if the new nickname is empty.
fn prepare_nickname_update(
    state: &super::state::AppState,
) -> Option<(String, String, Option<String>)> {
    let new_nickname = state.chat_input.lines().join("\n");
    if new_nickname.trim().is_empty() {
        return None;
    }
    let (old_nickname, peer_id) = state.editing_nickname_peer.as_ref().map_or_else(
        || (state.own_nickname.clone(), None),
        |pid| {
            let old = state
                .self_nicknames_for_peers
                .get(pid)
                .cloned()
                .unwrap_or_else(|| state.own_nickname.clone());
            (old, Some(pid.clone()))
        },
    );
    Some((new_nickname, old_nickname, peer_id))
}

/// Toggles mouse capture mode (F12)
fn toggle_mouse_capture(state: &mut super::state::AppState) {
    use ratatui::crossterm::execute;
    flip_mouse_capture_state(state);
    let mode = if state.env.mouse_capture {
        "enabled"
    } else {
        "disabled"
    };
    p2plog_debug(format!("Mouse capture {mode}"));
    let mut stdout = std::io::stdout();
    let _ = if state.env.mouse_capture {
        execute!(stdout, crossterm::event::EnableMouseCapture)
    } else {
        execute!(stdout, crossterm::event::DisableMouseCapture)
    };
}

/// `n` opens the shared nickname editor: this install's own nickname on the
/// Settings tab, or the local display name of the Peer Info tab's peer (the
/// name only this install shows). A no-op on every other tab.
fn handle_nickname_key(s: &mut super::state::AppState, tab: &p2p_app::tui_tabs::TabContent) {
    match tab {
        p2p_app::tui_tabs::TabContent::Settings => {
            s.begin_self_nickname_edit();
            p2plog_debug("Started nickname edit from Settings tab".to_string());
        }
        p2p_app::tui_tabs::TabContent::PeerInfo(peer_id) => {
            s.begin_local_nickname_edit(peer_id.clone());
            p2plog_debug("Started local nickname edit".to_string());
        }
        _ => {}
    }
}

/// Applies a per-peer *local* nickname edit (the name only this install shows
/// for the peer). Invalid input keeps the editor open with a popup, mirroring
/// the canonical Rust rule the other frontends use; a successful edit updates
/// the in-memory display maps and re-sorts the Contacts tab so the new name is
/// reflected immediately.
fn handle_local_nickname_submission(state: &mut super::state::AppState, peer_id: &str) {
    let new_nickname = state.chat_input.lines().join("\n");
    let trimmed = new_nickname.trim();
    if trimmed.is_empty() {
        state.cancel_nickname_edit();
        return;
    }
    if !p2p_app::nickname::validate_nickname(trimmed) {
        state.popup =
            Some("Local nickname: letters, numbers or dashes (max 20 characters)".to_string());
        return;
    }
    match p2p_app::set_peer_local_nickname(peer_id, trimmed) {
        Ok(()) => {
            state
                .local_nicknames
                .insert(peer_id.to_string(), trimmed.to_string());
            state.resort_peers();
            state.popup = None;
            p2plog_debug(format!("Set local nickname for {peer_id}: {trimmed}"));
        }
        Err(e) => p2plog_debug(format!("Failed to set local nickname: {e}")),
    }
    state.cancel_nickname_edit();
}

async fn handle_nickname_submission(
    state: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) {
    if state.is_editing_local_nickname() {
        if let Some(peer_id) = state.editing_nickname_peer.clone() {
            handle_local_nickname_submission(state, &peer_id);
        } else {
            state.cancel_nickname_edit();
        }
        return;
    }
    let Some((new_nickname, old_nickname, peer_id)) = prepare_nickname_update(state) else {
        state.cancel_nickname_edit();
        return;
    };
    // Validate with the canonical Rust rule every other frontend uses, so the
    // TUI cannot persist a nickname a web/mobile client would reject. Keep the
    // editor open with a hint on bad input (same UX as the local-nickname path).
    let new_nickname = new_nickname.trim().to_string();
    if !p2p_app::nickname::validate_nickname(&new_nickname) {
        state.popup = Some("Nickname: letters, numbers or dashes (max 20 characters)".to_string());
        return;
    }

    if let Some(peer_id) = peer_id {
        state
            .self_nicknames_for_peers
            .insert(peer_id.clone(), new_nickname.clone());
        let _ = p2p_app::set_peer_self_nickname_for_peer(&peer_id, &new_nickname);
        let _ = swarm_cmd_tx
            .send(SwarmCommand::SendDm {
                peer_id: peer_id.clone(),
                content: String::new(),
                nickname: Some(new_nickname.clone()),
                msg_id: None,
                ack_for: None,
                attachment: None,
                reply_to: None,
            })
            .await;
        update_dm_transcript_labels(
            &mut state.dm_messages,
            &peer_id,
            &old_nickname,
            &new_nickname,
        );
        p2plog_debug(format!("Updated per-peer nickname to: {new_nickname}"));
    } else {
        state.own_nickname.clone_from(&new_nickname);
        let _ = p2p_app::set_self_nickname(&new_nickname);
        for p in &state.peers {
            let peer_id = &p.peer_id;
            if state.self_nicknames_for_peers.contains_key(peer_id) {
                continue;
            }
            let _ = swarm_cmd_tx
                .send(SwarmCommand::SendDm {
                    peer_id: peer_id.clone(),
                    content: String::new(),
                    nickname: Some(new_nickname.clone()),
                    msg_id: None,
                    ack_for: None,
                    attachment: None,
                    reply_to: None,
                })
                .await;
        }
        let peer_ids: Vec<String> = state.dm_messages.keys().cloned().collect();
        for peer_id in peer_ids {
            if state.self_nicknames_for_peers.contains_key(&peer_id) {
                continue;
            }
            update_dm_transcript_labels(
                &mut state.dm_messages,
                &peer_id,
                &old_nickname,
                &new_nickname,
            );
        }
        p2plog_debug(format!("Updated broadcast nickname to: {new_nickname}"));
    }
    state.popup = None;
    state.cancel_nickname_edit();
}

/// Creates or joins a public group by name: persists it, subscribes to its
/// topic, and opens its chat tab.
async fn create_or_join_group(
    state: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    name: &str,
) {
    match p2p_app::groups::create_public_group(name.trim()) {
        Ok(group) => {
            let group_id = group.group_id.clone();
            let display_name = group.display_name.clone();
            let _ = swarm_cmd_tx
                .send(SwarmCommand::SubscribeGroup {
                    group_id: group_id.clone(),
                })
                .await;
            state.reload_group_summaries();
            state.group_selection = state
                .group_summaries
                .iter()
                .position(|g| g.group.group_id == group_id)
                .unwrap_or(0);
            super::click_handlers::open_group_chat(state, &group_id, &display_name);
            state.input_mode = p2p_app::InputMode::Chat;
            state.chat_input = super::TextArea::default();
            state.popup = None;
            p2plog_debug(format!("Created/joined group: {display_name} ({group_id})"));
        }
        // Rust is the single validation choke point for group names. Keep the
        // prompt open with a hint on bad input (same UX as nickname errors), so
        // the caller can correct the name instead of losing it.
        Err(e) => state.popup = Some(format!("Could not create/join group: {e}")),
    }
}

/// Groups-tab keys: `g` opens the create/join prompt, `d` arms the leave
/// confirmation for the selected group (`y`/Enter confirms). Both are no-ops
/// while a text-input mode is active, which the caller guards.
fn handle_groups_key(c: char, s: &mut super::state::AppState) {
    match c {
        'g' => {
            s.input_mode = p2p_app::InputMode::CreatingGroup;
            s.chat_input = super::TextArea::default();
            p2plog_debug("Started group create/join".to_string());
        }
        'd' => {
            if let Some(group) = s.group_summaries.get(s.group_selection) {
                let group_id = group.group.group_id.clone();
                let display_name = group.group.display_name.clone();
                s.begin_group_leave(group_id, display_name);
                p2plog_debug("Leave group confirmation armed".to_string());
            }
        }
        _ => {}
    }
}

/// Leaves a group after the user confirms: delete the local rows (messages +
/// membership + the group itself) and unsubscribe from its gossipsub topic,
/// close the group's chat tab, and refresh the list. Local-only by design —
/// public groups have no server-side membership to notify, so other members
/// keep their copy of the history (mirrors Flutter's "Leave group").
async fn confirm_group_leave(state: &SharedState, swarm_cmd_tx: &mpsc::Sender<SwarmCommand>) {
    let prompt = {
        let mut s = state.lock().await;
        s.group_leave_prompt.take()
    };
    let Some(prompt) = prompt else {
        return;
    };
    match p2p_app::groups::delete_group(&prompt.group_id) {
        Ok(()) => {
            let _ = swarm_cmd_tx
                .send(SwarmCommand::UnsubscribeGroup {
                    group_id: prompt.group_id.clone(),
                })
                .await;
            state.lock().await.apply_group_leave(&prompt.group_id);
            p2plog_debug(format!(
                "Left group: {} ({})",
                prompt.display_name, prompt.group_id
            ));
        }
        Err(e) => p2plog_debug(format!("Failed to leave group: {e}")),
    }
}

/// `Delete` arms the local-only deletion prompt for the newest sent message in
/// the active chat. Incoming rows and live events have no DB id, so they are
/// skipped; with nothing deletable we explain that in a popup instead.
fn arm_delete_prompt(s: &mut super::state::AppState, tab: &p2p_app::tui_tabs::TabContent) {
    use p2p_app::tui_tabs::TabContent;

    let Some((id, preview)) = s.last_sent_message(tab) else {
        s.popup = Some("No sent message to delete in this conversation".to_string());
        return;
    };
    let is_group = matches!(tab, TabContent::GroupChat(_));
    s.begin_delete_message(id, is_group, preview, tab.clone());
    p2plog_debug(format!("Delete confirmation armed for message {id}"));
}

/// Apply a confirmed local deletion: tombstone the DB row via the shared API,
/// then drop the matching line from the conversation's aligned queues. Nothing
/// is sent over the swarm — other peers keep their copy (US-005).
async fn confirm_delete_message(state: &SharedState) {
    let prompt = {
        let mut s = state.lock().await;
        s.delete_message_prompt.take()
    };
    let Some(prompt) = prompt else {
        return;
    };
    match p2p_app::api::delete_message(prompt.message_id, prompt.is_group) {
        Ok(()) => {
            let mut s = state.lock().await;
            if s.remove_deleted_message(&prompt) {
                p2plog_debug(format!("Deleted message {} locally", prompt.message_id));
            } else {
                // The row vanished from the in-memory queues (e.g. a reload
                // happened while the popup was open); the DB tombstone still
                // applies, so tell the user why nothing was removed on screen.
                s.popup = Some("Message deleted, but its line is no longer loaded".to_string());
            }
        }
        Err(e) => {
            p2plog_debug(format!(
                "Failed to delete message {}: {e}",
                prompt.message_id
            ));
            let mut s = state.lock().await;
            s.popup = Some(format!("Could not delete message: {e}"));
        }
    }
}

/// `Ctrl+E` opens the local-edit editor on the newest sent message in the
/// active chat. Incoming rows and live events have no DB id, so they are
/// skipped; with nothing editable we explain that in a popup. The pre-fill is
/// the persisted body, never the rendered transcript line, so file chips,
/// quote headers and the edit marker cannot leak into the stored text.
fn arm_edit_prompt(s: &mut super::state::AppState, tab: &p2p_app::tui_tabs::TabContent) {
    use p2p_app::tui_tabs::TabContent;

    let Some((id, fallback)) = s.last_sent_message_raw(tab) else {
        s.popup = Some("No sent message to edit in this conversation".to_string());
        return;
    };
    let is_group = matches!(tab, TabContent::GroupChat(_));
    let original = if is_group {
        p2p_app::groups::group_message_body(id)
    } else {
        p2p_app::messages::message_body(id)
    }
    .ok()
    .flatten()
    .unwrap_or(fallback);
    s.begin_edit_message(id, is_group, original, tab.clone());
    p2plog_debug(format!("Local edit opened for message {id}"));
}

/// Open a downloaded attachment with the platform's default handler (parity
/// with Flutter's tappable attachment chip).
///
/// The path is passed as a single argument — never through a shell — and the
/// opener is spawned detached: the input task must not block until the user
/// closes their image viewer. Linux uses `xdg-open`, macOS `open`, and Windows
/// the `start` builtin via `cmd`.
fn open_attachment(path: &str) -> Result<(), String> {
    #[cfg(target_os = "windows")]
    let spawned = std::process::Command::new("cmd")
        .args(["/C", "start", "", path])
        .spawn();
    #[cfg(all(unix, not(target_os = "macos")))]
    let spawned = std::process::Command::new("xdg-open").arg(path).spawn();
    #[cfg(target_os = "macos")]
    let spawned = std::process::Command::new("open").arg(path).spawn();
    spawned
        .map(|_| ())
        .map_err(|e| format!("Could not open attachment '{path}': {e}"))
}

/// Resolve and launch the newest downloaded attachment in `tab`, surfacing a
/// popup when there is nothing to open or the platform opener cannot start.
fn open_newest_attachment(s: &mut super::state::AppState, tab: &p2p_app::tui_tabs::TabContent) {
    let Some(path) = s.newest_attachment_path(tab) else {
        s.popup = Some("No downloaded attachment in this conversation".to_string());
        return;
    };
    if let Err(err) = open_attachment(&path) {
        s.popup = Some(err);
    }
}

/// Apply a confirmed local edit: replace the DB body through the shared API,
/// then refresh the matching in-memory line with the canonical edit marker.
/// Nothing is sent over the swarm — peers keep the original body (US-005).
fn confirm_edit_message(s: &mut super::state::AppState) {
    let Some(prompt) = s.editing_message.clone() else {
        return;
    };
    let content = s
        .chat_input
        .lines()
        .first()
        .map_or_else(String::new, std::string::ToString::to_string)
        .trim()
        .to_string();
    if content.is_empty() {
        s.popup = Some("Message body cannot be empty".to_string());
        return;
    }
    match p2p_app::api::edit_message(prompt.message_id, prompt.is_group, &content) {
        Ok(()) => {
            let applied = s.replace_edited_message(&prompt, &content);
            s.editing_message = None;
            s.input_mode = p2p_app::InputMode::Chat;
            s.chat_input = super::TextArea::default();
            s.popup = None;
            if !applied {
                s.popup = Some("Message edited, but its line is no longer loaded".to_string());
            }
            p2plog_debug(format!("Edited message {} locally", prompt.message_id));
        }
        Err(e) => {
            s.popup = Some(format!("Could not edit message: {e}"));
        }
    }
}

/// Apply one reaction token to the prompt's message. Both the typed custom
/// token and the quick palette go through this single commit path, so
/// validation, persistence, fan-out and chip refresh cannot drift. The local
/// change is applied before the signal is queued, so chips refresh even when
/// the node is offline; a failed queue only delays peer sync.
async fn commit_reaction(
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    raw: &str,
) {
    let Some(prompt) = s.adding_reaction.clone() else {
        return;
    };
    let emoji = match p2p_app::reactions::validate_emoji(raw) {
        Ok(emoji) => emoji,
        Err(e) => {
            s.popup = Some(format!("Invalid reaction: {e}"));
            return;
        }
    };
    let Some(actor) = p2p_app::peers::local_peer_id_string() else {
        s.popup = Some("Local peer id is not available".to_string());
        return;
    };
    // Recipients come from the message's scope, never from the emoji itself.
    let recipients = p2p_app::reactions::recipients_for_message(&prompt.msg_id);
    let remove = match p2p_app::reactions::has_reaction(&prompt.msg_id, &actor, &emoji) {
        Ok(remove) => remove,
        Err(e) => {
            s.popup = Some(format!("Could not read reactions: {e}"));
            return;
        }
    };
    if let Err(e) = p2p_app::reactions::apply(&prompt.msg_id, &actor, &emoji, remove) {
        s.popup = Some(format!("Could not save reaction: {e}"));
        return;
    }
    let action = if remove { "Removed" } else { "Added" };
    s.popup = None;
    if !recipients.is_empty() {
        let _ = swarm_cmd_tx
            .send(SwarmCommand::SendReaction {
                peer_ids: recipients,
                signal: Box::new(p2p_app::behavior::ReactionSignal::new(
                    prompt.msg_id.clone(),
                    emoji.clone(),
                    actor,
                    remove,
                )),
            })
            .await;
    }
    match p2p_app::reactions::summaries_for(&prompt.msg_id) {
        Ok(summaries) => {
            s.reactions.insert(prompt.msg_id.clone(), summaries);
        }
        Err(e) => {
            s.popup = Some(format!("Reaction saved, but chips could not refresh: {e}"));
        }
    }
    s.adding_reaction = None;
    s.input_mode = p2p_app::InputMode::Chat;
    s.chat_input = super::TextArea::default();
    p2plog_debug(format!("{action} reaction {emoji} on {}", prompt.msg_id));
}

/// Apply the emoji typed in the shared editor as a reaction on the newest
/// message of the active chat (US-008).
async fn confirm_reaction(
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) {
    let raw = s.chat_input.lines().join("\n");
    commit_reaction(s, swarm_cmd_tx, &raw).await;
}

/// Apply one of the canonical quick-reaction tokens while the reaction editor
/// owns input. Returns `true` only when a plain `1`–`6` key was consumed, so
/// ordinary chat characters and every modifier chord keep their normal paths.
async fn handle_quick_reaction_key(
    key_event: &crossterm::event::KeyEvent,
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) -> bool {
    if !s.is_adding_reaction() || !key_event.modifiers.is_empty() {
        return false;
    }
    let index = match key_event.code {
        crossterm::event::KeyCode::Char('1') => 0,
        crossterm::event::KeyCode::Char('2') => 1,
        crossterm::event::KeyCode::Char('3') => 2,
        crossterm::event::KeyCode::Char('4') => 3,
        crossterm::event::KeyCode::Char('5') => 4,
        crossterm::event::KeyCode::Char('6') => 5,
        _ => return false,
    };
    let Some(token) = p2p_app::reactions::quick_reaction(index) else {
        return false;
    };
    commit_reaction(s, swarm_cmd_tx, token).await;
    true
}

/// Handles Ctrl+W (close DM or Peer Info tab)
fn handle_close_dm_tab(
    state: &mut super::state::AppState,
    tab_content: &p2p_app::tui_tabs::TabContent,
) {
    if let p2p_app::tui_tabs::TabContent::Direct(peer_id) = tab_content {
        state.clear_typing(peer_id);
    }
    if let Some(closed_idx) = state.dynamic_tabs.remove_tab(tab_content) {
        let next_tab = if closed_idx > 0 {
            closed_idx.saturating_sub(1)
        } else {
            0
        };
        state.switch_to_tab(next_tab);
        state.peer_selection = 0;
        p2plog_debug(format!("Closed tab: {tab_content:?}"));
    }
}

/// Queue a call signal to `peer_id` on the calls lane (invite/accept/reject/
/// end; the session id is echoed by every kind).
async fn send_call_signal(
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    peer_id: &str,
    call_id: &str,
    kind: &str,
) {
    let _ = swarm_cmd_tx
        .send(SwarmCommand::SendCallSignal {
            peer_id: peer_id.to_string(),
            signal: Box::new(p2p_app::CallSignal::new(kind, call_id.to_string())),
        })
        .await;
}

/// Place an outgoing call to `peer_id`: mint a fresh session and send its
/// invite. A no-op while a call is already active (one session at a time).
async fn start_call_to_peer(
    state: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    peer_id: &str,
) {
    if state
        .call_session
        .as_ref()
        .is_some_and(p2p_app::CallSession::is_active)
    {
        p2plog_debug("Call already active; ignoring new ring".to_string());
        return;
    }
    let session = p2p_app::CallSession::outgoing(peer_id);
    let call_id = session.call_id.clone();
    send_call_signal(swarm_cmd_tx, peer_id, &call_id, "invite").await;
    state.call_session = Some(session);
    state.call_media = CallMediaStatus::default();
    p2plog_debug(format!("Placing call to {peer_id} ({call_id})"));
}

/// `c` starts a call to the peer targeted by `tab`: the selected
/// contact/device on the Contacts tab, or the Peer Info owner.
async fn start_call_for_tab(
    tab: &p2p_app::tui_tabs::TabContent,
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) {
    if let Some(peer_id) = match tab {
        p2p_app::tui_tabs::TabContent::Contacts => s.selected_contact_peer_id(),
        p2p_app::tui_tabs::TabContent::PeerInfo(pid) => Some(pid.clone()),
        _ => None,
    } {
        start_call_to_peer(s, swarm_cmd_tx, &peer_id).await;
    }
}

/// Route a key to the active call overlay. A live session swallows all input
/// until it resolves (mirrors the device-binding prompt):
///   * `Ringing` — `a`/`A` accepts; any other key (Esc included) declines.
///   * `Calling` — `c`/`C`/Esc cancels the outgoing ring; other keys ignored.
///   * `InCall`  — `m`/`M` toggles the mic mute, Esc hangs up; other keys ignored.
///
/// Always consumes the key (the caller short-circuits before generic dispatch).
async fn handle_call_overlay_key(
    key_event: &crossterm::event::KeyEvent,
    state: &SharedState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    render_tx: &mpsc::Sender<RenderEvent>,
) {
    let s = state.lock().await;
    let Some(session) = s.call_session.as_ref() else {
        return;
    };
    let (call_id, peer_id, call_state) = (
        session.call_id.clone(),
        session.peer_id.clone(),
        session.state,
    );
    drop(s);

    match call_state {
        p2p_app::CallState::Ringing => {
            let accept = matches!(key_event.code, crossterm::event::KeyCode::Char('a' | 'A'));
            let kind = if accept { "accept" } else { "reject" };
            let mut s = state.lock().await;
            if accept {
                if let Some(session) = s.call_session.as_mut() {
                    session.on_signal(&p2p_app::CallSignal::new(kind, call_id.clone()));
                }
            } else {
                s.call_session = None;
            }
            drop(s);
            send_call_signal(swarm_cmd_tx, &peer_id, &call_id, kind).await;
            if accept {
                // Opening the media session on accept (rather than on invite)
                // pins sender/receiver call ids before any frame can arrive.
                let _ = swarm_cmd_tx
                    .send(SwarmCommand::StartCallMedia {
                        call_id: call_id.clone(),
                        peer_id: peer_id.clone(),
                    })
                    .await;
                // Start the device adapter only after the session command is
                // queued, so an early capture frame cannot be dropped.
                let s = state.lock().await;
                s.call_audio.start(&call_id, &peer_id, swarm_cmd_tx);
                drop(s);
            }
            p2plog_debug(if accept {
                format!("Accepted call {call_id}")
            } else {
                format!("Declined call {call_id} (ringing)")
            });
        }
        p2p_app::CallState::Calling => {
            let is_esc = key_event.code == crossterm::event::KeyCode::Esc;
            let cancel =
                is_esc || matches!(key_event.code, crossterm::event::KeyCode::Char('c' | 'C'));
            if cancel {
                let mut s = state.lock().await;
                s.call_session = None;
                s.call_audio.stop();
                drop(s);
                send_call_signal(swarm_cmd_tx, &peer_id, &call_id, "end").await;
                let _ = swarm_cmd_tx.send(SwarmCommand::StopCallMedia).await;
                p2plog_debug(format!("Cancelled outgoing call {call_id}"));
            }
        }
        p2p_app::CallState::InCall => {
            if matches!(key_event.code, crossterm::event::KeyCode::Char('m' | 'M')) {
                let mut s = state.lock().await;
                let muted = !s.call_media.muted;
                s.call_media.muted = muted;
                drop(s);
                let _ = swarm_cmd_tx
                    .send(SwarmCommand::SetCallMediaMute { muted })
                    .await;
                p2plog_debug(format!(
                    "Call {call_id} mic {}",
                    if muted { "muted" } else { "unmuted" }
                ));
            } else if key_event.code == crossterm::event::KeyCode::Esc {
                let mut s = state.lock().await;
                s.call_session = None;
                s.call_media = CallMediaStatus::default();
                s.call_audio.stop();
                drop(s);
                send_call_signal(swarm_cmd_tx, &peer_id, &call_id, "end").await;
                let _ = swarm_cmd_tx.send(SwarmCommand::StopCallMedia).await;
                p2plog_debug(format!("Hanging up call {call_id}"));
            }
        }
        p2p_app::CallState::Ended => {}
    }
    let _ = render_tx.send(RenderEvent).await;
}

/// Handles Esc one level at a time: dismiss popup / cancel edit / clear
/// Contacts search / return to broadcast chat.
///
/// Device-binding, group-leave and delete prompts own Esc upstream in
/// `prompt_key_action`, so they must not be cancelled again here.
async fn handle_esc_key(state: &SharedState, render_tx: &mpsc::Sender<RenderEvent>) {
    let mut s = state.lock().await;
    if dismiss_popup(&mut s) {
        p2plog_debug("Dismissed popup".to_string());
        drop(s);
        let _ = render_tx.send(RenderEvent).await;
        return;
    }
    if s.cancel_edit_message() {
        p2plog_debug("Cancelled message edit".to_string());
    } else if s.cancel_reaction() {
        p2plog_debug("Cancelled reaction".to_string());
    } else if s.is_searching_contacts() {
        s.end_contact_search(false);
        p2plog_debug("Cleared Contacts search".to_string());
    } else if s.is_editing_nickname() {
        s.cancel_nickname_edit();
        p2plog_debug("Cancelled nickname edit".to_string());
    } else if s.is_creating_group() {
        s.cancel_group_create();
        p2plog_debug("Cancelled group create/join".to_string());
    } else if s.is_dialing_peer() {
        s.cancel_dial_peer();
        p2plog_debug("Cancelled peer dial".to_string());
    } else if s.is_adding_network_peer() {
        s.cancel_add_network_peer();
        p2plog_debug("Cancelled network peer entry".to_string());
    } else {
        let tab = s.dynamic_tabs.tab_index_to_content(s.active_tab);
        if s.clear_reply(&tab) {
            p2plog_debug("Cleared reply draft".to_string());
        } else {
            s.switch_to_tab(0);
            s.chat_scroll_offset = 0;
            s.auto_scroll.chat = true;
            s.mark_broadcast_viewed();
            p2plog_debug("Returned to Broadcast Chat (Esc)".to_string());
        }
    }
    drop(s);
    let _ = render_tx.send(RenderEvent).await;
}

/// Decline the active device-binding prompt (leaves the peer unbound). Also
/// used by the generic popup dismiss and Esc paths so the prompt can never
/// linger after the popup is gone.
pub fn decline_device_binding_prompt(state: &mut super::state::AppState) {
    if state.device_binding_prompt.take().is_some() {
        p2plog_debug("Declined device-binding intro".to_string());
    }
}

/// Accept the active device-binding prompt: mint a signed claim binding the
/// intro's device into this install's user, persist it locally, and send the
/// claim back over the swarm. On mint failure (e.g. the install has no
/// account) the prompt is cleared and the error is surfaced in a popup.
pub async fn accept_device_binding_prompt(
    state: &SharedState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) {
    let prompt = {
        let mut s = state.lock().await;
        s.device_binding_prompt.take()
    };
    let Some(prompt) = prompt else {
        return;
    };
    match p2p_app::identity::mint_device_binding(&prompt.peer_id, &prompt.device_pubkey) {
        Ok(request) => {
            let _ = swarm_cmd_tx
                .send(SwarmCommand::SendDeviceBinding {
                    peer_id: prompt.peer_id.clone(),
                    request: Box::new(request),
                })
                .await;
            p2plog_debug(format!(
                "Accepted device-binding intro from {}",
                p2p_app::fmt::peer_id_suffix(&prompt.peer_id)
            ));
            // Accepting bound the intro's device into our user: refresh the
            // identity/settings display (device-set grew).
            let mut s = state.lock().await;
            s.refresh_my_user();
        }
        Err(e) => {
            p2plog_debug(format!("Failed to accept device binding: {e}"));
            let mut s = state.lock().await;
            s.popup = Some(format!(
                "Could not accept device binding from {}: {e}",
                p2p_app::fmt::peer_id_suffix(&prompt.peer_id)
            ));
        }
    }
}

/// Opens the Peer Info tab for the current tab's target peer (see
/// [`super::state::AppState::peer_info_target`]). Returns `false` when the
/// active tab has no peer to inspect, so callers can avoid a misleading log.
fn open_peer_info_for_active_tab(state: &mut super::state::AppState) -> bool {
    let tab_content = state.dynamic_tabs.tab_index_to_content(state.active_tab);
    let Some(peer_id) = state.peer_info_target(&tab_content) else {
        return false;
    };
    let tab_idx = state.dynamic_tabs.add_peer_info_tab(peer_id);
    state.switch_to_tab(tab_idx);
    true
}

/// Sets the peers-table sort column, toggling direction if the same column is
/// chosen again (mirroring Flutter's `_PeerList` header tap behavior), and
/// re-sorts the peer list while preserving the selected peer.
fn apply_peer_sort(state: &mut super::state::AppState, column: usize) {
    if state.peer_sort_column == column {
        state.peer_sort_ascending = !state.peer_sort_ascending;
    } else {
        state.peer_sort_column = column;
        state.peer_sort_ascending = false;
    }
    state.resort_peers();
}

/// Dispatches a peer-list sort key (`1`-`5`, `n`/`m`/`b`/`l`/`f` for columns,
/// `o` to toggle direction) when the Contacts tab is active.
fn handle_peer_sort_key(state: &mut super::state::AppState, c: char) {
    match c {
        '1' | 'n' | 'N' => apply_peer_sort(state, 0),
        '2' | 'm' | 'M' => apply_peer_sort(state, 1),
        '3' | 'b' | 'B' => apply_peer_sort(state, 2),
        '4' | 'l' | 'L' => apply_peer_sort(state, 3),
        '5' | 'f' | 'F' => apply_peer_sort(state, 4),
        'o' | 'O' => {
            state.peer_sort_ascending = !state.peer_sort_ascending;
            state.resort_peers();
        }
        _ => {}
    }
}

/// Handles Enter key (send message or multi-line input)
async fn handle_enter_key(
    state: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    shift_held: bool,
    tab_content: p2p_app::tui_tabs::TabContent,
) {
    if shift_held {
        if tab_content.is_input_enabled() {
            state.chat_input.insert_str("\n");
        }
    } else if matches!(tab_content, p2p_app::tui_tabs::TabContent::Contacts) {
        if let Some(peer_id) = state.selected_contact_peer_id() {
            load_dm_messages(state, &peer_id);
            let tab_idx = state.dynamic_tabs.add_dm_tab(peer_id.clone());
            state.switch_to_tab(tab_idx);
            p2plog_debug(format!("Opened DM with peer: {peer_id}"));
        }
    } else if matches!(tab_content, p2p_app::tui_tabs::TabContent::Groups) {
        if let Some(group) = state.group_summaries.get(state.group_selection) {
            let group_id = group.group.group_id.clone();
            let display_name = group.group.display_name.clone();
            super::click_handlers::open_group_chat(state, &group_id, &display_name);
            p2plog_debug(format!("Opened group: {display_name}"));
        }
    } else if let p2p_app::tui_tabs::TabContent::PeerInfo(peer_id) = &tab_content {
        load_dm_messages(state, peer_id);
        let tab_idx = state.dynamic_tabs.add_dm_tab(peer_id.clone());
        state.switch_to_tab(tab_idx);
        p2plog_debug(format!("Opened DM with peer: {peer_id}"));
    } else if tab_content.is_input_enabled() {
        let text: String = state.chat_input.lines().join("\n");
        let trimmed = text.trim_start();
        if trimmed.starts_with("/file ") {
            match parse_file_command(&text) {
                Some(path) => {
                    super::message_handlers::send_file_message(
                        state,
                        swarm_cmd_tx,
                        &path,
                        tab_content,
                    )
                    .await;
                }
                None => state.popup = Some("Usage: /file <path>".to_string()),
            }
        } else if !text.trim().is_empty() {
            super::message_handlers::send_message(state, swarm_cmd_tx, text, None, tab_content)
                .await;
        }
    }
}

/// Pure: parse a `/file` chat command into a path (files lane §12). Comments
/// out of any ordinary message; only an actual `/file <path>` with a non-blank
/// path returns `Some`, everything else stays `None` so it passes through the
/// normal send path.
fn parse_file_command(input: &str) -> Option<String> {
    input
        .trim_start()
        .strip_prefix("/file ")
        .map(str::trim)
        .filter(|path| !path.is_empty())
        .map(str::to_owned)
}

/// Open the active tab's Peer Info target for a `Ctrl+I` / `Ctrl+P` chord.
///
/// `Ctrl+P` is the cross-terminal, tab-agnostic binding: `p` is 0x70, so
/// Ctrl+P sends 0x10 (`DLE`), a distinct control byte crossterm uniformly
/// reports as `Char('p')`+CONTROL (the `b'\x01'..=b'\x1A'` arm) whether or not
/// the kitty protocol is active. `Ctrl+I` works only on kitty terminals
/// (`WezTerm`) and only on a Direct tab; on non-kitty terminals Ctrl+I
/// collapses to the bare Tab byte, which always cycles tabs (see
/// [`process_key_event`]).
fn handle_peer_info_control_chord(
    key_event: &crossterm::event::KeyEvent,
    s: &mut super::state::AppState,
) {
    let chord = if key_event.code == crossterm::event::KeyCode::Char('p') {
        "Ctrl+P"
    } else {
        "Ctrl+I"
    };
    if open_peer_info_for_active_tab(s) {
        p2plog_debug(format!("Opened Peer Info tab ({chord})"));
    } else {
        p2plog_debug(format!("Peer Info {chord} ignored (no peer on this tab)"));
    }
}

/// Processes keyboard input events, returns the exit signal (true = quit).
///
/// Early-out handling (Esc, Ctrl+Q, the device-binding prompt, popup
/// dismissal) happens here before the key is dispatched; the actual dispatch
/// against the active tab lives in [`handle_key_dispatch`].
/// Submit a peer multiaddr entered in the dial prompt (Settings tab).
async fn handle_dial_peer_submission(
    state: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) {
    let address = state.chat_input.lines().join("\n").trim().to_string();
    state.cancel_dial_peer();
    if address.is_empty() {
        return;
    }
    let _ = swarm_cmd_tx
        .send(SwarmCommand::Dial {
            address: address.clone(),
        })
        .await;
    p2plog_debug(format!("Dialing peer: {address}"));
}

/// Settings-tab single-key shortcuts: `n` edits this install's nickname,
/// `d` begins a peer dial, `b`/`r` open the network-peer add prompt for a
/// bootstrap/relay multiaddr, `x` removes the highlighted entry, `l` toggles
/// LAN-only mode. Other chars fall through to the input box.
fn handle_settings_shortcut(c: char, s: &mut super::state::AppState) {
    match c {
        'n' => handle_nickname_key(s, &p2p_app::tui_tabs::TabContent::Settings),
        'l' => toggle_lan_only(s),
        't' => toggle_theme_dark(s),
        'c' => cycle_theme_accent(s),
        's' => toggle_notification_sound(s),
        'o' => toggle_notification_desktop(s),
        'd' if !s.is_dialing_peer() => {
            s.begin_dial_peer();
            p2plog_debug("Started peer dial".to_string());
        }
        'b' => {
            s.begin_add_network_peer(p2p_app::network_config::NetworkPeerKind::Bootstrap);
            p2plog_debug("Started bootstrap multiaddr entry".to_string());
        }
        'r' => {
            s.begin_add_network_peer(p2p_app::network_config::NetworkPeerKind::Relay);
            p2plog_debug("Started relay multiaddr entry".to_string());
        }
        'x' => remove_selected_network_peer(s),
        _ => {}
    }
}

/// Submit the Settings add-network-peer prompt: validate + persist via the
/// canonical [`p2p_app::network_config::add_network_peer`] path, then reload
/// the list. Validation failures surface in a popup (same as nickname errors).
fn handle_add_network_peer_submission(s: &mut super::state::AppState) {
    let kind = s.network_peer_kind;
    let address = s.chat_input.lines().join("\n").trim().to_string();
    let Some(kind) = kind else {
        return;
    };
    if address.is_empty() {
        s.cancel_add_network_peer();
        return;
    }
    match p2p_app::network_config::add_network_peer(kind.as_str(), &address) {
        Ok(peer) => {
            // Only a successful submit closes the prompt. A rejected address
            // keeps the text so the next correction key can edit it, matching
            // the nickname and group-name prompts.
            s.cancel_add_network_peer();
            p2plog_debug(format!(
                "Saved {} network peer: {}",
                peer.kind, peer.multiaddr
            ));
            s.reload_network_peers();
            s.network_peer_selection = s
                .network_peers
                .iter()
                .position(|row| row.id == peer.id)
                .unwrap_or(s.network_peer_selection);
        }
        Err(error) => {
            s.popup = Some(format!("Network peer not saved: {error}"));
        }
    }
}

/// Toggle LAN-only mode (Settings `l`), persisting via the canonical settings
/// accessor. Applies on next node start; the current run keeps its wiring.
fn toggle_lan_only(s: &mut super::state::AppState) {
    let next = !p2p_app::settings::lan_only();
    match p2p_app::settings::set_lan_only(next) {
        Ok(()) => p2plog_debug(format!("LAN-only mode set to {next}")),
        Err(error) => s.popup = Some(format!("LAN-only setting not saved: {error}")),
    }
}

/// Toggle the notification sound channel (Settings `s`). Persist via the
/// canonical notification accessor so TUI and Flutter share one setting.
fn toggle_notification_sound(s: &mut super::state::AppState) {
    let next = !p2p_app::settings::notification_sound();
    match p2p_app::notifications::set_settings(next, p2p_app::settings::notification_desktop()) {
        Ok(()) => p2plog_debug(format!("Notification sound set to {next}")),
        Err(error) => s.popup = Some(format!("Notification setting not saved: {error}")),
    }
}

/// Toggle the desktop-notification channel (Settings `o`). Same persistence
/// path as [`toggle_notification_sound`].
fn toggle_notification_desktop(s: &mut super::state::AppState) {
    let next = !p2p_app::settings::notification_desktop();
    match p2p_app::notifications::set_settings(p2p_app::settings::notification_sound(), next) {
        Ok(()) => p2plog_debug(format!("Desktop notifications set to {next}")),
        Err(error) => s.popup = Some(format!("Notification setting not saved: {error}")),
    }
}

/// Toggle dark/light (Settings `t`). Persist via the canonical theme accessor
/// and update the in-memory palette immediately so the next frame reflects it.
fn toggle_theme_dark(s: &mut super::state::AppState) {
    let next = !s.palette.dark;
    match p2p_app::theme::set(next, s.palette.accent.as_str()) {
        Ok(()) => {
            s.palette.dark = next;
            p2plog_debug(format!("Theme set to dark={next}"));
        }
        Err(error) => s.popup = Some(format!("Theme not saved: {error}")),
    }
}

/// Cycle the accent colour (Settings `c`), same persistence + immediate update
/// as [`toggle_theme_dark`].
fn cycle_theme_accent(s: &mut super::state::AppState) {
    let next = s.palette.accent.next();
    match p2p_app::theme::set(s.palette.dark, next.as_str()) {
        Ok(()) => {
            s.palette.accent = next;
            p2plog_debug(format!("Accent set to {}", next.as_str()));
        }
        Err(error) => s.popup = Some(format!("Theme not saved: {error}")),
    }
}

/// Remove the highlighted persisted network peer (Settings `x`).
fn remove_selected_network_peer(s: &mut super::state::AppState) {
    let Some(peer) = s.network_peers.get(s.network_peer_selection).cloned() else {
        return;
    };
    match p2p_app::network_config::remove_network_peer(peer.id) {
        Ok(true) => {
            p2plog_debug(format!(
                "Removed {} network peer: {}",
                peer.kind, peer.multiaddr
            ));
            s.reload_network_peers();
        }
        Ok(false) => {}
        Err(error) => {
            s.popup = Some(format!("Network peer not removed: {error}"));
        }
    }
}

/// Which single-slot prompt (if any) owns the current key.
#[derive(Clone, Copy)]
enum PromptAction {
    AcceptDeviceBinding,
    DeclineDeviceBinding,
    ConfirmGroupLeave,
    CancelGroupLeave,
    ConfirmDelete,
    CancelDelete,
    NoPrompt,
}

/// Resolve prompt precedence once: device binding > group leave > deletion.
/// Every prompt owns its keys (including Esc), so nothing below sees them.
const fn prompt_key_action(
    state: &super::state::AppState,
    key_event: &crossterm::event::KeyEvent,
) -> PromptAction {
    use crossterm::event::KeyCode;

    let is_confirm = matches!(key_event.code, KeyCode::Char('y' | 'Y') | KeyCode::Enter);
    if state.device_binding_prompt.is_some() {
        return if matches!(key_event.code, KeyCode::Char('a' | 'A')) {
            PromptAction::AcceptDeviceBinding
        } else {
            PromptAction::DeclineDeviceBinding
        };
    }
    if state.group_leave_prompt.is_some() {
        return if is_confirm {
            PromptAction::ConfirmGroupLeave
        } else {
            PromptAction::CancelGroupLeave
        };
    }
    if state.delete_message_prompt.is_some() {
        return if is_confirm {
            PromptAction::ConfirmDelete
        } else {
            PromptAction::CancelDelete
        };
    }
    PromptAction::NoPrompt
}

async fn process_key_event(
    key_event: crossterm::event::KeyEvent,
    state: &SharedState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    render_tx: &mpsc::Sender<RenderEvent>,
) -> bool {
    if key_event
        .modifiers
        .contains(crossterm::event::KeyModifiers::CONTROL)
        && key_event.code == crossterm::event::KeyCode::Char('q')
    {
        p2plog_debug("Exit signal received".to_string());
        return true;
    }

    // Prompt precedence: device-binding > group leave > message deletion >
    // live call overlay > plain popup/Esc handling.
    let prompt_action = {
        let s = state.lock().await;
        prompt_key_action(&s, &key_event)
    };
    match prompt_action {
        PromptAction::AcceptDeviceBinding => {
            accept_device_binding_prompt(state, swarm_cmd_tx).await;
            let _ = render_tx.send(RenderEvent).await;
            return false;
        }
        PromptAction::DeclineDeviceBinding => {
            let mut s = state.lock().await;
            decline_device_binding_prompt(&mut s);
            drop(s);
            let _ = render_tx.send(RenderEvent).await;
            return false;
        }
        PromptAction::ConfirmGroupLeave => {
            confirm_group_leave(state, swarm_cmd_tx).await;
            let _ = render_tx.send(RenderEvent).await;
            return false;
        }
        PromptAction::CancelGroupLeave => {
            let mut s = state.lock().await;
            if s.cancel_group_leave() {
                p2plog_debug("Cancelled group leave".to_string());
            }
            drop(s);
            let _ = render_tx.send(RenderEvent).await;
            return false;
        }
        PromptAction::ConfirmDelete => {
            confirm_delete_message(state).await;
            let _ = render_tx.send(RenderEvent).await;
            return false;
        }
        PromptAction::CancelDelete => {
            let mut s = state.lock().await;
            if s.cancel_delete_message() {
                p2plog_debug("Cancelled message deletion".to_string());
            }
            drop(s);
            let _ = render_tx.send(RenderEvent).await;
            return false;
        }
        PromptAction::NoPrompt => {}
    }

    // A live call session owns the keys until it resolves: accept/decline a
    // ring, cancel an outgoing call, hang up an active one. Handled before Esc
    // so Esc is a call key here, not the generic dismiss/return-to-chat path.
    let call_active = {
        let s = state.lock().await;
        s.call_session
            .as_ref()
            .is_some_and(p2p_app::CallSession::is_active)
    };
    if call_active {
        handle_call_overlay_key(&key_event, state, swarm_cmd_tx, render_tx).await;
        return false;
    }

    if key_event.code == crossterm::event::KeyCode::Esc {
        handle_esc_key(state, render_tx).await;
        return false;
    }

    let mut s = state.lock().await;

    // Diagnostic: log exactly what crossterm parsed for every input key that
    // touches the Tab/Ctrl+I/Ctrl+P routing, regardless of the kitty flag, so
    // we can tell from the TUI log what the app actually received.
    if matches!(
        key_event.code,
        crossterm::event::KeyCode::Tab
            | crossterm::event::KeyCode::BackTab
            | crossterm::event::KeyCode::Char('i' | 'I' | 'p' | 'P')
    ) {
        p2plog_debug(format!(
            "Key: code={:?} mods={:?}",
            key_event.code, key_event.modifiers
        ));
    }

    // If a popup is open, any key dismisses it (except we still honor exit keys
    // above). Correction keys inside an editor belong to the editor, so they
    // dismiss the validation hint and keep going instead of being swallowed.
    if dismiss_popup(&mut s) && !popup_dismissal_feeds_editor(&key_event, &s) {
        drop(s);
        let _ = render_tx.send(RenderEvent).await;
        return false;
    }

    // `?` opens the modal shortcut table. It is a plain key when no input box
    // owns the keyboard, so prompts/editors/search keep their literal `?`.
    if is_shortcuts_help_key(&key_event) && s.input_mode == p2p_app::InputMode::Chat {
        s.popup = Some(p2p_app::tui_render::shortcuts_help_text().to_string());
        p2plog_debug("Opened shortcut help".to_string());
        drop(s);
        let _ = render_tx.send(RenderEvent).await;
        return false;
    }

    handle_key_dispatch(key_event, &mut s, swarm_cmd_tx).await;
    drop(s);
    let _ = render_tx.send(RenderEvent).await;
    false
}

/// Contacts-tab key handling: opening the search box and the column sorts.
///
/// The search box itself is fed by the dispatch's dedicated arms (it owns every
/// printable key while open), so this only has to distinguish "is the search
/// box opening?" from "is this a sort shortcut?".
fn handle_contacts_tab_key(
    key_event: crossterm::event::KeyEvent,
    is_ctrl: bool,
    s: &mut super::state::AppState,
) {
    if is_ctrl || s.is_modal_editor() {
        return;
    }
    match key_event.code {
        crossterm::event::KeyCode::Char('/') if !s.is_searching_contacts() => {
            s.begin_contact_search();
            p2plog_debug("Searching contacts".to_string());
        }
        crossterm::event::KeyCode::Char(c) if !s.is_searching_contacts() => {
            handle_peer_sort_key(s, c);
        }
        _ => {}
    }
}

/// Feed a key to the Contacts search box while it is open.
///
/// Returns `true` when the key belonged to the box (so the caller's arm can
/// swallow it instead of letting the tab actions or the sort keys see it).
fn handle_contacts_search_edit(
    key_event: crossterm::event::KeyEvent,
    s: &mut super::state::AppState,
) -> bool {
    if !s.is_searching_contacts() {
        return false;
    }
    match key_event.code {
        crossterm::event::KeyCode::Char(c) => {
            s.chat_input.insert_char(c);
        }
        crossterm::event::KeyCode::Backspace => {
            s.chat_input.delete_char();
        }
        _ => return false,
    }
    sync_contact_search(s);
    true
}

/// Re-derive the Contacts filter from the shared search box.
///
/// The box is the single source of the query: every keystroke of the
/// [`p2p_app::InputMode::SearchingContacts`] mode lands here.
fn sync_contact_search(s: &mut super::state::AppState) {
    let query = s.chat_input.lines().join("\n");
    s.set_contact_search(&query);
}

/// Dispatch a fully-unlocked key event against the active tab.
///
/// Tab lookups and modifier flags are computed once up front; shared
/// terminal-key semantics (Ctrl+I / Ctrl+P vs bare Tab) live with
/// [`handle_peer_info_control_chord`]. The match itself only routes to the
/// focused helpers so no single function owns every frontend shortcut.
async fn handle_key_dispatch(
    key_event: crossterm::event::KeyEvent,
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) {
    let is_ctrl = key_event
        .modifiers
        .contains(crossterm::event::KeyModifiers::CONTROL);
    let shift_held = key_event
        .modifiers
        .contains(crossterm::event::KeyModifiers::SHIFT);
    let tab = s.dynamic_tabs.tab_index_to_content(s.active_tab);
    let on_contacts = matches!(&tab, p2p_app::tui_tabs::TabContent::Contacts);
    let on_peer_info = matches!(&tab, p2p_app::tui_tabs::TabContent::PeerInfo(_));
    let on_direct = matches!(&tab, p2p_app::tui_tabs::TabContent::Direct(_));
    let dm_peer_id = match &tab {
        p2p_app::tui_tabs::TabContent::Direct(peer_id) => Some(peer_id.clone()),
        _ => None,
    };
    let input_enabled = tab.is_input_enabled();

    if handle_global_navigation(&key_event, is_ctrl, on_direct, s).await {
        return;
    }
    if handle_quick_reaction_key(&key_event, s, swarm_cmd_tx).await {
        return;
    }
    if handle_clipboard_shortcut(key_event.code, is_ctrl, s, &tab) {
        return;
    }
    if handle_chat_action_shortcut(key_event.code, is_ctrl, s, &tab) {
        return;
    }

    match key_event.code {
        crossterm::event::KeyCode::Enter => {
            handle_enter_dispatch(s, swarm_cmd_tx, shift_held, tab).await;
        }
        crossterm::event::KeyCode::Char('w') if is_ctrl => {
            if let Some(peer_id) = dm_peer_id.as_deref() {
                super::message_handlers::send_typing(s, swarm_cmd_tx, peer_id, false);
            }
            handle_close_dm_tab(s, &tab);
        }
        // The Contacts search box owns every printable key while it is open, so
        // typing `c`/`e`/`i` edits the query instead of triggering their
        // Contacts actions (checked below).
        crossterm::event::KeyCode::Char(_) | crossterm::event::KeyCode::Backspace
            if !is_ctrl && on_contacts && handle_contacts_search_edit(key_event, s) => {}
        crossterm::event::KeyCode::Char(_)
            if !is_ctrl
                && !s.is_modal_editor()
                && (on_contacts || on_peer_info)
                && handle_contacts_action_key(
                    key_event,
                    is_ctrl,
                    on_contacts,
                    &tab,
                    s,
                    swarm_cmd_tx,
                )
                .await => {}
        crossterm::event::KeyCode::Char(_)
            if !is_ctrl
                && !s.is_modal_editor()
                && (on_peer_info
                    || matches!(
                        &tab,
                        p2p_app::tui_tabs::TabContent::Settings
                            | p2p_app::tui_tabs::TabContent::Groups
                            | p2p_app::tui_tabs::TabContent::Log
                    ))
                && handle_tab_specific_shortcut(key_event.code, s, &tab) => {}
        // Remaining Contacts-tab keys: `/` opens the search box (which then owns
        // every keystroke, so typing never re-sorts) and anything else is a
        // column-sort shortcut; `e`/`i`/`c` were handled above.
        crossterm::event::KeyCode::Char(_) | crossterm::event::KeyCode::Backspace
            if on_contacts && !s.is_modal_editor() =>
        {
            handle_contacts_tab_key(key_event, is_ctrl, s);
        }
        _ => {
            handle_default_input(
                key_event,
                s,
                swarm_cmd_tx,
                dm_peer_id.as_deref(),
                input_enabled,
            );
        }
    }
}

/// Terminal-level keys: the Peer Info control chords, tab cycling, scrolling
/// and F12's mouse-capture toggle. Returns `true` when the key was consumed.
async fn handle_global_navigation(
    key_event: &crossterm::event::KeyEvent,
    is_ctrl: bool,
    on_direct: bool,
    s: &mut super::state::AppState,
) -> bool {
    let editing = s.is_modal_editor();
    match key_event.code {
        // Ctrl+P is universal: it opens the active tab's Peer Info target when
        // there is one and is consumed everywhere (never literal 'p' text).
        crossterm::event::KeyCode::Char('p') if !editing && is_ctrl => {
            handle_peer_info_control_chord(key_event, s);
            return true;
        }
        // Ctrl+I stays Direct-only and kitty-only. On other tabs it falls
        // through to the chat-input branch, as before.
        crossterm::event::KeyCode::Char('i') if !editing && is_ctrl && on_direct => {
            handle_peer_info_control_chord(key_event, s);
            return true;
        }
        crossterm::event::KeyCode::BackTab => {
            if !editing {
                handle_navigation_key(key_event.code, s).await;
            }
            return true;
        }
        // Tab carries two meanings: bare Tab cycles tabs on every terminal (a
        // bare 0x09 — Ctrl+I collapses to the same byte on non-kitty terminals,
        // but there Ctrl+P is the distinct Peer Info binding instead, so Tab is
        // always free to cycle). Tab+CONTROL is the CSI-u spelling of Ctrl+I on
        // terminals that send it as an explicitly-modified Tab; it is a no-op.
        crossterm::event::KeyCode::Tab => {
            if editing {
                // A prompt keeps the keyboard: cycling tabs here would leave
                // the prompt armed on a different tab, where Enter can commit
                // it with no visible input box.
                return true;
            }
            if is_ctrl {
                p2plog_debug("Ctrl+I (Tab+CONTROL) ignored: no-op on this tab".to_string());
            } else {
                handle_navigation_key(key_event.code, s).await;
            }
            return true;
        }
        crossterm::event::KeyCode::Up
        | crossterm::event::KeyCode::Down
        | crossterm::event::KeyCode::PageUp
        | crossterm::event::KeyCode::PageDown
        | crossterm::event::KeyCode::Home
        | crossterm::event::KeyCode::End => {
            if !editing {
                handle_scroll_key(key_event.code, s).await;
            }
            return true;
        }
        crossterm::event::KeyCode::F(12) => {
            toggle_mouse_capture(s);
            return true;
        }
        _ => {}
    }
    false
}

/// `Ctrl+C` clipboard ownership, shared by chat tabs and the Log tab so the
/// policy lives in one place: copy the newest rendered message on a chat tab
/// (the same row `Ctrl+R`/`Ctrl+Y` target), or every log line on the Log tab —
/// Flutter's "Copy All". Raw mode delivers `Ctrl+C` as a key event, not SIGINT,
/// and the render loop emits queued sequences after the frame so stdout stays
/// single-threaded. Returns `true` when the key was consumed.
fn handle_clipboard_shortcut(
    code: crossterm::event::KeyCode,
    is_ctrl: bool,
    s: &mut super::state::AppState,
    tab: &p2p_app::tui_tabs::TabContent,
) -> bool {
    use p2p_app::tui_tabs::TabContent;

    if !is_ctrl || code != crossterm::event::KeyCode::Char('c') {
        return false;
    }
    match tab {
        TabContent::Log => {
            if let Some(payload) = p2p_app::clipboard::copy_all_logs(&p2p_app::get_tui_logs()) {
                s.pending_clipboard.push(payload);
                p2plog_debug("Copied all logs to clipboard".to_string());
            }
            true
        }
        TabContent::Chat | TabContent::Direct(_) | TabContent::GroupChat(_)
            if s.input_mode == p2p_app::InputMode::Chat =>
        {
            if let Some(line) = s.newest_message_line(tab) {
                s.pending_clipboard.push(line);
                p2plog_debug("Copied newest message to clipboard".to_string());
            }
            true
        }
        // Keep `c` available to the tab's own shortcuts (and to text editors)
        // everywhere else.
        _ => false,
    }
}

/// Chat composer actions that must not consume a bare printable key.
/// Returns `true` when the key was consumed.
fn handle_chat_action_shortcut(
    code: crossterm::event::KeyCode,
    is_ctrl: bool,
    s: &mut super::state::AppState,
    tab: &p2p_app::tui_tabs::TabContent,
) -> bool {
    let in_chat = s.input_mode == p2p_app::InputMode::Chat
        && matches!(
            tab,
            p2p_app::tui_tabs::TabContent::Chat
                | p2p_app::tui_tabs::TabContent::Direct(_)
                | p2p_app::tui_tabs::TabContent::GroupChat(_)
        );
    if !in_chat {
        return false;
    }
    match code {
        // `Ctrl+R` captures the newest replyable message in a chat as this
        // conversation's reply draft; `Esc` clears it, and sending consumes it.
        crossterm::event::KeyCode::Char('r') if is_ctrl => {
            if let Some(reply) = s.begin_reply(tab) {
                p2plog_debug(format!("Replying to {}", reply.msg_id));
            }
        }
        // `Delete` arms local-only deletion of the newest sent message in a
        // chat. Text editors and the Contacts/Settings/Groups tabs don't own a
        // message queue, so the key is a no-op there.
        crossterm::event::KeyCode::Delete => arm_delete_prompt(s, tab),
        // `Ctrl+E` opens the local-edit editor for the newest sent message in a
        // chat. A bare printable key would swallow the letter while composing.
        crossterm::event::KeyCode::Char('e') if is_ctrl => arm_edit_prompt(s, tab),
        // `Ctrl+Y` opens the shared emoji editor for a reaction on the newest
        // message in a chat (US-008). Any message with a stable wire id can be
        // reacted to, incoming rows included, unlike local edit/delete.
        crossterm::event::KeyCode::Char('y') if is_ctrl => {
            if s.begin_reaction(tab) {
                p2plog_debug("Reaction editor opened".to_string());
            } else {
                s.popup = Some("No message to react to in this conversation".to_string());
            }
        }
        // `Ctrl+O` opens the newest downloaded attachment in a chat, matching
        // Flutter's tappable attachment chip. Bare `o` is a Settings toggle, so
        // the modifier keeps the chat composer untouched.
        crossterm::event::KeyCode::Char('o') if is_ctrl => open_newest_attachment(s, tab),
        // `Ctrl+C` is owned by `handle_clipboard_shortcut`, which runs first so
        // it can also serve the Log tab without this function's chat-only guard.
        _ => return false,
    }
    true
}

/// Enter commits whichever editor or prompt is open, or sends the draft.
async fn handle_enter_dispatch(
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    shift_held: bool,
    tab: p2p_app::tui_tabs::TabContent,
) {
    if s.is_searching_contacts() {
        s.end_contact_search(true);
        p2plog_debug("Applied Contacts search".to_string());
    } else if s.is_editing_nickname() {
        handle_nickname_submission(s, swarm_cmd_tx).await;
    } else if s.is_editing_message() {
        confirm_edit_message(s);
    } else if s.is_adding_reaction() {
        confirm_reaction(s, swarm_cmd_tx).await;
    } else if s.is_creating_group() {
        let name = s.chat_input.lines().join("\n");
        create_or_join_group(s, swarm_cmd_tx, &name).await;
    } else if s.is_dialing_peer() {
        handle_dial_peer_submission(s, swarm_cmd_tx).await;
    } else if s.is_adding_network_peer() {
        handle_add_network_peer_submission(s);
    } else {
        handle_enter_key(s, swarm_cmd_tx, shift_held, tab).await;
    }
}

/// Shortcuts owned by Peer Info, Settings, Groups and Log (in that order of
/// precedence). Returns `true` when the key was consumed.
fn handle_tab_specific_shortcut(
    code: crossterm::event::KeyCode,
    s: &mut super::state::AppState,
    tab: &p2p_app::tui_tabs::TabContent,
) -> bool {
    if s.is_modal_editor() {
        return false;
    }
    match code {
        crossterm::event::KeyCode::Char('n')
            if !s.is_editing_nickname()
                && matches!(tab, p2p_app::tui_tabs::TabContent::PeerInfo(_)) =>
        {
            handle_nickname_key(s, tab);
            true
        }
        crossterm::event::KeyCode::Char(c)
            if !s.is_dialing_peer()
                && !s.is_adding_network_peer()
                && matches!(tab, p2p_app::tui_tabs::TabContent::Settings) =>
        {
            handle_settings_shortcut(c, s);
            true
        }
        crossterm::event::KeyCode::Char(c)
            if !s.is_editing_nickname()
                && !s.is_creating_group()
                && matches!(tab, p2p_app::tui_tabs::TabContent::Groups) =>
        {
            handle_groups_key(c, s);
            true
        }
        // `c` clears the in-memory log buffer on the Log tab, mirroring
        // Flutter's Log-tab "Clear" action. The Log tab has no input box, so
        // the key is free here; no log line is pushed after clearing so the
        // pane is visibly empty (matching Flutter's "No logs yet" state).
        crossterm::event::KeyCode::Char('c')
            if matches!(tab, p2p_app::tui_tabs::TabContent::Log) =>
        {
            p2p_app::clear_tui_logs();
            true
        }
        // `r` re-reads the shares table on the Shares tab. Live share events
        // also reload it, but a manual refresh keeps the view authoritative
        // after an action whose result arrives asynchronously.
        crossterm::event::KeyCode::Char('r')
            if matches!(tab, p2p_app::tui_tabs::TabContent::Shares) =>
        {
            s.reload_shares();
            true
        }
        _ => false,
    }
}

/// Unclaimed keys feed the active text editor, with the typing indicator on
/// DM tabs.
fn handle_default_input(
    key_event: crossterm::event::KeyEvent,
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    dm_peer_id: Option<&str>,
    input_enabled: bool,
) {
    if input_enabled || s.is_modal_editor() {
        s.chat_input.input(key_event);
        if input_enabled
            && s.input_mode == p2p_app::InputMode::Chat
            && matches!(
                key_event.code,
                crossterm::event::KeyCode::Char(_)
                    | crossterm::event::KeyCode::Backspace
                    | crossterm::event::KeyCode::Delete
            )
            && let Some(peer_id) = dm_peer_id
        {
            let composing = !s.chat_input.lines().join("\n").trim().is_empty();
            super::message_handlers::send_typing(s, swarm_cmd_tx, peer_id, composing);
        }
    }
}

/// The Contacts / Peer Info action keys, all of which must be checked before
/// the search box and the generic sort-key arm.
///
/// Returns `true` when the key was one of them.
async fn handle_contacts_action_key(
    key_event: crossterm::event::KeyEvent,
    is_ctrl: bool,
    on_contacts: bool,
    tab: &p2p_app::tui_tabs::TabContent,
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) -> bool {
    if is_ctrl || s.is_modal_editor() {
        return false;
    }
    match key_event.code {
        crossterm::event::KeyCode::Char('i') if on_contacts => {
            if open_peer_info_for_active_tab(s) {
                p2plog_debug("Opened Peer Info tab".to_string());
            }
            true
        }
        // `e` expands/collapses the selected contact's device rows (no-op on
        // single-device contacts and device rows).
        crossterm::event::KeyCode::Char('e') if on_contacts => {
            s.toggle_expand_selected_contact();
            p2plog_debug("Toggled contact expansion".to_string());
            true
        }
        // `b` mutes/unmutes the peer shown on the Peer Info tab (US-054). The
        // swarm boundary enforces it; this only edits the persisted list.
        crossterm::event::KeyCode::Char('b')
            if matches!(tab, p2p_app::tui_tabs::TabContent::PeerInfo(_)) =>
        {
            toggle_peer_block(tab, s, swarm_cmd_tx);
            true
        }
        // `c` places a call to the selected contact/device or the Peer Info
        // owner.
        crossterm::event::KeyCode::Char('c')
            if on_contacts || matches!(tab, p2p_app::tui_tabs::TabContent::PeerInfo(_)) =>
        {
            start_call_for_tab(tab, s, swarm_cmd_tx).await;
            true
        }
        // `d` sends this install's device-binding intro to the selected peer so
        // their account holder can bind us as one of their devices (the "add my
        // second device" direction, mirroring Flutter/web).
        crossterm::event::KeyCode::Char('d')
            if on_contacts || matches!(tab, p2p_app::tui_tabs::TabContent::PeerInfo(_)) =>
        {
            send_device_intro_for_tab(tab, s, swarm_cmd_tx);
            true
        }
        _ => false,
    }
}

/// `d` sends our device-binding intro to the peer targeted by `tab`: the
/// selected contact/device on Contacts, or the Peer Info owner. The intro is
/// built from the local identity (no provisioning required) and queued on the
/// device-binding swarm lane. Errors surface in a popup so a failed send is
/// never mistaken for success.
fn send_device_intro_for_tab(
    tab: &p2p_app::tui_tabs::TabContent,
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) {
    let Some(peer_id) = (match tab {
        p2p_app::tui_tabs::TabContent::Contacts => s.selected_contact_peer_id(),
        p2p_app::tui_tabs::TabContent::PeerInfo(pid) => Some(pid.clone()),
        _ => None,
    }) else {
        return;
    };
    match p2p_app::identity::intro_device_binding_request() {
        Ok(request) => {
            match swarm_cmd_tx.try_send(SwarmCommand::SendDeviceBinding {
                peer_id: peer_id.clone(),
                request: Box::new(request),
            }) {
                Ok(()) => {
                    s.popup = Some(format!(
                        "Device intro sent to {}",
                        p2p_app::fmt::peer_id_suffix(&peer_id)
                    ));
                    p2plog_debug(format!("Sent device-binding intro to {peer_id}"));
                }
                Err(e) => {
                    s.popup = Some(format!("Could not queue device intro: {e}"));
                    p2plog_debug(format!("Failed to queue device-binding intro: {e}"));
                }
            }
        }
        Err(e) => {
            s.popup = Some(format!("Could not build device intro: {e}"));
            p2plog_debug(format!("Failed to build device-binding intro: {e}"));
        }
    }
}

/// Toggle the persisted blocklist entry for the Peer Info tab's peer (US-054).
///
/// The reason is surfaced in a popup; enforcement itself lives in
/// `swarm_handler`, so blocking takes effect on the very next event.
fn toggle_peer_block(
    tab: &p2p_app::tui_tabs::TabContent,
    s: &mut super::state::AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
) {
    let p2p_app::tui_tabs::TabContent::PeerInfo(peer_id) = tab else {
        return;
    };
    let was_blocked = s.blocked_peers.contains(peer_id);
    let result = if was_blocked {
        p2p_app::blocklist::unblock_peer(peer_id).map(|changed| (false, changed))
    } else {
        p2p_app::blocklist::block_peer(peer_id).map(|changed| (true, changed))
    };
    match result {
        Ok((now_blocked, _changed)) => {
            s.reload_blocked_peers();
            if now_blocked {
                // Close the live connection too: the boundary refuses new
                // ones, but the existing one predates the block.
                let _ = swarm_cmd_tx.try_send(SwarmCommand::DisconnectPeer {
                    peer_id: peer_id.clone(),
                });
            }
            let action = if now_blocked { "Blocked" } else { "Unblocked" };
            s.popup = Some(format!("{action} {peer_id}"));
            p2plog_debug(format!("{action} peer {peer_id}"));
        }
        Err(e) => {
            s.popup = Some(format!("Blocklist error: {e}"));
            p2plog_debug(format!("Blocklist error for {peer_id}: {e}"));
        }
    }
}

/// Processes mouse input events
async fn process_mouse_event(
    mouse_event: crossterm::event::MouseEvent,
    state: &SharedState,
    render_tx: &mpsc::Sender<RenderEvent>,
) {
    if matches!(
        mouse_event.kind,
        crossterm::event::MouseEventKind::Moved | crossterm::event::MouseEventKind::Drag(_)
    ) {
        // Track the live hover row so wheel-scroll and click routing on split
        // DM tabs target the pane the pointer is actually over. No frame change
        // results from a move alone, so nothing needs re-rendering.
        state.lock().await.last_mouse_row = mouse_event.row;
        return;
    }

    let mut s = state.lock().await;
    let mut should_render = false;

    s.last_mouse_row = mouse_event.row;

    // Mouse ownership mirrors the keyboard precedence: confirmation prompts and
    // a live call swallow every click/wheel so they cannot move tabs, open DMs
    // or scroll a conversation behind the visible overlay.
    if s.has_prompt_or_call_overlay() {
        return;
    }

    // A validation popup is click-to-dismiss even while a modal editor is
    // active; once it is gone the editor owns the pointer just like it owns the
    // keyboard. Contacts search is deliberately not a modal editor, so its
    // click-to-finalize path below stays available.
    let popup_dismissed = matches!(
        mouse_event.kind,
        crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left)
    ) && dismiss_popup(&mut s);
    if popup_dismissed {
        should_render = true;
    } else if s.is_modal_editor() {
        return;
    } else {
        let tab_content = s.dynamic_tabs.tab_index_to_content(s.active_tab);
        let is_peers_tab = matches!(tab_content, p2p_app::tui_tabs::TabContent::Contacts);
        let peer_id = if let p2p_app::tui_tabs::TabContent::Direct(pid) = &tab_content {
            Some(pid.as_str())
        } else {
            None
        };

        // List tabs move their selection on wheel events through the same
        // handler as arrow keys; message tabs scroll their transcript.
        // `handle_mouse_scroll` decides which applies and returns false for
        // tabs with no wheel behavior (notably Peer Info), so no extra
        // tab-type gate is needed here.
        match mouse_event.kind {
            crossterm::event::MouseEventKind::ScrollUp => {
                should_render = handle_mouse_scroll(&mut s, "up", peer_id);
            }
            crossterm::event::MouseEventKind::ScrollDown => {
                should_render = handle_mouse_scroll(&mut s, "down", peer_id);
            }
            crossterm::event::MouseEventKind::Down(crossterm::event::MouseButton::Left) => {
                should_render = handle_mouse_left_click(
                    &mut s,
                    mouse_event.row,
                    mouse_event.column,
                    is_peers_tab,
                );
            }
            _ => {}
        }
    }
    drop(s);
    if should_render {
        let _ = render_tx.send(RenderEvent).await;
    }
}

/// Main input event processor - routes keyboard and mouse events
/// Returns true if exit was requested, false otherwise
pub async fn process_input_event(
    input_event: InputEvent,
    state: &SharedState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    render_tx: &mpsc::Sender<RenderEvent>,
) -> bool {
    match input_event {
        InputEvent::Key(key_event) => {
            process_key_event(key_event, state, swarm_cmd_tx, render_tx).await
        }
        InputEvent::Mouse(mouse_event) => {
            process_mouse_event(mouse_event, state, render_tx).await;
            false
        }
    }
}

