//! Raw key-byte probe for diagnosing `Tab` vs `Ctrl+I` (and other modifier
//! key) encoding differences across terminals.
//!
//! Run with: `p2p_chat_tui key-probe`
//!
//! Reads raw bytes straight off the terminal (bypassing crossterm's event
//! parser, which can silently mis-decode or reject unusual CSI sequences) and
//! prints each byte it receives. This gives ground truth for what a terminal
//! actually sends for a given physical key under each keyboard-encoding mode:
//!
//! - Pressing `1` selects **Legacy mode** (no requests sent): `Ctrl+I` is
//!   expected to be byte-identical to `Tab` (`0x09`).
//! - Pressing `2` requests the **Kitty protocol** (`CSI > 1 u`,
//!   `DISAMBIGUATE_ESCAPE_CODES`): a working terminal must send `Ctrl+I` as
//!   `ESC [ 1 0 5 ; 4 u` distinct from a bare `Tab` (`0x09` or `ESC [ 9 u`).
//! - Pressing `3` requests **modifyOtherKeys mode 2** (`CSI > 4;2 m`): xterm
//!   style, `Ctrl+I` as `ESC [ 2 7 ; 5 ; 1 0 5 ~`.
//!
//! Press `q` to quit (restores the terminal).

use crossterm::{
    event::{KeyboardEnhancementFlags, PopKeyboardEnhancementFlags, PushKeyboardEnhancementFlags},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode},
};
use std::io::{Read, Write};

#[derive(Debug)]
enum ProbeMode {
    Legacy,
    Kitty,
    ModifyOtherKeys,
}

impl ProbeMode {
    const fn banner(&self) -> &'static str {
        match self {
            Self::Legacy => "LEGACY (no request). Press Tab then Ctrl+I.",
            Self::Kitty => "KITTY (`CSI > 1 u`). Press Tab then Ctrl+I.",
            Self::ModifyOtherKeys => "modifyOtherKeys 2 (`CSI > 4;2 m`). Press Tab then Ctrl+I.",
        }
    }
}

fn byte_label(b: u8) -> String {
    match b {
        0x1B => "ESC".to_string(),
        0x09 => "TAB".to_string(),
        0x0D => "CR".to_string(),
        0x0A => "LF".to_string(),
        0x7F => "DEL".to_string(),
        b if b.is_ascii_graphic() || b == b' ' => format!("[{}]", char::from(b)),
        b => format!("\\x{b:02x}"),
    }
}

/// Apply one keyboard-encoding mode and print its banner.
///
/// Keeping the three protocol switches in one place makes the near-identical
/// `1`/`2`/`3` arms in [`run`] one line each and guarantees every switch emits
/// the same banner. `stdout` is passed by mutable reference so `execute!`'s
/// `by_ref()` flush leaves the caller's handle usable.
fn switch_mode(stdout: &mut impl Write, mode: &ProbeMode) -> color_eyre::Result<()> {
    match mode {
        ProbeMode::Legacy => {
            execute!(stdout, PopKeyboardEnhancementFlags)?;
            write!(stdout, "\x1b[>4;0m")?;
        }
        ProbeMode::Kitty => {
            write!(stdout, "\x1b[>4;0m")?;
            execute!(
                stdout,
                PushKeyboardEnhancementFlags(KeyboardEnhancementFlags::DISAMBIGUATE_ESCAPE_CODES)
            )?;
        }
        ProbeMode::ModifyOtherKeys => {
            execute!(stdout, PopKeyboardEnhancementFlags)?;
            write!(stdout, "\x1b[>4;2m")?;
        }
    }
    write!(stdout, "\r\nMode: {}\r\n", mode.banner())?;
    Ok(())
}

/// Runs the probe until the user presses `q`. Restores the terminal on exit.
pub fn run() -> color_eyre::Result<()> {
    enable_raw_mode()?;
    let mut stdout = std::io::stdout();
    write!(stdout, "\r\n")?; // leading blank line, then scroll like a normal app
    write!(
        stdout,
        "Byte probe. Modes: 1=legacy 2=kitty 3=modifyOtherKeys   q=quit\r\n"
    )?;
    stdout.flush()?;

    let mut mode = ProbeMode::Legacy;
    write!(stdout, "Mode: {}\r\n", mode.banner())?;
    stdout.flush()?;

    let mut stdin = std::io::stdin();
    let mut buf = [0u8; 128];
    let mut in_escape = false;
    // True while we are still expecting the single-byte introducer that must
    // follow ESC (`[` for CSI, `]` for OSC, ...). The introducer itself is
    // never a final byte, so without this a CSI sequence would wrongly
    // terminate on its own `[` (0x5B is inside 0x40..=0x7E).
    let mut expect_intro = false;
    let mut seq_len = 0usize;

    let mut quit = false;
    while !quit {
        let n = stdin.read(&mut buf).map_err(color_eyre::Report::from)?;
        if n == 0 {
            break;
        }
        for &b in buf.iter().take(n) {
            if !in_escape {
                match b {
                    b'1' => {
                        mode = ProbeMode::Legacy;
                        switch_mode(&mut stdout, &mode)?;
                    }
                    b'2' => {
                        mode = ProbeMode::Kitty;
                        switch_mode(&mut stdout, &mode)?;
                    }
                    b'3' => {
                        mode = ProbeMode::ModifyOtherKeys;
                        switch_mode(&mut stdout, &mode)?;
                    }
                    b'q' => {
                        quit = true;
                        break;
                    }
                    0x1B => {
                        write!(stdout, "ESC")?;
                        in_escape = true;
                        expect_intro = true;
                        seq_len = 1;
                    }
                    b => {
                        write!(stdout, " {}\r\n", byte_label(b))?;
                    }
                }
            } else if b == 0x1B {
                // New escape inside an unfinished one: close the line first.
                write!(stdout, "\r\n")?;
                write!(stdout, "ESC")?;
                expect_intro = true;
                seq_len = 1;
            } else {
                write!(stdout, " {}", byte_label(b))?;
                seq_len = seq_len.saturating_add(1);
                let final_byte = !expect_intro && (0x40..=0x7E).contains(&b);
                expect_intro = false;
                if final_byte || seq_len > 32 {
                    in_escape = false;
                    write!(stdout, "\r\n")?;
                    seq_len = 0;
                }
            }
        }
        stdout.flush()?;
    }

    // Restore the terminal: reset modifyOtherKeys, pop the kitty flags.
    write!(stdout, "\x1b[>4;0m")?;
    let _ = execute!(stdout, PopKeyboardEnhancementFlags);
    disable_raw_mode()?;
    println!("Key probe finished. Terminal restored.");
    Ok(())
}

use super::state::CHANNEL_CAPACITY;
use p2p_app::generated::models_queryable::{MessageReceipt, Peer};
use p2p_app::p2plog_debug;
use p2p_app::peers::KnownPeer;
use p2p_app::set_tui_redraw_hook;
use ratatui::Terminal;
use ratatui::backend::CrosstermBackend;
use std::collections::{HashMap, HashSet, VecDeque};
use std::io::Write;
use std::sync::Arc;
use tokio::sync::Mutex;
use tokio::sync::mpsc;

/// Pure: extract nickname maps from DB peers
// Type aliases for organized receipt data
type BroadcastReceipts = HashMap<String, HashMap<String, f64>>;
type DmReceipts = HashMap<String, (String, f64)>;

fn extract_nickname_maps(
    peers: &[Peer],
) -> (
    HashMap<String, String>,
    HashMap<String, String>,
    HashMap<String, String>,
) {
    let mut local = HashMap::new();
    let mut received = HashMap::new();
    let mut self_for_peer = HashMap::new();
    for p in peers {
        if let Some(n) = p.peer_local_nickname.clone() {
            local.insert(p.peer_id.clone(), n);
        }
        if let Some(n) = p.received_nickname.clone() {
            received.insert(p.peer_id.clone(), n);
        }
        if let Some(n) = p.self_nickname_for_peer.clone() {
            self_for_peer.insert(p.peer_id.clone(), n);
        }
    }
    (local, received, self_for_peer)
}

/// Pure: deduplicate peers and format timestamps
fn deduplicate_peers(peers: &[KnownPeer]) -> VecDeque<p2p_app::PeerRecord> {
    let mut result = VecDeque::new();
    let mut seen_ids = HashSet::new();
    for peer in peers {
        if !seen_ids.insert(peer.peer_id.clone()) {
            continue;
        }
        let last_seen = p2p_app::format_peer_datetime(peer.last_seen);
        let first_seen = p2p_app::format_peer_datetime(peer.first_seen);
        result.push_back(p2p_app::PeerRecord {
            peer_id: peer.peer_id.clone(),
            first_seen,
            last_seen,
        });
    }
    result
}

/// Pure: organize flat receipt list into broadcast and DM maps
fn organize_receipts(receipts: &[MessageReceipt]) -> (BroadcastReceipts, DmReceipts) {
    let mut broadcast: HashMap<String, HashMap<String, f64>> = HashMap::new();
    let mut dm: HashMap<String, (String, f64)> = HashMap::new();
    for r in receipts {
        let msg_id = r.msg_id.clone();
        let peer_id = r.peer_id.clone();
        let confirmed_at = r.confirmed_at;
        if r.kind == 0 {
            broadcast
                .entry(msg_id)
                .or_default()
                .insert(peer_id, confirmed_at);
        } else {
            dm.insert(msg_id, (peer_id, confirmed_at));
        }
    }
    (broadcast, dm)
}

/// Run the new 4-task TUI architecture
///
/// Orchestrates the spawning and supervision of the four concurrent tasks:
/// - **`SwarmHandler`**: Translates libp2p events to `SwarmEvent`
/// - **`EventSource`**: Polls terminal for keyboard/mouse input
/// - **`CommandProcessor`**: Receives events, mutates shared `AppState`
/// - **`RenderLoop`**: Renders `AppState` to terminal when requested
///
/// All tasks communicate via bounded MPSC channels (capacity: 100 events).
/// State is shared behind `Arc<Mutex<AppState>>` for safe concurrent access.
///
/// The function sets up terminal mode (alternate screen, raw mode, mouse capture),
/// initializes the state from database, and waits for any task to exit (indicating error).
/// Signal to trigger a render (instead of busy-polling)
#[derive(Debug, Clone, Copy)]
pub struct RenderEvent;
/// Bring up the raw-mode terminal and push the minimal keyboard-enhancement
/// flag.
///
/// Only `DISAMBIGUATE_ESCAPE_CODES` is needed to tell Ctrl+I apart from bare
/// Tab (Ctrl+letter is then reported as its true key code plus CONTROL) — the
/// `REPORT_ALL_KEYS` flag is deliberately NOT pushed: it makes the terminal
/// report every key (letters, shift presses) as CSI-u events, which is
/// unnecessary and leaves the shell deluged in CSI-u garbage if the keyboard
/// encoding is ever left active on exit. The push is sent AFTER raw mode is
/// enabled (some terminals only apply kitty encoding to keys read once raw mode
/// is active). The returned flag is the synchronous kitty-capability probe,
/// read BEFORE the input-handler task starts reading the tty so there is no
/// race (`WezTerm` reports supported; Konsole collapses Ctrl+I to 0x09). It
/// selects which peer-info shortcut is active on a Direct tab: Ctrl+I (kitty)
/// vs Ctrl+P (non-kitty).
fn setup_terminal() -> color_eyre::Result<(Terminal<CrosstermBackend<std::io::Stdout>>, bool)> {
    use ratatui::crossterm::{
        event::PushKeyboardEnhancementFlags,
        execute,
        terminal::{EnterAlternateScreen, enable_raw_mode},
    };

    let mut stdout = std::io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    enable_raw_mode()?;
    execute!(
        stdout,
        PushKeyboardEnhancementFlags(
            crossterm::event::KeyboardEnhancementFlags::DISAMBIGUATE_ESCAPE_CODES
        ),
        crossterm::event::EnableMouseCapture,
    )?;

    let keyboard_enhanced = crossterm::terminal::supports_keyboard_enhancement().unwrap_or(false);
    p2plog_debug(format!(
        "Keyboard enhancement (kitty) protocol: {} — Ctrl+I {} be distinct from Tab",
        if keyboard_enhanced {
            "supported"
        } else {
            "NOT supported"
        },
        if keyboard_enhanced {
            "will"
        } else {
            "will NOT"
        }
    ));

    let backend = CrosstermBackend::new(stdout);
    let terminal = Terminal::new(backend)?;
    Ok((terminal, keyboard_enhanced))
}

/// Load the full initial application state from the database (nickname maps,
/// message history, known peers, receipts, groups) and set the fixed runtime
/// fields. Returns the state, the DB URL/label shown in the status bar, and the
/// group list (reused for re-subscription on startup).
fn initialize_state(
    topic_str: &str,
    own_nickname: String,
    keyboard_enhanced: bool,
) -> (
    super::state::AppState,
    String,
    Vec<p2p_app::groups::GroupSummary>,
) {
    let db_info = p2p_app::get_database_url();
    p2plog_debug(format!("Database: {db_info}"));
    p2plog_debug(format!("Loading data for topic: {topic_str}"));

    let (local_nicknames, received_nicknames, self_nicknames_for_peers) = p2p_app::load_peers()
        .map_or_else(
            |_| (HashMap::new(), HashMap::new(), HashMap::new()),
            |db_peers| extract_nickname_maps(&db_peers),
        );

    let (initial_messages, initial_message_ids, initial_message_db_ids) =
        super::state::load_and_format_messages(
            topic_str,
            super::state::MAX_MESSAGE_HISTORY,
            &local_nicknames,
            &received_nicknames,
            &own_nickname,
        );
    p2plog_debug(format!(
        "Loaded {} messages from database",
        initial_messages.len()
    ));

    // Load initial peers from database (including peer IDs that only exist in
    // messages), sorted by last_seen (latest first) — the format is
    // "YYYY-MM-DD HH:MM:SS" so lexicographic ordering works.
    let mut initial_peers = p2p_app::load_known_peers().map_or_else(
        |_| {
            p2plog_debug("No peers found in database".to_string());
            VecDeque::new()
        },
        |db_peers| {
            let peers = deduplicate_peers(&db_peers);
            p2plog_debug(format!(
                "Loaded {} unique peers from {} total database entries",
                peers.len(),
                db_peers.len()
            ));
            peers
        },
    );
    let mut peers_vec: Vec<_> = initial_peers.into_iter().collect();
    peers_vec.sort_by(|a, b| b.last_seen.cmp(&a.last_seen));
    initial_peers = peers_vec.into();

    let (loaded_broadcast_receipts, loaded_dm_receipts) = p2p_app::load_receipts().map_or_else(
        |_| (HashMap::new(), HashMap::new()),
        |receipts| {
            let (br, dr) = organize_receipts(&receipts);
            p2plog_debug(format!(
                "Loaded {} broadcast receipts and {} DM receipts from database",
                br.len(),
                dr.len()
            ));
            (br, dr)
        },
    );

    let local_peer_id =
        p2p_app::get_local_peer_id().map_or_else(|_| "unknown".to_string(), |id| id.to_string());

    // Load group list (known groups + member counts) from the database.
    let initial_groups = p2p_app::groups::list_groups_with_member_counts().unwrap_or_default();
    let mut state = super::state::AppState::new(
        topic_str.to_string(),
        own_nickname,
        local_peer_id,
        local_nicknames,
        received_nicknames,
        self_nicknames_for_peers,
        super::state::InitialStateData {
            messages: initial_messages,
            message_ids: initial_message_ids,
            message_db_ids: initial_message_db_ids,
            peers: initial_peers,
            broadcast_receipts: loaded_broadcast_receipts,
            dm_receipts: loaded_dm_receipts,
            groups: initial_groups.clone(),
        },
    );
    // Hydrate stored reaction chips once for the loaded broadcast history
    // (US-008); live events and other chats extend the same map.
    p2p_app::reactions::hydrate_into(&mut state.reactions, state.message_ids.iter().cloned());
    // Seed the unread badge from the shared DB watermark so a restart agrees
    // with Flutter/web. The pane opens on the first unread row when there are
    // any; a fresh install (no marker) reports zero.
    state.seed_broadcast_unread(p2p_app::messages::broadcast_unread_count());
    state.env.kitty_keyboard_active = keyboard_enhanced;
    state.db_url.clone_from(&db_info);
    state.platform = format!("Terminal ({})", std::env::consts::OS);
    state.reload_network_peers();
    (state, db_info, initial_groups)
}

/// Provision a user identity for this install (idempotent): creates the users
/// row keyed by a generated account keypair and self-binds the local device, so
/// the TUI is an account holder that can accept device-binding intros ('a' on
/// the prompt). Mirrors the mobile auto-provision at start. The announced
/// user-level nickname is seeded with the install's self nickname (ensured
/// earlier) so fresh accounts resolve to a name on the receiver side. Best
/// effort — a failure only degrades the account features, not the chat.
async fn provision_account(state: &super::state::SharedState) {
    let self_nickname = p2p_app::get_self_nickname().ok().flatten();
    if let Err(e) = p2p_app::identity::provision_my_user(None, self_nickname.as_deref()) {
        p2plog_debug(format!("Failed to provision user identity: {e}"));
    }
    state.lock().await.refresh_my_user();
}

/// Restore the terminal after shutdown: pop the keyboard-enhancement flag and
/// defensively clear every keyboard mode while raw mode is still on (so the
/// escape sequences transmit cleanly), then leave the alternate screen and
/// restore termios.
///
/// We pushed only `DISAMBIGUATE_ESCAPE_CODES` at startup; on exit we pop it and
/// also emit `CSI > 4;0m` (xterm modifyOtherKeys off) in case any terminal left
/// it on. Otherwise the shell keeps receiving CSI-u/modified-key sequences
/// (arrow keys print as `A`..`D`, or junk like `;1u;5u…`) and is unusable.
fn restore_terminal(mut stdout: std::io::Stdout) {
    use ratatui::crossterm::{
        execute,
        terminal::{LeaveAlternateScreen, disable_raw_mode},
    };

    let _ = execute!(stdout, crossterm::event::PopKeyboardEnhancementFlags);
    let _ = write!(stdout, "\x1b[>4;0m");
    let _ = stdout.flush();
    let _ = execute!(stdout, LeaveAlternateScreen);
    let _ = execute!(stdout, crossterm::event::DisableMouseCapture);
    let _ = disable_raw_mode();
}

/// Main TUI loop: set up the terminal, initialize state, spawn the task
/// pipelines, and wait for any task to exit (indicating error or exit). The
/// function sets up terminal mode (alternate screen, raw mode, mouse capture)
/// and waits for the pipeline to finish, printing cached logs after restoring
/// the terminal.
///
/// Signal to trigger a render (instead of busy-polling) is carried by the
/// [`RenderEvent`] unit struct.
pub async fn run_new_tui() -> color_eyre::Result<()> {
    let (mut terminal, keyboard_enhanced) = setup_terminal()?;
    terminal.clear()?;

    let topic_str = p2p_app::CHAT_TOPIC.to_string();

    // Initialize state
    let own_nickname = p2p_app::ensure_self_nickname().unwrap_or_else(|_| "Anonymous".to_string());
    let (state, _db_info, _initial_groups) =
        initialize_state(&topic_str, own_nickname, keyboard_enhanced);
    let state = Arc::new(Mutex::new(state));

    // Setup channels
    let (input_tx, input_rx) = mpsc::channel(CHANNEL_CAPACITY);
    let (render_tx, render_rx) = mpsc::channel(CHANNEL_CAPACITY);
    let render_tx_for_logs = render_tx.clone();
    set_tui_redraw_hook(move || {
        let _ = render_tx_for_logs.try_send(RenderEvent);
    });
    let _ = render_tx.send(RenderEvent).await;

    // Use the mobile_node backend (single shared node) instead of owning a
    // swarm directly. This is step 2 of the Option A refactor: the TUI now
    // consumes events from the shared node's broadcast fan-out.
    let swarm_event_rx =
        p2p_app::mobile_node::subscribe_events().map_err(|e| color_eyre::eyre::eyre!(e))?;
    let swarm_cmd_tx =
        p2p_app::mobile_node::command_sender().map_err(|e| color_eyre::eyre::eyre!(e))?;

    // Wrap the broadcast receiver in an mpsc channel adapter so the existing
    // CommandProcessor (which expects mpsc::Receiver<SwarmEvent>) keeps
    // working. A small task forwards events.
    let (fwd_tx, fwd_rx) = mpsc::channel(CHANNEL_CAPACITY);
    let mut bc_rx = swarm_event_rx;
    tokio::spawn(async move {
        loop {
            match bc_rx.recv().await {
                Ok(ev) => {
                    if fwd_tx.send(ev).await.is_err() {
                        break;
                    }
                }
                Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
                Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => {}
            }
        }
    });

    provision_account(&state).await;

    // Groups are re-subscribed by mobile_node::start_node_impl already.

    // Sweep dead attachment blobs (files lane §12).
    if let Err(e) = p2p_app::file_transfer::gc_stale_attachments() {
        p2plog_debug(format!("attachment GC failed: {e}"));
    }

    // EventSource sends InputEvent to this channel
    let event_source = super::event_source::spawn_input_handler(input_tx);

    // CommandProcessor receives both InputEvent and SwarmEvent, sends RenderEvent and SwarmCommand
    let (command_processor, _) = super::command_processor::spawn_command_processor(
        state.clone(),
        input_rx,
        fwd_rx,
        render_tx,
        swarm_cmd_tx,
    );

    // RenderLoop reads state and renders
    let render_loop = super::render_loop::spawn_render_loop(state.clone(), terminal, render_rx);

    p2plog_debug("Started TUI on mobile_node backend".to_string());

    // Wait for any task to complete (indicates error or exit). The swarm
    // handler lives inside mobile_node now, so we only watch the TUI tasks.
    let exit_reason = tokio::select! {
        result = event_source => {
            if result.is_err() { "EventSource task error" } else { "EventSource completed" }
        }
        result = command_processor => {
            if result.is_err() { "CommandProcessor task error" } else { "CommandProcessor completed" }
        }
        result = render_loop => {
            if result.is_err() { "RenderLoop task error" } else { "RenderLoop completed" }
        }
    };
    p2plog_debug(format!("TUI exited: {exit_reason}"));

    // Restore terminal
    let () = restore_terminal(std::io::stdout());
    Ok(())
}

#[cfg(test)]
#[path = "../../../tests/unit/unit_bin_tui_main_loop.rs"]
mod tests;

use super::state::AppState;
use super::state::{MAX_DM_HISTORY, MAX_MESSAGE_HISTORY, trim_history};
use p2p_app::{DisplayMessage, SwarmCommand, p2plog_debug};
use std::collections::VecDeque;
use tokio::sync::mpsc;

/// Attach the DB row id of a just-sent message to its aligned queue slot.
/// The push happens before the DB write (to preserve the visible order), so
/// the caller records the row index and fills it in once the save succeeds.
fn attach_sent_db_id(ids: Option<&mut VecDeque<Option<i32>>>, idx: usize, id: i32) {
    if let Some(ids) = ids
        && let Some(slot) = ids.get_mut(idx)
    {
        *slot = Some(id);
    }
}

/// Pure: format and push an outgoing broadcast message to state, trimming history.
/// Returns the index of the new row so the caller can attach its saved DB id.
fn push_outgoing_broadcast_to_state(
    state: &mut AppState,
    ts: &str,
    own_nickname: &str,
    content: &str,
    attachment: Option<&p2p_app::files::MessageAttachment>,
    msg_id: String,
    reply_to: Option<&p2p_app::ReplyRef>,
) -> usize {
    let body = render_outgoing_body(content, attachment);
    let msg = p2p_app::reply::with_quoted_header(format!("{ts} [{own_nickname}] {body}"), reply_to);
    state.messages.push_back(DisplayMessage {
        text: msg,
        sender_peer_id: None,
    });
    state.message_ids.push_back(Some(msg_id));
    state.message_db_ids.push_back(None);
    trim_history(&mut state.messages, MAX_MESSAGE_HISTORY);
    trim_history(&mut state.message_ids, MAX_MESSAGE_HISTORY);
    trim_history(&mut state.message_db_ids, MAX_MESSAGE_HISTORY);
    state.message_db_ids.len().saturating_sub(1)
}

/// Pure: compose an outgoing chat line before the sender tag: text first, the
/// attachment chip appended; an attachment-only message renders as just the
/// chip so a file never shows up as a blank row.
fn render_outgoing_body(
    content: &str,
    attachment: Option<&p2p_app::files::MessageAttachment>,
) -> String {
    let chip = attachment.map_or_else(String::new, p2p_app::files::file_chip);
    if content.trim().is_empty() {
        chip
    } else if chip.is_empty() {
        content.to_string()
    } else {
        format!("{content} {chip}")
    }
}

/// Inputs for appending an outgoing DM to the in-memory chat log.
struct OutgoingDm<'a> {
    peer_id: &'a str,
    ts: &'a str,
    self_nickname: &'a str,
    content: &'a str,
    attachment: Option<&'a p2p_app::files::MessageAttachment>,
    msg_id: String,
    reply_to: Option<&'a p2p_app::ReplyRef>,
    encrypted: bool,
}

/// Pure: format and push an outgoing DM to state, trimming history. Returns the
/// index of the new row so the caller can attach its saved DB id.
fn push_outgoing_dm_to_state(state: &mut AppState, dm: OutgoingDm<'_>) -> usize {
    let OutgoingDm {
        peer_id,
        ts,
        self_nickname,
        content,
        attachment,
        msg_id,
        reply_to,
        encrypted,
    } = dm;
    let body = p2p_app::e2e::mark_encrypted(render_outgoing_body(content, attachment), encrypted);
    let msg =
        p2p_app::reply::with_quoted_header(format!("{ts} [{self_nickname}] {body}"), reply_to);
    let dm_msgs = state.dm_messages.entry(peer_id.to_string()).or_default();
    dm_msgs.push_back(msg);
    state
        .dm_message_ids
        .entry(peer_id.to_string())
        .or_default()
        .push_back(Some(msg_id));
    state
        .dm_message_db_ids
        .entry(peer_id.to_string())
        .or_default()
        .push_back(None);
    trim_history(dm_msgs, MAX_DM_HISTORY);
    if let Some(ids) = state.dm_message_ids.get_mut(peer_id) {
        trim_history(ids, MAX_DM_HISTORY);
    }
    if let Some(ids) = state.dm_message_db_ids.get_mut(peer_id) {
        trim_history(ids, MAX_DM_HISTORY);
    }
    state
        .dm_message_db_ids
        .get(peer_id)
        .map_or(0, VecDeque::len)
        .saturating_sub(1)
}

/// Inputs for appending an outgoing group message to the in-memory chat log.
struct OutgoingGroup<'a> {
    group_id: &'a str,
    ts: &'a str,
    own_nickname: &'a str,
    content: &'a str,
    attachment: Option<&'a p2p_app::files::MessageAttachment>,
    msg_id: String,
    reply_to: Option<&'a p2p_app::ReplyRef>,
}

/// Pure: format and push an outgoing group message to state, trimming history.
/// Returns the index of the new row so the caller can attach its saved DB id.
fn push_outgoing_group_message_to_state(state: &mut AppState, group: OutgoingGroup<'_>) -> usize {
    let OutgoingGroup {
        group_id,
        ts,
        own_nickname,
        content,
        attachment,
        msg_id,
        reply_to,
    } = group;
    let body = render_outgoing_body(content, attachment);
    let msg = p2p_app::reply::with_quoted_header(format!("{ts} [{own_nickname}] {body}"), reply_to);
    let msgs = state
        .group_messages
        .entry(group_id.to_string())
        .or_default();
    msgs.push_back(msg);
    state
        .group_message_ids
        .entry(group_id.to_string())
        .or_default()
        .push_back(Some(msg_id));
    state
        .group_message_db_ids
        .entry(group_id.to_string())
        .or_default()
        .push_back(None);
    state
        .group_message_peer_ids
        .entry(group_id.to_string())
        .or_default()
        .push_back(None);
    trim_history(msgs, MAX_MESSAGE_HISTORY);
    if let Some(ids) = state.group_message_ids.get_mut(group_id) {
        trim_history(ids, MAX_MESSAGE_HISTORY);
    }
    if let Some(ids) = state.group_message_db_ids.get_mut(group_id) {
        trim_history(ids, MAX_MESSAGE_HISTORY);
    }
    if let Some(ids) = state.group_message_peer_ids.get_mut(group_id) {
        trim_history(ids, MAX_MESSAGE_HISTORY);
    }
    state.group_scroll_state.insert(group_id.to_string(), {
        let len = msgs.len();
        (len, true)
    });
    // Sending our own message jumps to the tail, so anything previously
    // counted as unread in this group has now been seen.
    state.group_unread_count.remove(group_id);
    state
        .group_message_db_ids
        .get(group_id)
        .map_or(0, VecDeque::len)
        .saturating_sub(1)
}

/// Sends a message (broadcast, direct, or group message): pushes it into the
/// active chat state, dispatches it over the swarm, and persists it with
/// receipt metadata. Routing picks the per-kind helper by the active tab.
///
/// `attachment` rides along as a descriptor (files lane §12); the bytes were
/// already stored via `files::store_outgoing_file` so the receiving end can
/// pull them from us.
pub async fn send_message(
    state: &mut AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    text: String,
    attachment: Option<p2p_app::files::MessageAttachment>,
    tab_content: p2p_app::tui_tabs::TabContent,
) {
    let own_nickname = state.own_nickname.clone();
    // One reply per outgoing message: the draft is consumed here so a failed
    // send still clears the affordance instead of silently quoting twice.
    let reply_to = state.take_reply(&tab_content);
    match &tab_content {
        p2p_app::tui_tabs::TabContent::Direct(peer_id) => {
            send_dm_message(
                state,
                swarm_cmd_tx,
                peer_id.clone(),
                text,
                attachment,
                own_nickname,
                reply_to,
            )
            .await;
        }
        p2p_app::tui_tabs::TabContent::GroupChat(group_id) => {
            send_group_message(
                state,
                swarm_cmd_tx,
                group_id.clone(),
                text,
                attachment,
                own_nickname,
                reply_to,
            )
            .await;
        }
        _ => {
            send_broadcast_message(
                state,
                swarm_cmd_tx,
                text,
                attachment,
                own_nickname,
                reply_to,
            )
            .await;
        }
    }
}

/// Attach a local file to a message on the active tab and send it (files lane
/// §12). The bytes are content-addressed into our store first so senders can
/// serve the receiver's pull; failures surface in a popup and the input is
/// kept as-is.
pub async fn send_file_message(
    state: &mut AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    path: &str,
    tab_content: p2p_app::tui_tabs::TabContent,
) {
    match p2p_app::files::store_outgoing_file(path) {
        Ok(attachment) => {
            send_message(
                state,
                swarm_cmd_tx,
                String::new(),
                Some(attachment),
                tab_content,
            )
            .await;
        }
        Err(e) => {
            state.popup = Some(format!("Failed to attach {path}: {e}"));
        }
    }
}

/// Send a transient typing state for a DM conversation (US-009).
///
/// Outgoing "started" signals are throttled in [`AppState`]; "stopped" signals
/// are always sent so a remote indicator is cleared immediately.
pub fn send_typing(
    state: &mut AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    peer_id: &str,
    is_typing: bool,
) {
    if !state.note_typing_sent(peer_id, is_typing) {
        return;
    }
    let _ = swarm_cmd_tx.try_send(SwarmCommand::SendTyping {
        peer_id: peer_id.to_string(),
        is_typing,
    });
}

/// Send a direct message: push to the DM chat state, dispatch over the swarm,
/// and persist with receipt metadata. The sender nickname is the per-peer
/// override when one exists, else our own nickname.
async fn send_dm_message(
    state: &mut AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    peer_id: String,
    text: String,
    attachment: Option<p2p_app::files::MessageAttachment>,
    own_nickname: String,
    reply_to: Option<p2p_app::ReplyRef>,
) {
    let ts = p2p_app::format_now();
    let dm_self_nickname = state
        .self_nicknames_for_peers
        .get(&peer_id)
        .cloned()
        .unwrap_or_else(|| own_nickname.clone());
    let msg_id = p2p_app::gen_msg_id();
    let msg_id_for_db = msg_id.clone();
    let sent_at = p2p_app::current_timestamp();

    let encrypted = p2p_app::e2e::can_encrypt_to_str(&peer_id);

    let row_idx = push_outgoing_dm_to_state(
        state,
        OutgoingDm {
            peer_id: &peer_id,
            ts: &ts,
            self_nickname: &dm_self_nickname,
            content: &text,
            attachment: attachment.as_ref(),
            msg_id: msg_id.clone(),
            reply_to: reply_to.as_ref(),
            encrypted,
        },
    );
    p2plog_debug(format!("Sent DM to {peer_id}: {text}"));

    state.chat_input = ratatui_textarea::TextArea::default();

    let _ = swarm_cmd_tx
        .send(SwarmCommand::SendDm {
            peer_id: peer_id.clone(),
            content: text.clone(),
            nickname: Some(dm_self_nickname),
            msg_id: Some(msg_id),
            ack_for: None,
            attachment: attachment.clone(),
            reply_to: reply_to.clone(),
        })
        .await;
    // Clear the remote indicator only after the message itself is queued, so
    // a peer sees "typing…" until the DM arrives. Fire-and-forget: a full lane
    // never blocks the message send.
    send_typing(state, swarm_cmd_tx, &peer_id, false);

    let meta = p2p_app::MessageMeta {
        sender_nickname: Some(own_nickname),
        msg_id: Some(msg_id_for_db),
        sent_at: Some(sent_at),
        attachment,
        reply_to,
        encrypted,
    };
    let saved_id = match p2p_app::save_message_with_meta(
        &text,
        None,
        &state.topic_str,
        true,
        Some(&peer_id),
        meta,
    ) {
        Ok(saved) => Some(saved.id),
        Err(e) => {
            p2plog_debug(format!("Failed to save message: {e}"));
            None
        }
    };
    // The TUI is the sender: stamp `sent = 1` so the row is deletable (US-005).
    let sent_id = saved_id.and_then(|id| match p2p_app::messages::mark_message_sent(id) {
        Ok(()) => Some(id),
        Err(e) => {
            p2plog_debug(format!("Failed to mark message as sent: {e}"));
            None
        }
    });
    if let Some(id) = sent_id {
        attach_sent_db_id(state.dm_message_db_ids.get_mut(&peer_id), row_idx, id);
    }
}

/// Send a group message: push to the group chat state, dispatch over the
/// swarm, and persist with group metadata.
async fn send_group_message(
    state: &mut AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    group_id: String,
    text: String,
    attachment: Option<p2p_app::files::MessageAttachment>,
    own_nickname: String,
    reply_to: Option<p2p_app::ReplyRef>,
) {
    let ts = p2p_app::format_now();
    let msg_id = p2p_app::gen_msg_id();
    let msg_id_for_db = msg_id.clone();
    let sent_at = p2p_app::current_timestamp();

    let row_idx = push_outgoing_group_message_to_state(
        state,
        OutgoingGroup {
            group_id: &group_id,
            ts: &ts,
            own_nickname: &own_nickname,
            content: &text,
            attachment: attachment.as_ref(),
            msg_id: msg_id.clone(),
            reply_to: reply_to.as_ref(),
        },
    );
    p2plog_debug(format!("Sent group message to {group_id}: {text}"));

    state.chat_input = ratatui_textarea::TextArea::default();

    let _ = swarm_cmd_tx
        .send(SwarmCommand::PublishGroup {
            group_id: group_id.clone(),
            content: text.clone(),
            nickname: Some(own_nickname.clone()),
            msg_id: Some(msg_id),
            attachment: attachment.clone(),
            reply_to: reply_to.clone(),
        })
        .await;

    let meta = p2p_app::groups::GroupMessageMeta {
        sender_nickname: Some(own_nickname),
        msg_id: Some(msg_id_for_db),
        sent_at: Some(sent_at),
        attachment,
        reply_to,
    };
    // Group outgoing rows are inserted with `sent = 1` already; just capture
    // the id so the local-only Delete binding can find the row (US-005).
    match p2p_app::groups::save_outgoing_group_message(&group_id, &text, meta) {
        Ok(saved) => attach_sent_db_id(
            state.group_message_db_ids.get_mut(&group_id),
            row_idx,
            saved.id,
        ),
        Err(e) => p2plog_debug(format!("Failed to save group message: {e}")),
    }
}

/// Send a broadcast: push to the broadcast chat state, dispatch over the
/// swarm, persist with metadata, and attribute the message to every peer that
/// was online to receive it so the peers table can show how many broadcasts we
/// sent each peer.
async fn send_broadcast_message(
    state: &mut AppState,
    swarm_cmd_tx: &mpsc::Sender<SwarmCommand>,
    text: String,
    attachment: Option<p2p_app::files::MessageAttachment>,
    own_nickname: String,
    reply_to: Option<p2p_app::ReplyRef>,
) {
    let ts = p2p_app::format_now();
    let msg_id = p2p_app::gen_msg_id();
    let msg_id_for_db = msg_id.clone();
    let sent_at = p2p_app::current_timestamp();

    let row_idx = push_outgoing_broadcast_to_state(
        state,
        &ts,
        &own_nickname,
        &text,
        attachment.as_ref(),
        msg_id.clone(),
        reply_to.as_ref(),
    );
    p2plog_debug(format!("Sent broadcast: {text}"));

    state.chat_input = ratatui_textarea::TextArea::default();

    let _ = swarm_cmd_tx
        .send(SwarmCommand::Publish {
            content: text.clone(),
            nickname: Some(own_nickname.clone()),
            msg_id: Some(msg_id),
            attachment: attachment.clone(),
            reply_to: reply_to.clone(),
        })
        .await;

    let meta = p2p_app::MessageMeta {
        sender_nickname: Some(own_nickname),
        msg_id: Some(msg_id_for_db.clone()),
        sent_at: Some(sent_at),
        attachment,
        reply_to,
        encrypted: false,
    };
    let saved_id =
        match p2p_app::save_message_with_meta(&text, None, &state.topic_str, false, None, meta) {
            Ok(saved) => Some(saved.id),
            Err(e) => {
                p2plog_debug(format!("Failed to save message: {e}"));
                None
            }
        };
    let sent_id = saved_id.and_then(|id| match p2p_app::messages::mark_message_sent(id) {
        Ok(()) => Some(id),
        Err(e) => {
            p2plog_debug(format!("Failed to mark message as sent: {e}"));
            None
        }
    });
    if let Some(id) = sent_id {
        attach_sent_db_id(Some(&mut state.message_db_ids), row_idx, id);
    }
    // Our own message is by definition on screen, so advance the shared
    // watermark too (matches Flutter's send path).
    state.mark_broadcast_viewed();

    let recipients: Vec<String> = state
        .connected
        .connected_peer_ids()
        .map(str::to_owned)
        .collect();
    if !recipients.is_empty() {
        let _ = p2p_app::peers::record_broadcast_recipients(&msg_id_for_db, &recipients);
    }
}

