//! OSC 52 clipboard sequences for the TUI.
//!
//! The render loop owns every TUI stdout write, so clipboard content is turned
//! into an escape sequence here (a pure function) and emitted *after* the frame
//! alongside the OSC 777 notifications in [`crate::notifications`]. That keeps
//! terminal writes single-threaded and prevents a clipboard payload from
//! interleaving with ratatui's screen drawing.
//!
//! OSC 52 support is terminal-dependent (kitty, iTerm2, `WezTerm`, Alacritty,
//! foot and modern xterm work; tmux needs `set-clipboard` passthrough enabled).
//! The same caveat applies to the desktop notifications already in the app.

use crossterm::Command;

/// Build the OSC 52 sequence that copies `content` to the terminal clipboard.
///
/// [`crossterm::clipboard::CopyToClipboard::to_clipboard_from`] targets the `c`
/// (clipboard) selection, the most widely supported destination across
/// emulators. The content is base64-encoded by crossterm, so message text —
/// including newlines, tabs and ANSI bytes — can never inject a second OSC
/// command into the sequence.
#[must_use]
pub fn copy_sequence(content: &str) -> String {
    let command = crossterm::clipboard::CopyToClipboard::to_clipboard_from(content.as_bytes());
    let mut out = String::new();
    // Writing an ANSI sequence into a `String` cannot fail.
    let _ = command.write_ansi(&mut out);
    out
}

/// Join every log line into one clipboard payload, mirroring Flutter's Log-tab
/// "Copy All" action (`_logs.join('\n')`). Returns `None` for an empty buffer so
/// the caller never emits a pointless OSC sequence.
#[must_use]
pub fn copy_all_logs(logs: &[String]) -> Option<String> {
    (!logs.is_empty()).then(|| logs.join("\n"))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// crossterm terminates the OSC with the canonical `ST` (`ESC \`) rather
    /// than BEL, so there is one ESC for the introducer and one for the end.
    const ST: &str = "\u{1b}\\";

    #[test]
    fn copy_sequence_targets_clipboard_with_known_base64() {
        let seq = copy_sequence("hello");
        assert!(seq.starts_with("\u{1b}]52;c;"), "{seq:?}");
        assert!(seq.ends_with(ST), "{seq:?}");
        assert!(seq.contains("aGVsbG8="), "{seq:?}");
    }

    #[test]
    fn copy_sequence_encodes_control_characters_without_osc_injection() {
        let seq = copy_sequence("line one\nline two\ttab\u{1b}[31mred");
        assert!(!seq.contains('\n'), "{seq:?}");
        assert!(!seq.contains('\t'), "{seq:?}");
        assert_eq!(seq.matches('\u{1b}').count(), 2, "{seq:?}");
        assert!(seq.ends_with(ST), "{seq:?}");
    }

    #[test]
    fn copy_sequence_of_empty_content_is_still_a_valid_sequence() {
        let seq = copy_sequence("");
        assert_eq!(seq, format!("\u{1b}]52;c;{ST}"));
    }

    #[test]
    fn copy_sequence_differs_for_different_content() {
        assert_ne!(copy_sequence("one"), copy_sequence("two"));
    }

    #[test]
    fn copy_all_logs_returns_none_for_an_empty_buffer() {
        assert_eq!(copy_all_logs(&[]), None);
    }

    #[test]
    fn copy_all_logs_joins_every_line_with_newlines() {
        let logs = vec![
            "[INFO] first".to_string(),
            String::new(),
            "[ERROR] third".to_string(),
        ];
        assert_eq!(
            copy_all_logs(&logs).as_deref(),
            Some("[INFO] first\n\n[ERROR] third")
        );
    }

    #[test]
    fn copy_all_logs_keeps_a_single_line_verbatim() {
        let logs = vec!["[DEBUG] only".to_string()];
        assert_eq!(copy_all_logs(&logs).as_deref(), Some("[DEBUG] only"));
    }
}

//! Shared tracking of currently connected peers.
//!
//! Both the TUI (`AppState`) and the Flutter backend (`mobile_node`) drive the
//! same [`ConnectedTracker`] from the `PeerConnected`/`PeerDisconnected` swarm
//! events, so every frontend reports the same set of peers that are *currently*
//! connected (plus the most recent disconnection) instead of inventing its own
//! bookkeeping.

use std::collections::HashSet;

/// Tracks which peers are currently connected and, on disconnect, remembers the
/// most recent disconnection so frontends can show `last connected to <peer>`.
///
/// A single instance must only be mutated from the task that processes swarm
/// events (the TUI's command processor, or `mobile_node`'s event poller).
#[derive(Debug, Default, Clone)]
pub struct ConnectedTracker {
    connected: HashSet<String>,
    last_peer: Option<String>,
    last_time: Option<f64>,
}

impl ConnectedTracker {
    /// Create an empty tracker.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Record that `peer_id` just connected.
    pub fn on_peer_connected(&mut self, peer_id: String) {
        self.connected.insert(peer_id);
    }

    /// Record that `peer_id` just disconnected at `at` (epoch seconds).
    pub fn on_peer_disconnected(&mut self, peer_id: &str, at: f64) {
        self.connected.remove(peer_id);
        self.last_peer = Some(peer_id.to_string());
        self.last_time = Some(at);
    }

    /// Number of peers currently connected.
    #[must_use]
    pub fn len(&self) -> usize {
        self.connected.len()
    }

    /// Whether no peer is currently connected.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.connected.is_empty()
    }

    /// Iterate over the IDs of the currently connected peers (`HashSet` order).
    pub fn connected_peer_ids(&self) -> impl Iterator<Item = &str> {
        self.connected.iter().map(String::as_str)
    }

    /// The most recent disconnection as `(peer_id, epoch_seconds)`, if any.
    #[must_use]
    pub const fn last_disconnection(&self) -> Option<(&str, f64)> {
        match (&self.last_peer, self.last_time) {
            (Some(peer), Some(at)) => Some((peer.as_str(), at)),
            _ => None,
        }
    }
}

