//! Receiver-side state for the attachment files lane (§12).
//!
//! The files lane is receiver-driven: each `"meta"`/`"chunk"` request is a
//! separate `request_response` round-trip, so the partial blob and its
//! bookkeeping must live outside any single swarm event. This module owns that
//! process-wide in-flight map, validates and assembles chunks, serves requests
//! for blobs we hold, and reclaims transfers whose peer disappeared. Keeping it
//! out of `swarm_handler` gives the lane one clear home and lets its invariants
//! be tested without a live `Swarm`.

use crate::types::{StringMap, SwarmEvent};
use crate::{AppBehaviour, p2plog_debug};
use libp2p::swarm::Swarm;
use std::sync::{Mutex, OnceLock, PoisonError};
use std::time::{Duration, Instant};
use tokio::sync::mpsc;

/// Process-wide receiver state for in-flight attachment pulls.
///
/// The files lane (§12) is receiver-driven: each `"chunk"` request is a
/// separate round-trip, so the partial blob and its metadata must live outside
/// any single handler frame. Keyed by content address (the `file_id`).
static RECEIVING_FILES: OnceLock<Mutex<StringMap<InFlightReceive>>> = OnceLock::new();

/// How long a transfer may make no progress before the flush tick abandons it.
/// One round-trip is a single 1 MiB chunk, so five minutes without any chunk is
/// unambiguously a failed pull (e.g. a `request_response` outbound failure that
/// never surfaces as a disconnect). A parameter on `abandon_idle_transfers` so
/// the sweep is testable without waiting.
pub(crate) const FILE_TRANSFER_IDLE_TIMEOUT: Duration = Duration::from_secs(300);

/// One in-flight receive plus the bookkeeping needed to reclaim it when its
/// source disappears. `peer` ties the pull to the connection serving it (so a
/// disconnect abandons exactly that peer's transfers); `last_activity` is the
/// backstop for requests that fail without any disconnect.
struct InFlightReceive {
    file: crate::files::ReceivingFile,
    peer: String,
    last_activity: Instant,
}

fn receiving_files() -> &'static Mutex<StringMap<InFlightReceive>> {
    RECEIVING_FILES.get_or_init(|| Mutex::new(StringMap::default()))
}

/// Garbage-collect dead attachment blobs (files lane §12): `.part` partials of
/// interrupted pulls and orphaned blobs/rows nothing references any more.
///
/// The `attachment-gc` Cargo feature is the enable/disable switch: with the
/// feature off this returns a zeroed report and the store never deletes
/// anything, so a build can opt out of blob cleanup entirely. Blobs with a
/// transfer currently in flight are excluded, and anything younger than
/// [`GC_GRACE`](crate::files::GC_GRACE) is skipped.
///
/// # Errors
/// Returns an error if a sweep fails (see [`crate::files::gc`]).
#[cfg(feature = "attachment-gc")]
pub fn gc_stale_attachments() -> color_eyre::Result<crate::files::GcStats> {
    let active: std::collections::HashSet<String> = receiving_files()
        .lock()
        .unwrap_or_else(PoisonError::into_inner)
        .keys()
        .cloned()
        .collect();
    crate::files::gc(&active, crate::files::GC_GRACE)
}

/// No-op build of [`gc_stale_attachments`] when the `attachment-gc` feature is
/// off (see the feature's doc comment in Cargo.toml).
#[cfg(not(feature = "attachment-gc"))]
pub fn gc_stale_attachments() -> color_eyre::Result<crate::files::GcStats> {
    Ok(crate::files::GcStats::default())
}

/// Remove an in-flight transfer and discard its `.part` blob. Every abort path
/// (malformed chunk, peer error, oversized meta, disconnect, idle sweep) must go
/// through here so a later transfer of the same content address cannot append
/// to stale bytes.
fn abandon_transfer(file_id: &str) -> Option<InFlightReceive> {
    let partial = receiving_files()
        .lock()
        .unwrap_or_else(PoisonError::into_inner)
        .remove(file_id);
    if let Some(partial) = partial.as_ref() {
        partial.file.discard();
    }
    partial
}

/// Abandon every in-flight pull being served by `peer`. A disconnecting peer can
/// no longer send the remaining chunks, so leaving its entries in the map wedges
/// `maybe_start_fetch` (which skips addresses already in flight) and keeps the
/// startup GC from reclaiming the stale `.part` blob.
pub(crate) fn abandon_transfers_from(peer: &str) {
    let stale: Vec<String> = receiving_files()
        .lock()
        .unwrap_or_else(PoisonError::into_inner)
        .iter()
        .filter(|(_, transfer)| transfer.peer == peer)
        .map(|(file_id, _)| file_id.clone())
        .collect();
    for file_id in stale {
        p2plog_debug(format!(
            "abandoning file transfer {file_id}: peer {peer} disconnected"
        ));
        abandon_transfer(&file_id);
    }
}

/// Abandon transfers that have made no progress for longer than `timeout`.
/// Covers failures that never reach an `"error"` response — notably a
/// `request_response` outbound failure (timeout/protocol error) with no peer
/// disconnect — which would otherwise leave a transfer wedged until restart.
pub(crate) fn abandon_idle_transfers(timeout: Duration) {
    let stale: Vec<String> = receiving_files()
        .lock()
        .unwrap_or_else(PoisonError::into_inner)
        .iter()
        .filter(|(_, transfer)| transfer.last_activity.elapsed() > timeout)
        .map(|(file_id, _)| file_id.clone())
        .collect();
    for file_id in stale {
        p2plog_debug(format!("abandoning idle file transfer {file_id}"));
        abandon_transfer(&file_id);
    }
}

/// What applying one chunk response should do next.
#[derive(Debug)]
enum ChunkOutcome {
    /// All bytes are in: hand the assembled transfer to the finalizer.
    Complete(crate::files::ReceivingFile),
    /// Append succeeded but the file is incomplete: pull chunk `u64` next.
    Continue(u64),
    /// The transfer cannot go on (unknown/errored); any partial is discarded.
    Failed,
}

/// Validate one chunk response against the transfer's advertised size and
/// current progress. Rejecting empty/mis-indexed/oversized chunks is what stops
/// a peer from keeping the receiver in the same request/response loop forever.
fn chunk_is_expected(
    receiving: &crate::files::ReceivingFile,
    chunk_index: Option<u64>,
    total_chunks: Option<u64>,
    chunk_size: Option<u64>,
    data_len: u64,
) -> bool {
    let expected = receiving.received.div_euclid(crate::files::FILE_CHUNK_SIZE);
    let remaining = receiving.size.saturating_sub(receiving.received);
    let advertised = crate::files::total_chunks(receiving.size);
    let expected_len = if expected.saturating_add(1) < advertised {
        crate::files::FILE_CHUNK_SIZE
    } else {
        remaining
    };
    data_len > 0
        && data_len == expected_len
        && chunk_index == Some(expected)
        && total_chunks.is_none_or(|value| value == advertised)
        && chunk_size.is_none_or(|value| value == crate::files::FILE_CHUNK_SIZE)
}

/// Append one chunk's bytes to the in-flight transfer and decide what happens
/// next. Kept fully synchronous so no `MutexGuard` (not `Send`) ever crosses an
/// `.await` in the handler task.
fn apply_chunk(file_id: &str, response: crate::FileTransferResponse) -> ChunkOutcome {
    let mut transfers = receiving_files()
        .lock()
        .unwrap_or_else(PoisonError::into_inner);
    let Some(transfer) = transfers.get_mut(file_id) else {
        p2plog_debug(format!("chunk for unknown transfer {file_id}"));
        return ChunkOutcome::Failed;
    };
    let Some(data) = response.data else {
        p2plog_debug(format!("chunk for {file_id} carried no data"));
        drop(transfers);
        abandon_transfer(file_id);
        return ChunkOutcome::Failed;
    };
    let data_len = u64::try_from(data.len()).unwrap_or(u64::MAX);
    if !chunk_is_expected(
        &transfer.file,
        response.chunk_index,
        response.total_chunks,
        response.chunk_size,
        data_len,
    ) {
        p2plog_debug(format!("rejected unexpected chunk for {file_id}"));
        drop(transfers);
        abandon_transfer(file_id);
        return ChunkOutcome::Failed;
    }
    if let Err(e) = transfer.file.write_chunk(&data) {
        p2plog_debug(format!("failed to write chunk for {file_id}: {e}"));
        drop(transfers);
        abandon_transfer(file_id);
        return ChunkOutcome::Failed;
    }
    let complete = transfer.file.is_complete();
    let received = transfer.file.received;
    // Every accepted chunk proves the peer is still serving the pull, so the
    // idle sweep must count from the latest one, not from the meta handshake.
    transfer.last_activity = Instant::now();
    if complete {
        let partial = transfers.remove(file_id);
        drop(transfers);
        return partial.map_or(ChunkOutcome::Failed, |t| ChunkOutcome::Complete(t.file));
    }
    drop(transfers);
    ChunkOutcome::Continue(received.div_euclid(crate::files::FILE_CHUNK_SIZE))
}

/// Atomically register a fresh in-flight receive for `file_id` from `peer`.
///
/// Returns `true` when a new transfer was registered, `false` when one is
/// already in flight (a duplicate `meta` response) or the partial file could
/// not be opened. A duplicate must never replace the live transfer: a fresh
/// `ReceivingFile` would reset `received` to 0 and discard the `.part` bytes
/// the live transfer is still assembling, desyncing the chunk index from the
/// peer. (A stale `.part` from a *killed* process is handled separately by
/// [`ReceivingFile::new`](crate::files::ReceivingFile::new).)
fn begin_receive(peer: &str, file_id: &str, name: &str, mime: Option<String>, size: u64) -> bool {
    let mut transfers = receiving_files()
        .lock()
        .unwrap_or_else(PoisonError::into_inner);
    if transfers.contains_key(file_id) {
        p2plog_debug(format!("ignoring duplicate meta for transfer {file_id}"));
        return false;
    }
    let file = match crate::files::ReceivingFile::new(file_id, name, mime, size) {
        Ok(file) => file,
        Err(e) => {
            p2plog_debug(format!("failed to open receiving file for {file_id}: {e}"));
            return false;
        }
    };
    transfers.insert(
        file_id.to_string(),
        InFlightReceive {
            file,
            peer: peer.to_string(),
            last_activity: Instant::now(),
        },
    );
    true
}

/// Receiver side of the attachment pull: if we neither hold the blob in the
/// store nor have a transfer in flight, ask the source peer for its metadata
/// to begin the chunk chain. Content-addressed, so an already-stored file
/// short-circuits the whole transfer.
pub(crate) fn maybe_start_fetch(
    peer_id: &libp2p::PeerId,
    attachment: &crate::files::MessageAttachment,
    swarm: &mut Swarm<AppBehaviour>,
) {
    // The descriptor rides in on the wire; never turn an unvalidated id into a
    // request (nor, downstream, a filesystem path).
    if !crate::files::is_valid_file_id(&attachment.file_id) {
        p2plog_debug(format!(
            "ignoring attachment with invalid file id {:?}",
            attachment.file_id
        ));
        return;
    }
    if crate::files::file_path(&attachment.file_id).is_none()
        && !receiving_files()
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .contains_key(&attachment.file_id)
    {
        request_file_meta(swarm, peer_id, &attachment.file_id);
    }
}

fn request_file_meta(swarm: &mut Swarm<AppBehaviour>, peer_id: &libp2p::PeerId, file_id: &str) {
    let request = crate::FileTransfer {
        kind: "meta".to_string(),
        file_id: file_id.to_string(),
        chunk_index: None,
    };
    let _ = swarm
        .behaviour_mut()
        .file_transfer
        .send_request(peer_id, request);
}

fn request_file_chunk(
    swarm: &mut Swarm<AppBehaviour>,
    peer_id: &libp2p::PeerId,
    file_id: &str,
    chunk_index: u64,
) {
    let request = crate::FileTransfer {
        kind: "chunk".to_string(),
        file_id: file_id.to_string(),
        chunk_index: Some(chunk_index),
    };
    let _ = swarm
        .behaviour_mut()
        .file_transfer
        .send_request(peer_id, request);
}

/// Handle the file-transfer lane (§12).
///
/// Requests come from a peer who wants a blob we hold in the store: serve
/// either its metadata (name/size/mime plus the chunking parameters) or one
/// chunk of bytes. Responses come from a peer we are pulling from: `"meta"`
/// starts a transfer, each `"chunk"` appends its bytes (and requests the next
/// one unless the transfer just completed), and `"error"` abandons it.
pub(crate) async fn handle_file_transfer(
    message: libp2p::request_response::Message<crate::FileTransfer, crate::FileTransferResponse>,
    peer: libp2p::PeerId,
    event_tx: &mpsc::Sender<SwarmEvent>,
    swarm: &mut Swarm<AppBehaviour>,
) {
    let peer_id_str = peer.to_string();
    match message {
        libp2p::request_response::Message::Request {
            request, channel, ..
        } => serve_file_transfer_request(&request, channel, swarm),
        libp2p::request_response::Message::Response { response, .. } => {
            handle_file_transfer_response(response, peer, peer_id_str, event_tx, swarm).await;
        }
    }
}

/// Serve a transfer request from a peer who wants a blob we hold: answer
/// `"meta"` with the descriptor + chunking parameters, `"chunk"` with the
/// requested slice, or `"error"` for anything else.
fn serve_file_transfer_request(
    request: &crate::FileTransfer,
    channel: libp2p::request_response::ResponseChannel<crate::FileTransferResponse>,
    swarm: &mut Swarm<AppBehaviour>,
) {
    let file_id = request.file_id.clone();
    let response = match request.kind.as_str() {
        "meta" => match crate::files::serve_file_meta(&file_id) {
            Some((name, size, mime)) => crate::FileTransferResponse {
                kind: "meta".to_string(),
                file_id,
                name: Some(name),
                size: Some(size),
                mime,
                total_chunks: Some(crate::files::total_chunks(size)),
                chunk_size: Some(crate::files::FILE_CHUNK_SIZE),
                ..Default::default()
            },
            None => crate::FileTransferResponse {
                kind: "error".to_string(),
                file_id,
                reason: Some("unknown file".to_string()),
                ..Default::default()
            },
        },
        "chunk" => {
            let chunk_index = request.chunk_index.unwrap_or_default();
            match crate::files::serve_chunk(&file_id, chunk_index) {
                Some(data) => crate::FileTransferResponse {
                    kind: "chunk".to_string(),
                    file_id,
                    chunk_index: Some(chunk_index),
                    data: Some(data),
                    ..Default::default()
                },
                None => crate::FileTransferResponse {
                    kind: "error".to_string(),
                    file_id: file_id.clone(),
                    reason: Some(format!("no chunk {chunk_index} for {file_id}")),
                    ..Default::default()
                },
            }
        }
        other => crate::FileTransferResponse {
            kind: "error".to_string(),
            file_id,
            reason: Some(format!("unknown file-transfer kind: {other}")),
            ..Default::default()
        },
    };
    let _ = swarm
        .behaviour_mut()
        .file_transfer
        .send_response(channel, response);
}

/// Receiver side of the pull: `"meta"` starts a transfer (refusing oversized
/// files and finishing instantly when empty), each `"chunk"` appends its bytes
/// and pulls the next one when incomplete, and `"error"` abandons the transfer.
async fn handle_file_transfer_response(
    response: crate::FileTransferResponse,
    peer: libp2p::PeerId,
    peer_id_str: String,
    event_tx: &mpsc::Sender<SwarmEvent>,
    swarm: &mut Swarm<AppBehaviour>,
) {
    match response.kind.as_str() {
        "meta" => {
            let file_id = response.file_id.clone();
            if !crate::files::is_valid_file_id(&file_id) {
                p2plog_debug(format!(
                    "refusing transfer with invalid file id {file_id:?}"
                ));
                return;
            }
            let size = response.size.unwrap_or_default();
            if size > crate::files::MAX_ATTACHMENT_SIZE {
                // Drop the partial too: a later valid meta for the same content
                // address must not append to bytes from the refused transfer.
                abandon_transfer(&file_id);
                p2plog_debug(format!(
                    "refusing oversized attachment {file_id} ({size} bytes)"
                ));
                return;
            }
            if !begin_receive(
                &peer_id_str,
                &file_id,
                response.name.as_deref().unwrap_or("attachment"),
                response.mime.clone(),
                size,
            ) {
                return;
            }
            // A zero-length file completes immediately.
            if size == 0 {
                let receiving = receiving_files()
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .remove(&file_id)
                    .map(|transfer| transfer.file);
                if let Some(receiving) = receiving {
                    finish_received_file(receiving, peer_id_str, event_tx).await;
                }
            } else {
                request_file_chunk(swarm, &peer, &file_id, 0);
            }
        }
        "chunk" => {
            let file_id = response.file_id.clone();
            match apply_chunk(&file_id, response) {
                ChunkOutcome::Complete(partial) => {
                    finish_received_file(partial, peer_id_str, event_tx).await;
                }
                ChunkOutcome::Continue(next_chunk) => {
                    request_file_chunk(swarm, &peer, &file_id, next_chunk);
                }
                ChunkOutcome::Failed => {
                    p2plog_debug(format!("file transfer {file_id} could not continue"));
                }
            }
        }
        "error" => {
            let file_id = response.file_id.clone();
            let reason = response.reason.unwrap_or_default();
            abandon_transfer(&file_id);
            p2plog_debug(format!("file transfer {file_id} failed: {reason}"));
        }
        other => p2plog_debug(format!("unknown file-transfer response kind: {other}")),
    }
}

/// Surface an assembled attachment to the frontends. The transfer is already
/// drained from the in-flight map and fully stored by the time this runs.
async fn finish_received_file(
    receiving: crate::files::ReceivingFile,
    peer_id: String,
    event_tx: &mpsc::Sender<SwarmEvent>,
) {
    let file_id = receiving.file_id.clone();
    let name = receiving.name.clone();
    let path = match receiving.finalize() {
        Ok(path) => path,
        Err(e) => {
            p2plog_debug(format!("failed to finalize attachment {file_id}: {e}"));
            return;
        }
    };
    let _ = event_tx
        .send(SwarmEvent::FileReceived {
            peer_id: peer_id.clone(),
            file_id: file_id.clone(),
            name,
            path,
        })
        .await;
    // A share manifest may have been waiting on this exact blob. Applying it
    // here (rather than in the UI) keeps folder convergence independent of
    // which frontend is running.
    for applied in crate::shares::note_blob_available(&file_id, &peer_id) {
        let _ = event_tx
            .send(SwarmEvent::ShareUpdated {
                peer_id: applied.peer_id,
                share_id: applied.share_id,
                revision: applied.revision,
                written: applied.stats.written,
                removed: applied.stats.removed,
            })
            .await;
    }
}

#[cfg(test)]
#[path = "../tests/unit/unit_file_transfer.rs"]
mod tests;

//! Content-addressed file attachment store (files lane §12).
//!
//! Every attachment is addressed by the SHA-256 hex of its bytes (`file_id`),
//! so repeated transfers of identical content reuse a single on-disk blob,
//! transfer integrity is verified by re-hashing on finalize, and receivers
//! deduplicate simply by checking whether `file_id` is already stored.
//!
//! The bytes live under `files_dir()` (a `*.files` directory derived from the
//! active database path); the [`files`](crate::generated::schema::files) table
//! records metadata plus the absolute stored path so serving (and the
//! frontends' open/save affordances) have exactly one lookup.
//!
//! Transfers are receiver-driven over the `/p2p-chat/files/1.0.0`
//! `request_response` lane: the receiver asks for metadata, then pulls
//! fixed-size chunks sequentially. Senders prepare a file with
//! [`store_outgoing_file`] (which also verifies the size cap) so it is ready to
//! serve as soon as the message it rides on arrives.

use crate::generated::models_insertable::NewFile;
use crate::generated::schema::files::dsl::files;
use color_eyre::eyre::{Context, eyre};
use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::time::Duration;

/// Size of one chunk pulled over the file-transfer lane (fits the cbor codec's
/// default 10 MiB response cap).
pub const FILE_CHUNK_SIZE: u64 = 1024 * 1024;

/// Accept/reject ceiling for a single attachment. Bounds transfer memory and
/// bandwidth; the metadata handshake advertises `size` so the receiver refuses
/// (and answers `error`) before pulling.
pub const MAX_ATTACHMENT_SIZE: u64 = 64 * 1024 * 1024;

/// Delivery-facing descriptor of one file attachment.
///
/// Rides inside `DirectMessage`/`BroadcastMessage`/`GroupMessage` on the wire
/// and in the `attachment_json` column of `messages`/`group_messages` on disk.
/// The descriptor itself identifies the content; the bytes are fetched over the
/// file lane on the receiver's side.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct MessageAttachment {
    /// SHA-256 hex of the file bytes (content address)
    pub file_id: String,
    /// Original filename as the sender advertised it
    pub name: String,
    /// Total byte length
    pub size: u64,
    /// Best-effort MIME type hint (`None` when unknown)
    pub mime: Option<String>,
}

/// Render an attachment descriptor as a plain-text chat chip, e.g.
/// `[file] notes.txt (2 KiB)`.
///
/// Used by the TUI's chat rows and sent-message echo; the Flutter chip builds
/// the same string from the descriptor's `size_label`, so a sent and a received
/// file always look identical.
#[must_use]
pub fn file_chip(attachment: &MessageAttachment) -> String {
    format!(
        "[file] {} ({})",
        attachment.name,
        format_file_size(attachment.size)
    )
}

/// Human-readable byte size: `512 B`, `1.5 KiB`, `64 MiB` — binary units
/// (1 KiB = 1024 B), at most one decimal, trailing `.0` dropped.
///
/// This is the single formatter behind every chip: the TUI renders
/// [`file_chip`], and the Flutter chip displays the label Rust attaches to
/// `MobileAttachment::size_label` (see `mobile_node`), so no frontend does its
/// own byte math.
#[must_use]
pub fn format_file_size(bytes: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KiB", "MiB", "GiB", "TiB"];
    if bytes < 1024 {
        return format!("{bytes} B");
    }
    let mut unit = 1_usize;
    let mut divisor: u64 = 1024;
    loop {
        // Tenths of the chosen unit, rounded to nearest. `u128` is wide enough
        // that none of these products can overflow for any `u64` input.
        let scaled = u128::from(bytes)
            .saturating_mul(10)
            .saturating_add(u128::from(divisor).saturating_div(2));
        let tenths = scaled.checked_div(u128::from(divisor)).unwrap_or(0);
        let next_unit = unit.saturating_add(1);
        // Rounding up to 1024 tenths would print "1024 KiB"; step up instead.
        if tenths >= 10_240 && next_unit < UNITS.len() {
            unit = next_unit;
            divisor = divisor.saturating_mul(1024);
            continue;
        }
        let whole = tenths.saturating_div(10);
        let frac = tenths.checked_rem(10).unwrap_or(0);
        let suffix = UNITS.get(unit).copied().unwrap_or("B");
        return if frac == 0 {
            format!("{whole} {suffix}")
        } else {
            format!("{whole}.{frac} {suffix}")
        };
    }
}

/// Compose a chat line body from message text plus an attachment descriptor:
/// text first, chip appended; an attachment-only message renders as just the
/// chip so a file never shows up as a blank row.
#[must_use]
pub fn render_message_body(content: &str, attachment: Option<&MessageAttachment>) -> String {
    if content.trim().is_empty() {
        attachment.map_or_else(String::new, file_chip)
    } else if let Some(attachment) = attachment {
        format!("{content} {}", file_chip(attachment))
    } else {
        content.to_string()
    }
}

/// Hydrate a chat row body from a DB `attachment_json` column (files lane §12)
/// plus the stored message text — the inverse of what the send path persisted.
#[must_use]
pub fn render_stored_body(content: &str, attachment_json: Option<&str>) -> String {
    render_message_body(
        content,
        attachment_json.and_then(attachment_from_json).as_ref(),
    )
}

/// Hydrate and decorate a stored chat row body (US-005).
///
/// Adds the attachment chip and local-edit marker. Shared by the DM and group
/// edit paths so the in-memory transcript after an edit matches the next reload.
#[must_use]
pub fn render_stored_display_body(
    content: &str,
    attachment_json: Option<&str>,
    edited: bool,
) -> String {
    let body = render_stored_body(content, attachment_json);
    crate::fmt::with_edited_marker_if(edited, &body)
}

/// SHA-256 of `data` as a lowercase hex string — the content address
/// (`file_id`) for the bytes.
#[must_use]
pub fn hash_bytes(data: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    use std::fmt::Write;

    let mut hasher = Sha256::new();
    hasher.update(data);
    let digest = hasher.finalize();
    let mut hex = String::with_capacity(digest.len().saturating_mul(2));
    for byte in digest {
        let _ = write!(hex, "{byte:02x}");
    }
    hex
}

/// Directory that holds the attachment blobs, derived from the active database
/// path: `<db>.files`. Created on first use.
///
/// # Errors
/// Returns an error if the directory cannot be created.
pub fn files_dir() -> color_eyre::Result<std::path::PathBuf> {
    let dir = std::path::PathBuf::from(format!("{}.files", crate::get_database_url()));
    std::fs::create_dir_all(&dir)
        .wrap_err_with(|| format!("failed to create attachment store dir {}", dir.display()))?;
    Ok(dir)
}

/// Whether `file_id` is a canonical content address as produced by
/// [`hash_bytes`]: exactly 64 lowercase hexadecimal characters.
///
/// Every path in the store is built by appending this value to a directory, so
/// validating it at the trust boundary is what keeps a network-supplied
/// descriptor from escaping the store via path traversal (e.g.
/// `"../../../.bashrc"`) or colliding with a non-blob file. Requiring lowercase
/// matches [`hash_bytes`] exactly and prevents duplicate blobs for the same
/// bytes under differently-cased ids.
#[must_use]
pub fn is_valid_file_id(file_id: &str) -> bool {
    file_id.len() == 64
        && file_id
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

/// Absolute on-disk path a `file_id`'s blob lives at (whether or not it exists
/// yet).
///
/// # Errors
/// Returns an error if `file_id` is not a canonical content address or the
/// store directory cannot be created.
pub fn store_path_for(file_id: &str) -> color_eyre::Result<std::path::PathBuf> {
    if !is_valid_file_id(file_id) {
        return Err(eyre!("invalid attachment file id: {file_id:?}"));
    }
    Ok(files_dir()?.join(file_id))
}

/// Best-effort MIME type hint from a filename's final extension.
#[must_use]
pub fn mime_from_name(name: &str) -> Option<String> {
    let ext = name.rsplit('.').next()?.to_ascii_lowercase();
    let mime = match ext.as_str() {
        "txt" | "md" | "log" | "rtf" => "text/plain",
        "html" | "htm" => "text/html",
        "csv" => "text/csv",
        "pdf" => "application/pdf",
        "json" => "application/json",
        "zip" => "application/zip",
        "gz" => "application/gzip",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "webp" => "image/webp",
        "svg" => "image/svg+xml",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "ogg" | "oga" => "audio/ogg",
        "m4a" => "audio/mp4",
        "mp4" | "m4v" => "video/mp4",
        "webm" => "video/webm",
        "mov" => "video/quicktime",
        _ => return None,
    };
    Some(mime.to_string())
}

/// Serialize an attachment descriptor for the `attachment_json` column.
#[must_use]
pub fn attachment_to_json(attachment: &MessageAttachment) -> Option<String> {
    serde_json::to_string(attachment).ok()
}

/// Deserialize an attachment descriptor from `attachment_json`.
#[must_use]
pub fn attachment_from_json(json: &str) -> Option<MessageAttachment> {
    serde_json::from_str(json).ok()
}

/// Prepare a local file for sending: copy (and hash) its bytes into the store
/// and record the `files` row. Returns the delivery descriptor the frontend
/// attaches to the outgoing message.
///
/// Idempotent by content address: a file already in the store is not rewritten.
///
/// # Errors
/// Returns an error if the file is missing, unreadable, or over
/// [`MAX_ATTACHMENT_SIZE`].
pub fn store_outgoing_file(path: &str) -> color_eyre::Result<MessageAttachment> {
    let data =
        std::fs::read(path).wrap_err_with(|| format!("failed to read attachment {path:?}"))?;
    let name = std::path::Path::new(path).file_name().map_or_else(
        || "attachment".to_string(),
        |s| s.to_string_lossy().into_owned(),
    );
    store_outgoing_bytes(&name, &data)
}

/// Store attachment bytes received out-of-band (the web upload route),
/// content-addressed exactly like [`store_outgoing_file`].
///
/// SHA-256 `file_id`, blob under [`files_dir`], row in the `files` table.
///
/// # Errors
/// Returns an error if `data` is over [`MAX_ATTACHMENT_SIZE`] or the blob
/// cannot be written/registered.
pub fn store_outgoing_bytes(name: &str, data: &[u8]) -> color_eyre::Result<MessageAttachment> {
    let size =
        u64::try_from(data.len()).map_err(|_| eyre!("attachment byte length out of range"))?;
    if size > MAX_ATTACHMENT_SIZE {
        return Err(eyre!(
            "attachment too large: {size} bytes (max {MAX_ATTACHMENT_SIZE})"
        ));
    }
    let file_id = hash_bytes(data);
    let name = if name.is_empty() {
        "attachment".to_string()
    } else {
        name.to_string()
    };
    let mime = mime_from_name(&name);

    let store_path = store_path_for(&file_id)?;
    if !store_path.exists() {
        std::fs::write(&store_path, data).wrap_err_with(|| {
            format!("failed to write attachment blob {}", store_path.display())
        })?;
    }
    insert_file_row(&file_id, &name, size, mime.as_deref(), 1, &store_path)?;

    Ok(MessageAttachment {
        file_id,
        name,
        size,
        mime,
    })
}

/// Canonical on-disk path of a blob that still exists.
///
/// Every writer stores bytes at [`store_path_for`] and records that same path
/// in the `files` row, so this is the single source of truth for blob bytes —
/// including on the serving side, where a per-chunk DB lookup would be waste.
fn canonical_blob_path(file_id: &str) -> Option<std::path::PathBuf> {
    let path = store_path_for(file_id).ok()?;
    path.exists().then_some(path)
}

/// Path of a stored attachment, but only when both halves of storage agree:
/// the metadata row exists and the blob is still on disk.
///
/// A `files` row alone is not proof of availability — the blob can be deleted
/// out of band while the row survives (GC only sweeps at startup). Treating
/// such a row as available makes the receiver skip the re-download and hands
/// the frontends a path they cannot open. Conversely, a blob without a row
/// cannot be served to peers (no name/size to advertise) and is GC's orphan
/// class, so it is not advertised either.
fn stored_blob_path(file_id: &str) -> Option<std::path::PathBuf> {
    find_file(file_id).ok().flatten()?;
    canonical_blob_path(file_id)
}

/// Absolute path of a stored attachment, as the frontends open/save it.
#[must_use]
pub fn file_path(file_id: &str) -> Option<String> {
    stored_blob_path(file_id).map(|p| p.display().to_string())
}

/// Number of fixed-size chunks a `size`-byte file splits into ({0} for empty).
#[must_use]
pub const fn total_chunks(size: u64) -> u64 {
    size.div_ceil(FILE_CHUNK_SIZE)
}

/// Serve the metadata handshake for a stored file.
///
/// Advertises a file only when its `files` row *and* its blob are present: a
/// stale row whose blob vanished must trigger a fresh pull on the receiver
/// instead of a meta/chunk pair the sender cannot fulfil.
#[must_use]
pub fn serve_file_meta(file_id: &str) -> Option<(String, u64, Option<String>)> {
    let row = find_file(file_id).ok().flatten()?;
    canonical_blob_path(file_id)?;
    let size = u64::try_from(row.size).unwrap_or(u64::MAX);
    Some((row.name, size, row.mime))
}

/// Serve one chunk of a stored file (the sender side of the pull-based lane).
#[must_use]
pub fn serve_chunk(file_id: &str, chunk_index: u64) -> Option<Vec<u8>> {
    use std::io::{Read, Seek, SeekFrom};
    let offset = chunk_index.checked_mul(FILE_CHUNK_SIZE)?;
    // The metadata handshake already checked the row and the blob; each chunk
    // only needs the canonical on-disk path, so no DB query is paid per chunk.
    let path = store_path_for(file_id).ok()?;
    if !path.exists() {
        return None;
    }
    let mut file = std::fs::File::open(&path).ok()?;
    let file_len = file.metadata().ok()?.len();
    if offset >= file_len {
        return None;
    }
    file.seek(SeekFrom::Start(offset)).ok()?;
    let remaining = file_len.saturating_sub(offset);
    let take = usize::try_from(remaining.min(FILE_CHUNK_SIZE)).ok()?;
    let mut data = vec![0; take];
    file.read_exact(&mut data).ok()?;
    Some(data)
}

/// Look up the `files` row for a `file_id`.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn find_file(
    file_id: &str,
) -> color_eyre::Result<Option<crate::generated::models_queryable::File>> {
    use diesel::{
        ExpressionMethods, OptionalExtension, QueryDsl, RunQueryDsl as _, SelectableHelper as _,
    };
    let conn = &mut crate::sqlite_connect()?;
    files
        .filter(crate::generated::schema::files::file_id.eq(file_id))
        .select(crate::generated::models_queryable::File::as_select())
        .first(conn)
        .optional()
        .wrap_err("failed to look up attachment")
}

fn insert_file_row(
    file_id: &str,
    name: &str,
    size: u64,
    mime: Option<&str>,
    direction: i32,
    path: &std::path::Path,
) -> color_eyre::Result<()> {
    use diesel::RunQueryDsl as _;
    let conn = &mut crate::sqlite_connect()?;
    let row = NewFile {
        file_id: file_id.to_string(),
        name: name.to_string(),
        size: i64::try_from(size).unwrap_or(i64::MAX),
        mime: mime.map(std::string::ToString::to_string),
        direction,
        path: path.display().to_string(),
    };
    diesel::insert_into(files)
        .values(&row)
        .on_conflict(crate::generated::schema::files::file_id)
        .do_nothing()
        .execute(conn)
        .wrap_err("failed to record attachment file")?;
    Ok(())
}

/// In-progress inbound transfer assembled chunk-by-chunk on the receiver.
///
/// Owned by the swarm handler (keyed by `file_id` in a process-wide map), so
/// partial progress survives the individual request/response round-trips. The
/// blob is appended to a temporary `.part` path inside [`files_dir`] and only
/// renamed into the store once the hash verifies against `file_id`.
#[derive(Debug, Clone)]
pub struct ReceivingFile {
    /// Content address the delivered bytes must match
    pub file_id: String,
    /// Original filename advertised by the sender
    pub name: String,
    /// MIME hint advertised by the sender
    pub mime: Option<String>,
    /// Expected byte length (from the metadata handshake)
    pub size: u64,
    /// Bytes received so far
    pub received: u64,
    /// Temporary in-progress path (finalized via [`ReceivingFile::finalize`])
    pub path: std::path::PathBuf,
}

impl ReceivingFile {
    /// Start assembling a transfer in the store directory.
    ///
    /// A partial left by a process killed mid-transfer is removed here: the
    /// in-memory receive map does not survive a restart, so a fast restart
    /// (inside [`GC_GRACE`], before GC can reclaim it) would otherwise append
    /// fresh chunks after the stale bytes and fail the final hash check. Every
    /// call is a genuinely fresh transfer — duplicate `meta` responses are
    /// rejected by the receiver before reaching here — so any existing `.part`
    /// at this content address is stale by definition.
    ///
    /// # Errors
    /// Returns an error if `file_id` is not a canonical content address, the
    /// store directory cannot be created, or a stale partial cannot be removed.
    pub fn new(
        file_id: &str,
        name: &str,
        mime: Option<String>,
        size: u64,
    ) -> color_eyre::Result<Self> {
        if !is_valid_file_id(file_id) {
            return Err(eyre!("invalid attachment file id: {file_id:?}"));
        }
        let path = files_dir()?.join(format!("{file_id}.part"));
        match std::fs::remove_file(&path) {
            Ok(()) => {}
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => {
                return Err(e).wrap_err_with(|| {
                    format!(
                        "failed to discard stale attachment partial {}",
                        path.display()
                    )
                });
            }
        }
        Ok(Self {
            file_id: file_id.to_string(),
            name: name.to_string(),
            mime,
            size,
            received: 0,
            path,
        })
    }

    /// Append one chunk's bytes to the in-progress blob.
    ///
    /// # Errors
    /// Returns an error if the append fails.
    pub fn write_chunk(&mut self, data: &[u8]) -> color_eyre::Result<()> {
        use std::io::Write;
        let mut file = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&self.path)
            .wrap_err("failed to open in-progress attachment")?;
        file.write_all(data)
            .wrap_err("failed to append attachment chunk")?;
        self.received = self
            .received
            .saturating_add(u64::try_from(data.len()).unwrap_or(u64::MAX));
        Ok(())
    }

    /// Whether every advertised byte has arrived.
    #[must_use]
    pub const fn is_complete(&self) -> bool {
        self.received >= self.size
    }

    /// Verify the assembled bytes hash to `file_id`, move them into the store,
    /// and record the `files` row (direction = received). On any mismatch the
    /// partial blob is removed. An empty file (size 0) needs no `.part` blob:
    /// the store entry is created directly.
    ///
    /// # Errors
    /// Returns an error if the blob is unreadable, the hash does not match, or
    /// the store/DB update fails.
    pub fn finalize(self) -> color_eyre::Result<String> {
        let store_path = store_path_for(&self.file_id)?;
        if self.size == 0 {
            // An empty file is still content: its address must be the SHA-256
            // of the empty byte string. Without this check a peer could claim
            // any content address with size 0 and get an empty blob stored
            // under it (poisoning the store and any future lookup/serve).
            let empty_id = hash_bytes(&[]);
            if empty_id != self.file_id {
                let _ = std::fs::remove_file(&self.path);
                return Err(eyre!(
                    "empty attachment hash mismatch (expected {}, got {empty_id})",
                    self.file_id
                ));
            }
            if !store_path.exists() {
                std::fs::write(&store_path, []).wrap_err_with(|| {
                    format!(
                        "failed to create empty attachment blob {}",
                        store_path.display()
                    )
                })?;
            }
            insert_file_row(
                &self.file_id,
                &self.name,
                self.size,
                self.mime.as_deref(),
                0,
                &store_path,
            )?;
            return Ok(store_path.display().to_string());
        }
        let data = std::fs::read(&self.path).wrap_err_with(|| {
            format!(
                "failed to read in-progress attachment {}",
                self.path.display()
            )
        })?;
        if hash_bytes(&data) != self.file_id {
            let _ = std::fs::remove_file(&self.path);
            return Err(eyre!(
                "attachment hash mismatch (expected {}, got {})",
                self.file_id,
                hash_bytes(&data)
            ));
        }
        std::fs::rename(&self.path, &store_path).wrap_err_with(|| {
            format!(
                "failed to finalize attachment {} -> {}",
                self.path.display(),
                store_path.display()
            )
        })?;
        insert_file_row(
            &self.file_id,
            &self.name,
            self.size,
            self.mime.as_deref(),
            0,
            &store_path,
        )?;
        Ok(store_path.display().to_string())
    }

    /// Drop the in-progress blob (transfer failed or was aborted).
    pub fn discard(&self) {
        let _ = std::fs::remove_file(&self.path);
    }
}

/// Minimum age a blob must reach before the GC is allowed to delete it.
///
/// Guards the brief window after `ReceivingFile::finalize` renames a blob into
/// the store but before its `files` row (and the message reference) lands, and
/// anything else that is still being written.
pub const GC_GRACE: Duration = Duration::from_mins(1);

/// What one attachment-GC pass deleted (files lane §12).
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct GcStats {
    /// `.part` partials of interrupted pulls that were removed
    pub incomplete_removed: usize,
    /// Full blobs / broken `files` rows that were removed
    pub orphans_removed: usize,
}

/// Attachment garbage collection (blob lifecycle, files lane §12): deletes
/// store entries nothing can use any more.
///
/// Two classes are swept:
/// - **Incomplete**: `.part` partials from interrupted pulls (crashes, aborted
///   transfers) with no transfer in flight backing them.
/// - **Overwritten/orphaned**: full blobs no live message references (superseded
///   content after a DB reset or message loss), blobs detached from their
///   `files` row, and `files` rows whose blob is missing on disk.
///
/// `active` is the set of `file_id`s currently being pulled (never swept) and
/// `grace` the minimum blob age before removal. Invocation is the knob: the
/// feature-gated `crate::file_transfer::gc_stale_attachments` only runs it when
/// the `attachment-gc` Cargo feature is on.
///
/// # Errors
/// Returns an error if the store directory cannot be created or a DB query
/// fails; individual unreadable/deleted blobs are skipped, not fatal.
pub fn gc<S: std::hash::BuildHasher>(
    active: &HashSet<String, S>,
    grace: Duration,
) -> color_eyre::Result<GcStats> {
    Ok(GcStats {
        incomplete_removed: sweep_incomplete_parts(active, grace)?,
        orphans_removed: sweep_orphan_blobs(grace)?,
    })
}

/// Remove every `.part` partial whose `file_id` has no transfer in flight and
/// that is older than `grace`; returns how many were deleted.
fn sweep_incomplete_parts<S: std::hash::BuildHasher>(
    active: &HashSet<String, S>,
    grace: Duration,
) -> color_eyre::Result<usize> {
    let mut removed = 0usize;
    for entry in std::fs::read_dir(files_dir()?).wrap_err("failed to scan attachment store")? {
        let entry = entry.wrap_err("failed to read attachment store entry")?;
        let name = entry.file_name().to_string_lossy().into_owned();
        let Some(file_id) = name.strip_suffix(".part") else {
            continue;
        };
        if active.contains(file_id) || !blob_older_than(entry.path().as_path(), grace) {
            continue;
        }
        if std::fs::remove_file(entry.path()).is_ok() {
            removed = removed.saturating_add(1);
        }
    }
    Ok(removed)
}

/// Remove blobs nothing can use any more (see [`gc`]); returns how many
/// artifacts (blobs or rows) were deleted.
fn sweep_orphan_blobs(grace: Duration) -> color_eyre::Result<usize> {
    let referenced = referenced_file_ids()?;
    let mut removed = 0usize;
    for entry in std::fs::read_dir(files_dir()?).wrap_err("failed to scan attachment store")? {
        let entry = entry.wrap_err("failed to read attachment store entry")?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if is_part_blob(&name)
            || !entry.file_type().is_ok_and(|t| t.is_file())
            || !blob_older_than(entry.path().as_path(), grace)
        {
            continue;
        }
        let file_id = name;
        if referenced.contains(&file_id) {
            continue;
        }
        // A blob with no live message reference is orphaned: delete the blob,
        // and its `files` row too if one lingers.
        if std::fs::remove_file(entry.path()).is_ok() {
            removed = removed.saturating_add(1);
        }
        if find_file(&file_id)?.is_some() {
            delete_file_row(&file_id)?;
            removed = removed.saturating_add(1);
        }
    }
    removed = removed.saturating_add(sweep_broken_rows()?);
    Ok(removed)
}

/// Delete `files` rows whose stored blob no longer exists on disk; returns how
/// many rows were removed (the blob is gone, so such a row can never be served
/// or opened again).
fn sweep_broken_rows() -> color_eyre::Result<usize> {
    use crate::generated::schema::files::dsl::{file_id, path};
    use diesel::QueryDsl as _;
    use diesel::RunQueryDsl as _;
    let conn = &mut crate::sqlite_connect()?;
    let rows = files
        .select((file_id, path))
        .load::<(String, String)>(conn)
        .wrap_err("failed to list stored attachments")?;
    let mut removed = 0usize;
    for (id, stored) in rows {
        if !std::path::Path::new(&stored).exists() {
            delete_file_row(&id)?;
            removed = removed.saturating_add(1);
        }
    }
    Ok(removed)
}

/// The set of `file_id`s referenced by any persisted message
/// (`messages.attachment_json` ∪ `group_messages.attachment_json`).
fn referenced_file_ids() -> color_eyre::Result<HashSet<String>> {
    use crate::generated::schema::group_messages::dsl::{
        attachment_json as group_attachment_json, group_messages,
    };
    use crate::generated::schema::messages::dsl::{attachment_json, messages};
    use diesel::QueryDsl as _;
    use diesel::RunQueryDsl as _;
    let conn = &mut crate::sqlite_connect()?;
    let message_rows = messages
        .select(attachment_json)
        .load::<Option<String>>(conn)
        .wrap_err("failed to scan message attachments")?;
    let group_rows = group_messages
        .select(group_attachment_json)
        .load::<Option<String>>(conn)
        .wrap_err("failed to scan group attachments")?;
    let mut referenced = HashSet::new();
    for json in message_rows.into_iter().chain(group_rows) {
        let Some(json) = json else {
            continue;
        };
        let Ok(value) = serde_json::from_str::<serde_json::Value>(&json) else {
            continue;
        };
        if let Some(file_id) = value.get("file_id").and_then(serde_json::Value::as_str) {
            referenced.insert(file_id.to_string());
        }
    }
    // A live share manifest references blobs just like a message does. Without
    // this union the startup GC would sweep a shared tree's bytes as orphans.
    // A share-DB error is fatal here (conservative: skip GC rather than delete).
    referenced.extend(crate::shares::referenced_file_ids()?);
    Ok(referenced)
}

fn delete_file_row(file_id: &str) -> color_eyre::Result<()> {
    use crate::generated::schema::files::dsl::files as files_table;
    use diesel::ExpressionMethods as _;
    use diesel::QueryDsl as _;
    use diesel::RunQueryDsl as _;
    let conn = &mut crate::sqlite_connect()?;
    diesel::delete(files_table.filter(crate::generated::schema::files::file_id.eq(file_id)))
        .execute(conn)
        .wrap_err("failed to remove attachment row")?;
    Ok(())
}

/// Whether a store entry name is an in-progress `.part` partial (the extension
/// comparison ignores case, like the filesystem's conventional hints).
#[must_use]
fn is_part_blob(name: &str) -> bool {
    std::path::Path::new(name)
        .extension()
        .is_some_and(|ext| ext.eq_ignore_ascii_case("part"))
}

/// Whether the blob file at `path` was last modified at least `grace` ago (`true`
/// for files we cannot stat — a conservative *skip* would be safer, but a swept
/// directory entry that vanishes mid-scan is already handled by the caller's
/// `is_ok` guard, so treat the un-statable case as stale).
#[must_use]
fn blob_older_than(path: &std::path::Path, grace: Duration) -> bool {
    let modified = match std::fs::metadata(path) {
        Ok(metadata) => metadata.modified(),
        Err(_) => return true,
    };
    modified.is_ok_and(|m| m.elapsed().is_ok_and(|age| age >= grace))
}

