/// A group with its current member count (for list views).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GroupSummary {
    /// The underlying group record.
    pub group: Group,
    /// Peers seen participating in the group.
    pub member_count: i64,
}

/// Find a group by its stable `group_id`.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn find_group(group_id: &str) -> color_eyre::Result<Option<Group>> {
    let conn = &mut crate::sqlite_connect()?;
    groups::table
        .filter(groups::group_id.eq(group_id))
        .select(Group::as_select())
        .first(conn)
        .optional()
        .wrap_err("failed to look up group")
}

/// Stored attachment descriptor JSON for a group message by wire id.
///
/// Mirrors [`crate::messages::attachment_json_for_msg_id`] so the TUI's
/// open-attachment key resolves group chips the same way as broadcast/DM ones.
#[must_use]
pub fn attachment_json_for_msg_id(msg_id: &str) -> Option<String> {
    let conn = &mut crate::sqlite_connect().ok()?;
    group_messages::table
        .filter(group_messages::msg_id.eq(msg_id))
        .select(group_messages::attachment_json)
        .first::<Option<String>>(conn)
        .ok()?
}

/// Create a public group from `name`, or return the existing group if one with
/// the same canonical name is already known (idempotent — `create == join` in
/// the UI).
///
/// The stored `display_name` keeps the caller's original spelling; only the
/// identity (`group_id`) is derived from the canonical form.
///
/// # Errors
/// Returns [`EmptyGroupName`] when `name` has no canonical content, or an
/// error if the group cannot be inserted.
pub fn create_public_group(name: &str) -> color_eyre::Result<Group> {
    let validated = GroupName::new(name)?;
    let group_id = stable_group_id(&validated);
    if let Some(existing) = find_group(&group_id)? {
        return Ok(existing);
    }
    let conn = &mut crate::sqlite_connect()?;
    let row = diesel::insert_into(groups::table)
        .values(NewGroup {
            group_id,
            display_name: name.trim().to_string(),
            is_private: 0,
        })
        .returning(Group::as_returning())
        .get_result(conn)
        .wrap_err("failed to create group")?;
    Ok(row)
}

/// Ensure a `groups` row exists for a group we were invited to.
///
/// An invite only carries the `group_id` (stable hash — the canonical group
/// name that produced it is unknown here, so the stored `display_name` falls
/// back to the id). Idempotent: returns the existing row when one already
/// exists (e.g. we had joined the same public group by name earlier).
///
/// # Errors
/// Returns an error if the group cannot be inserted.
pub fn ensure_group_for_invite(group_id: &str) -> color_eyre::Result<Group> {
    if let Some(existing) = find_group(group_id)? {
        return Ok(existing);
    }
    let conn = &mut crate::sqlite_connect()?;
    diesel::insert_into(groups::table)
        .values(NewGroup {
            group_id: group_id.to_string(),
            display_name: group_id.to_string(),
            is_private: 0,
        })
        .returning(Group::as_returning())
        .get_result(conn)
        .wrap_err("failed to materialize invited group")
}

/// List all known groups (oldest first).
///
/// # Errors
/// Returns an error if the database query fails.
pub fn list_groups() -> color_eyre::Result<Vec<Group>> {
    let conn = &mut crate::sqlite_connect()?;
    groups::table
        .order_by(groups::created_at.asc())
        .then_order_by(groups::id.asc())
        .select(Group::as_select())
        .load(conn)
        .wrap_err("failed to list groups")
}

/// List every known group with its current member count.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn list_groups_with_member_counts() -> color_eyre::Result<Vec<GroupSummary>> {
    let rows = list_groups()?;
    let counts = get_all_group_member_counts()?;
    Ok(rows
        .into_iter()
        .map(|group| GroupSummary {
            member_count: counts.get(&group.group_id).copied().unwrap_or(0),
            group,
        })
        .collect())
}

/// Delete a group and all of its messages and memberships.
///
/// # Errors
/// Returns an error if the database operation fails.
pub fn delete_group(group_id: &str) -> color_eyre::Result<()> {
    let conn = &mut crate::sqlite_connect()?;
    // Reactions are keyed by the wire `msg_id`, with no group column or FK, so
    // deleting the messages would otherwise strand their reaction rows as
    // orphans. Collect the ids on this connection before removing the rows and
    // drop the matching reactions first — a re-created group with the same
    // deterministic id must not inherit stale reactions from the old one.
    let msg_ids: Vec<String> = group_messages::table
        .filter(group_messages::group_id.eq(group_id))
        .select(group_messages::msg_id)
        .load::<Option<String>>(conn)?
        .into_iter()
        .flatten()
        .collect();
    if !msg_ids.is_empty() {
        diesel::delete(message_reactions::table.filter(message_reactions::msg_id.eq_any(&msg_ids)))
            .execute(conn)?;
    }
    diesel::delete(group_messages::table.filter(group_messages::group_id.eq(group_id)))
        .execute(conn)?;
    diesel::delete(group_members::table.filter(group_members::group_id.eq(group_id)))
        .execute(conn)?;
    diesel::delete(groups::table.filter(groups::group_id.eq(group_id))).execute(conn)?;
    Ok(())
}

