/// Record `peer_id` as a participant in a group (idempotent; public groups
/// discover members from traffic).
///
/// # Errors
/// Returns an error if the database operation fails.
pub fn record_group_member(group_id: &str, peer_id: &str) -> color_eyre::Result<()> {
    use diesel::insert_into;
    let conn = &mut crate::sqlite_connect()?;
    insert_into(group_members::table)
        .values(NewGroupMember {
            group_id: group_id.to_string(),
            peer_id: peer_id.to_string(),
        })
        .on_conflict((group_members::group_id, group_members::peer_id))
        .do_nothing()
        .execute(conn)?;
    Ok(())
}

/// Number of peers seen in a group.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn get_group_member_count(group_id: &str) -> color_eyre::Result<i64> {
    let conn = &mut crate::sqlite_connect()?;
    group_members::table
        .filter(group_members::group_id.eq(group_id))
        .count()
        .get_result(conn)
        .wrap_err("failed to count group members")
}

/// Whether the local peer is a member of the given group.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn is_group_member(group_id: &str, peer_id: &str) -> color_eyre::Result<bool> {
    let conn = &mut crate::sqlite_connect()?;
    let count: i64 = group_members::table
        .filter(group_members::group_id.eq(group_id))
        .filter(group_members::peer_id.eq(peer_id))
        .count()
        .get_result(conn)
        .wrap_err("failed to check group membership")?;
    Ok(count > 0)
}

/// Member counts for every group (for list views).
///
/// # Errors
/// Returns an error if the database query fails.
pub fn get_all_group_member_counts() -> color_eyre::Result<std::collections::HashMap<String, i64>> {
    let conn = &mut crate::sqlite_connect()?;
    let total: i64 = group_members::table.count().get_result(conn)?;
    if total == 0 {
        return Ok(std::collections::HashMap::new());
    }
    let rows: Vec<(String, i64)> = group_members::table
        .group_by(group_members::group_id)
        .select((group_members::group_id, count(group_members::group_id)))
        .load(conn)?;
    Ok(rows.into_iter().collect())
}

// ── Group messages ─────────────────────────────────────────────────────────

/// Save an outgoing group message (inserted as already-sent: the row only
/// exists because the message was transmitted).
///
/// # Errors
/// Returns an error if the message cannot be inserted.
pub fn save_outgoing_group_message(
    group_id: &str,
    content: &str,
    meta: GroupMessageMeta,
) -> color_eyre::Result<GroupMessage> {
    let conn = &mut crate::sqlite_connect()?;
    let reply_to_json = meta.reply_to.as_ref().and_then(crate::reply::encode);
    let new_msg = NewGroupMessage {
        group_id: group_id.to_string(),
        content: content.to_string(),
        peer_id: None,
        sent: 1,
        msg_id: meta.msg_id,
        reply_to_json,
        sent_at: meta.sent_at,
        sender_nickname: meta.sender_nickname,
        attachment_json: meta
            .attachment
            .as_ref()
            .and_then(crate::files::attachment_to_json),
    };
    diesel::insert_into(group_messages::table)
        .values(&new_msg)
        .returning(GroupMessage::as_returning())
        .get_result(conn)
        .wrap_err("failed to save group message")
}

/// Stable id assigned to an incoming group row.
///
/// Wire ids are kept as-is; a message that arrived without one uses the same
/// synthetic `nil:` key the insert does, so live events and reloaded history
/// expose the same replyable id even for a duplicate delivery.
#[must_use]
pub fn incoming_group_msg_id(
    group_id: &str,
    peer_id: &str,
    content: &str,
    sent_at: Option<f64>,
    wire_msg_id: Option<String>,
) -> String {
    wire_msg_id.unwrap_or_else(|| {
        let key = fnv1a_hex(&format!(
            "{group_id}|{peer_id}|{}|{content}",
            sent_at.unwrap_or(0.0)
        ));
        format!("nil:{key}")
    })
}

/// Save an incoming group message, deduplicating mesh re-deliveries on
/// `(group_id, msg_id)`. Returns [`Option::None`] when a duplicate is skipped.
///
/// Messages without an `msg_id` get a stable synthetic key derived from their
/// content, so `SQLite`'s `(group_id, msg_id)` unique index still dedups them —
/// a `NULL` `msg_id` would otherwise slip past the index (`SQLite` treats `NULL`s
/// as distinct) and accept every retransmit.
///
/// # Errors
/// Returns an error if the message cannot be inserted.
pub fn save_incoming_group_message(
    group_id: &str,
    peer_id: &str,
    content: &str,
    meta: GroupMessageMeta,
) -> color_eyre::Result<Option<GroupMessage>> {
    let conn = &mut crate::sqlite_connect()?;
    let msg_id = incoming_group_msg_id(group_id, peer_id, content, meta.sent_at, meta.msg_id);
    let reply_to_json = meta.reply_to.as_ref().and_then(crate::reply::encode);
    let new_msg = NewGroupMessage {
        group_id: group_id.to_string(),
        content: content.to_string(),
        peer_id: Some(peer_id.to_string()),
        sent: 0,
        msg_id: Some(msg_id),
        reply_to_json,
        sent_at: meta.sent_at,
        sender_nickname: meta.sender_nickname,
        attachment_json: meta
            .attachment
            .as_ref()
            .and_then(crate::files::attachment_to_json),
    };
    diesel::insert_into(group_messages::table)
        .values(&new_msg)
        .on_conflict((group_messages::group_id, group_messages::msg_id))
        .do_nothing()
        .returning(GroupMessage::as_returning())
        .get_result(conn)
        .optional()
        .wrap_err("failed to save group message")
}

/// Locally hide a group message we sent (US-005).
///
/// Only an outgoing (`sent = 1`) row that is not already a tombstone is
/// stamped with the current Unix timestamp; incoming rows are never deletable.
/// Returns `true` iff a row actually changed. This is local-only: no wire
/// message is sent and peers keep their own copy of the row.
///
/// # Errors
/// Returns an error string when the database write fails.
pub fn mark_group_message_deleted(id: i32) -> Result<bool, String> {
    let conn = &mut crate::sqlite_connect().map_err(|e| e.to_string())?;
    let changed = diesel::update(
        group_messages::table
            .filter(group_messages::id.eq(id))
            .filter(group_messages::sent.eq(1))
            .filter(group_messages::deleted_at.is_null()),
    )
    .set(group_messages::deleted_at.eq(crate::fmt::current_timestamp()))
    .execute(conn)
    .map_err(|e| format!("failed to delete group message {id}: {e}"))?;
    Ok(changed > 0)
}

/// Locally edit the body of a group message we sent (US-005).
///
/// Mirrors [`crate::messages::edit_message`]: only a non-tombstoned outgoing
/// row is changed, the body is replaced in place and `edited_at` records the
/// LOCAL edit time. Repeat edits refresh the timestamp; nothing is sent to the
/// group. Returns `true` iff a row changed.
///
/// # Errors
/// Returns an error string when the database write fails.
pub fn edit_group_message(id: i32, content: &str) -> Result<bool, String> {
    let conn = &mut crate::sqlite_connect().map_err(|e| e.to_string())?;
    let changed = diesel::update(
        group_messages::table
            .filter(group_messages::id.eq(id))
            .filter(group_messages::sent.eq(1))
            .filter(group_messages::deleted_at.is_null()),
    )
    .set((
        group_messages::content.eq(content),
        group_messages::edited_at.eq(crate::fmt::current_timestamp()),
    ))
    .execute(conn)
    .map_err(|e| format!("failed to edit group message {id}: {e}"))?;
    Ok(changed > 0)
}

/// Raw stored body of an editable sent group row, for the TUI edit pre-fill.
///
/// Mirrors [`crate::messages::message_body`]: display-only decorations must not
/// leak back into the persisted body. `None` means missing, incoming, or
/// tombstoned.
///
/// # Errors
/// Returns an error string when the database read fails.
pub fn group_message_body(id: i32) -> Result<Option<String>, String> {
    let conn = &mut crate::sqlite_connect().map_err(|e| e.to_string())?;
    group_messages::table
        .filter(group_messages::id.eq(id))
        .filter(group_messages::sent.eq(1))
        .filter(group_messages::deleted_at.is_null())
        .select(group_messages::content)
        .first::<String>(conn)
        .optional()
        .map_err(|e| format!("failed to read group message {id}: {e}"))
}

/// Fully rendered body of an edited sent group row (chip + edit marker).
///
/// Mirrors [`crate::messages::message_display_body`] so the in-memory group
/// transcript matches the next DB reload after a local edit.
///
/// # Errors
/// Returns an error string when the database read fails.
pub fn group_message_display_body(id: i32) -> Result<Option<String>, String> {
    let conn = &mut crate::sqlite_connect().map_err(|e| e.to_string())?;
    let row = group_messages::table
        .filter(group_messages::id.eq(id))
        .filter(group_messages::sent.eq(1))
        .filter(group_messages::deleted_at.is_null())
        .select((
            group_messages::content,
            group_messages::attachment_json,
            group_messages::edited_at,
        ))
        .first::<(String, Option<String>, Option<f64>)>(conn)
        .optional()
        .map_err(|e| format!("failed to read group message {id}: {e}"))?;
    Ok(row.map(|(content, attachment_json, edited_at)| {
        crate::files::render_stored_display_body(
            &content,
            attachment_json.as_deref(),
            edited_at.is_some(),
        )
    }))
}

/// The `sent_at` watermark of a group's newest stored message (`None` when the
/// group has no history).
///
/// Served as the requesting side's `after` boundary for backfill: any member
/// with a *newer* stored message than this was up during the gap and can
/// answer it. Deliberately **unfiltered** by `deleted_at`: a local tombstone
/// must still hold the watermark so peers never resend that row.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn latest_group_sent_at(group_id: &str) -> color_eyre::Result<Option<f64>> {
    use crate::generated::schema::group_messages;
    let conn = &mut crate::sqlite_connect()?;
    group_messages::table
        .filter(group_messages::group_id.eq(group_id))
        .order_by(group_messages::sent_at.desc())
        .select(group_messages::sent_at)
        .first::<Option<f64>>(conn)
        .optional()
        .wrap_err("failed to read group watermark")
        .map(Option::flatten)
}

/// Load a group's stored messages strictly newer than the `after` watermark,
/// oldest first, bounded to `limit`.
///
/// This is the backfill answer: a member that was up longer than the requester
/// replies by re-publishing exactly these rows on the main group topic, where
/// the requester's `(group_id, msg_id)` unique index (and the `nil:` synthetic
/// key for messages without an `msg_id`) absorbs every overlap. Local tombstones
/// are skipped: deletion never leaks back onto the wire. Messages without a
/// `sent_at` are skipped — they predate the watermark convention and any live
/// retransmit dedups them anyway.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn load_group_messages_after(
    group_id: &str,
    after: f64,
    limit: usize,
) -> color_eyre::Result<Vec<GroupMessage>> {
    use crate::generated::schema::group_messages;
    let conn = &mut crate::sqlite_connect()?;
    group_messages::table
        .filter(group_messages::group_id.eq(group_id))
        .filter(group_messages::sent_at.gt(after))
        .filter(group_messages::deleted_at.is_null())
        .order_by(group_messages::sent_at.asc())
        .then_order_by(group_messages::id.asc())
        .limit(crate::usize_limit_to_i64(limit))
        .select(GroupMessage::as_select())
        .load(conn)
        .wrap_err("failed to load backfill history")
}

/// Load a group's messages, newest first, limited to `limit`.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn load_group_messages(group_id: &str, limit: usize) -> color_eyre::Result<Vec<GroupMessage>> {
    let conn = &mut crate::sqlite_connect()?;
    group_messages::table
        .filter(group_messages::group_id.eq(group_id))
        .filter(group_messages::deleted_at.is_null())
        .order_by(group_messages::created_at.desc())
        .then_order_by(group_messages::id.desc())
        .limit(crate::usize_limit_to_i64(limit))
        .select(GroupMessage::as_select())
        .load(conn)
        .wrap_err("failed to load group messages")
}

