//! Centralized logging system using the `tracing` crate.
//!
//! This module provides a unified logging solution that:
//! - Uses `tracing` (Rust's most popular structured logging library)
//! - Supports a single callback registry for all frontends (TUI, Flutter)
//! - Writes to both terminal (if no callback) and a persistent log file
//! - Integrates with libp2p's existing tracing usage

use std::collections::VecDeque;
use std::io::Write;
use std::sync::{Arc, Mutex, OnceLock};
#[cfg(feature = "tracing")]
use tracing::field::Visit;

/// Direct-to-logcat sink for Android.
///
/// A native app's stdout/stderr are not reliably routed to logcat on Android
/// (they usually go to /dev/null), so `eprintln!` from the Rust core would never
/// show up in `adb logcat` / `flutter run`. We therefore call the NDK `liblog`
/// directly so the in-app Log-tab lines surface in logcat and can be captured
/// by `run_waydroid.sh`.
#[cfg(target_os = "android")]
mod android_log {
    use std::os::raw::{c_char, c_int};

    #[link(name = "log")]
    unsafe extern "C" {
        fn __android_log_write(prio: c_int, tag: *const c_char, text: *const c_char) -> c_int;
    }

    const ANDROID_LOG_DEBUG: c_int = 3;
    const ANDROID_LOG_INFO: c_int = 4;
    const ANDROID_LOG_WARN: c_int = 5;
    const ANDROID_LOG_ERROR: c_int = 6;

    pub fn write(line: &str) {
        let prio = if let Some(rest) = line.split_once('[') {
            let up = rest.1.to_ascii_uppercase();
            if up.contains("[ERROR]") {
                ANDROID_LOG_ERROR
            } else if up.contains("[WARN]") {
                ANDROID_LOG_WARN
            } else if up.contains("[DEBUG]") {
                ANDROID_LOG_DEBUG
            } else {
                ANDROID_LOG_INFO
            }
        } else {
            ANDROID_LOG_INFO
        };

        let tag = b"p2p_app\0".as_ptr() as *const c_char;
        let text = match std::ffi::CString::new(line.trim_end_matches('\n')) {
            Ok(c) => c,
            Err(_) => return,
        };
        unsafe {
            __android_log_write(prio, tag, text.as_ptr());
        }
    }
}

type LogCallback = Arc<dyn Fn(String) + Send + Sync>;
type RedrawHook = Arc<dyn Fn() + Send + Sync>;

/// Maximum number of logs to keep in memory for UI replay
const MAX_LOGS: usize = 1000;

/// In-memory log storage for UI access and replay when callbacks attach later
static LOG_BUFFER: OnceLock<Mutex<VecDeque<String>>> = OnceLock::new();

/// Unified callback registry: all frontends (Flutter FRB, TUI)
/// register here to receive log messages. One entry per registration.
static LOG_CALLBACKS: Mutex<Vec<LogCallback>> = Mutex::new(vec![]);

/// Optional hook that requests a TUI redraw when new logs arrive.
static TUI_REDRAW_HOOK: OnceLock<Mutex<Option<RedrawHook>>> = OnceLock::new();

/// Custom tracing layer that sends log events through `push_log`.
///
/// Only compiled with the `tracing` feature: the minimal headless CLI builds
/// without it (see `init_logging`), and `push_log` still logs to stderr/the
/// file/buffer there.
#[cfg(feature = "tracing")]
struct TuiTracingLayer;

#[cfg(feature = "tracing")]
impl<S> tracing_subscriber::layer::Layer<S> for TuiTracingLayer
where
    S: tracing::Subscriber + 'static,
{
    fn on_event(&self, event: &tracing::Event<'_>, _ctx: tracing_subscriber::layer::Context<S>) {
        let mut buf = String::new();
        let mut visitor = FormatVisitor(&mut buf);
        event.record(&mut visitor);

        let ts = chrono::Local::now().format("%H:%M:%S.%3f");
        let level = event.metadata().level().to_string();
        let target = event.metadata().target();
        let msg = if buf.is_empty() {
            format!("{ts} [{level}] {target}")
        } else {
            format!("{ts} [{level}] {target} {buf}")
        };

        push_log(msg);
    }
}

/// Visitor that formats event fields into a string
#[cfg(feature = "tracing")]
struct FormatVisitor<'a>(&'a mut String);

#[cfg(feature = "tracing")]
impl Visit for FormatVisitor<'_> {
    fn record_str(&mut self, field: &tracing::field::Field, value: &str) {
        if field.name() == "message" {
            self.0.push_str(value);
        } else {
            let _ = std::fmt::write(&mut *self.0, format_args!(" {}={value}", field.name()));
        }
    }

    fn record_i64(&mut self, field: &tracing::field::Field, value: i64) {
        let _ = std::fmt::write(&mut *self.0, format_args!(" {}={value}", field.name()));
    }

    fn record_u64(&mut self, field: &tracing::field::Field, value: u64) {
        let _ = std::fmt::write(&mut *self.0, format_args!(" {}={value}", field.name()));
    }

    fn record_bool(&mut self, field: &tracing::field::Field, value: bool) {
        let _ = std::fmt::write(&mut *self.0, format_args!(" {}={value}", field.name()));
    }

    fn record_debug(&mut self, field: &tracing::field::Field, value: &dyn std::fmt::Debug) {
        let _ = std::fmt::write(&mut *self.0, format_args!(" {}={value:?}", field.name()));
    }
}

/// Initialize the logging system.
///
/// Must be called once at application startup before any logging occurs.
/// When the `tracing` feature is enabled, this sets up the tracing subscriber.
#[cfg(feature = "tracing")]
pub fn init_logging() {
    use tracing_subscriber::prelude::*;

    // Initialize log buffer storage
    let _ = LOG_BUFFER.get_or_init(|| Mutex::new(VecDeque::new()));

    // Build filter - use environment or default to warn
    let filter = tracing_subscriber::EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("warn,p2p_app=info"));

    // Create the subscriber with our custom layer
    let subscriber = tracing_subscriber::registry()
        .with(filter)
        .with(TuiTracingLayer);

    let _ = subscriber.try_init();
}

#[cfg(not(feature = "tracing"))]
pub fn init_logging() {
    let _ = LOG_BUFFER.get_or_init(|| Mutex::new(VecDeque::new()));
}

/// Set or replace the redraw hook used after log messages.
pub fn set_tui_redraw_hook<F>(hook: F)
where
    F: Fn() + Send + Sync + 'static,
{
    let hook_cell = TUI_REDRAW_HOOK.get_or_init(|| Mutex::new(None));
    if let Ok(mut guard) = hook_cell.lock() {
        *guard = Some(Arc::new(hook));
    }
}

/// Request a TUI redraw if a redraw hook has been installed.
pub fn request_tui_redraw() {
    let Some(hook_cell) = OnceLock::get(&TUI_REDRAW_HOOK) else {
        return;
    };
    if let Ok(guard) = hook_cell.lock()
        && let Some(hook) = guard.as_ref()
    {
        hook();
    }
}

/// Get all stored log messages from the buffer.
pub fn get_tui_logs() -> Vec<String> {
    LOG_BUFFER
        .get()
        .map_or_default(|m| m.lock().map_or_default(|g| g.clone().into_iter().collect()))
}

/// Clear the in-memory log buffer (Log tab / Settings "Clear" action).
///
/// A no-op when logging was never initialized (empty buffer).
pub fn clear_tui_logs() {
    if let Some(logs) = LOG_BUFFER.get()
        && let Ok(mut guard) = logs.lock()
    {
        guard.clear();
    }
}

/// Path to the application log file.
fn log_file_path() -> std::path::PathBuf {
    let cwd = std::env::current_dir().unwrap_or_default();
    let target_dir = cwd.join("target");
    if target_dir.is_dir() {
        target_dir.join(format!(
            "p2p_app_{}.log",
            chrono::Local::now().format("%F_%H%M-%S")
        ))
    } else {
        cwd.join(format!(
            "p2p_app_{}.log",
            chrono::Local::now().format("%F_%H%M-%S")
        ))
    }
}

/// Global log file handle (append mode, thread-safe via Mutex).
static LOG_FILE: Mutex<Option<std::fs::File>> = Mutex::new(None);

/// Write a log line to the persistent log file.
fn write_to_file(formatted: &str) {
    let Ok(mut file) = LOG_FILE.lock() else {
        return;
    };
    if file.is_none() {
        let path = log_file_path();
        let _ = std::fs::create_dir_all(path.parent().unwrap_or(&std::path::PathBuf::new()));
        match std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&path)
        {
            Ok(f) => *file = Some(f),
            Err(_) => *file = None,
        }
    }
    if let Some(f) = file.as_mut() {
        let _ = f.write_all(formatted.as_bytes());
    }
}

/// Push a log message to the buffer, file, and all registered callbacks.
///
/// If no callbacks are registered, the message is printed to stderr.
pub fn push_log(message: impl Into<String>) {
    let msg = message.into();
    let ts = chrono::Local::now().format("%Y-%m-%d %H:%M:%S%.3f");
    let formatted = format!("[{ts}] {msg}\n");

    // Store in buffer for replay when callbacks are added later
    {
        let _ = LOG_BUFFER.get_or_init(|| Mutex::new(VecDeque::new()));
        if let Some(logs) = LOG_BUFFER.get()
            && let Ok(mut l) = logs.lock()
        {
            let display = format!("[{ts}] {msg}");
            l.push_back(display);
            if l.len() > MAX_LOGS {
                l.pop_front();
            }
        }
    }

    // Write to persistent log file
    write_to_file(&formatted);

    // Notify all registered callbacks (or stderr if none registered)
    let Ok(callbacks) = LOG_CALLBACKS.lock() else {
        return;
    };
    if callbacks.is_empty() {
        // On the mobile frontend the stderr mirror below already emits every
        // line, so avoid printing it twice during early startup (before the
        // Flutter callback is registered).
        #[cfg(not(feature = "mobile"))]
        eprintln!("[{ts}] {msg}");
    } else {
        for cb in callbacks.iter() {
            cb(format!("[{ts}] {msg}"));
        }
    }

    // When compiled for the Flutter/mobile frontend, mirror every log line so
    // the lines shown in the in-app Log tab are also visible where the app runs:
    //  - on Android, write directly to logcat (stderr is not routed to logcat),
    //    so `adb logcat` / `flutter run` actually receive them;
    //  - elsewhere (desktop), print to stderr so run_flutter_desktop.sh shows them.
    // Excluded under `cfg(test)` so the test harness stays quiet.
    #[cfg(all(feature = "mobile", target_os = "android", not(test)))]
    {
        android_log::write(&formatted);
    }
    #[cfg(all(feature = "mobile", not(target_os = "android"), not(test)))]
    {
        eprintln!("[{ts}] {msg}");
    }
}

/// Register a callback that will receive all log messages.
///
/// External frontends (Flutter FRB, TUI) can use this to add their
/// own log display. When registered, all previously accumulated logs in the
/// buffer are immediately replayed to the callback.
pub fn register_log_callback(callback: LogCallback) {
    let Ok(mut callbacks) = LOG_CALLBACKS.lock() else {
        return;
    };

    // Replay accumulated logs that were captured before this callback was registered
    if let Some(logs) = LOG_BUFFER.get()
        && let Ok(l) = logs.lock()
    {
        for log in l.iter() {
            callback(log.clone());
        }
    }

    callbacks.push(callback);
}

/// A peekable character stream, shared by the ANSI-sequence consumers below.
type EscapeChars<'a> = std::iter::Peekable<std::str::Chars<'a>>;

/// Consume a CSI payload: `ESC [` is already read; the sequence ends at its
/// final byte (`0x40..=0x7E`).
fn consume_csi(chars: &mut EscapeChars<'_>) {
    for c in chars.by_ref() {
        if ('@'..='~').contains(&c) {
            break;
        }
    }
}

/// Consume an OSC payload: `ESC ]` is already read; the sequence ends at BEL
/// or `ESC \`.
fn consume_osc(chars: &mut EscapeChars<'_>) {
    while let Some(c) = chars.next() {
        match c {
            '\x07' => break,
            '\x1b' => {
                if chars.peek() == Some(&'\\') {
                    chars.next();
                }
                break;
            }
            _ => {}
        }
    }
}

/// Remove ANSI escape codes from a string (e.g., color/formatting codes).
///
/// Understands CSI sequences (`ESC[ params final`), OSC sequences
/// (`ESC]…BEL` / `ESC]…ESC\`), and two-character sequences (`ESC(`, `ESC M`,
/// `ESC=`), so a non-SGR escape like `ESC[2J` never swallows the text that
/// follows it.
#[must_use]
pub fn strip_ansi_codes(s: &str) -> String {
    let mut result = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '\x1b' {
            result.push(c);
            continue;
        }
        match chars.peek().copied() {
            // CSI: ESC [ parameters / intermediates / final (0x40..=0x7E).
            Some('[') => {
                chars.next();
                consume_csi(&mut chars);
            }
            // OSC: ESC ] … BEL, or … ESC \.
            Some(']') => {
                chars.next();
                consume_osc(&mut chars);
            }
            // Two-character sequences (ESC M, ESC =, …). Character-set
            // designation sequences (ESC ( B, ESC ) 0, …) carry an extra
            // designator byte after the intermediate.
            Some(intermediate) => {
                chars.next();
                if matches!(intermediate, '(' | ')' | '*' | '+' | '-' | '.' | '/') {
                    chars.next();
                }
            }
            None => {}
        }
    }
    result
}

/// Debug log alias
pub fn p2plog_debug(msg: impl Into<String>) {
    push_log(format!("[DEBUG] {}", msg.into()));
}

/// Info log alias
pub fn p2plog_info(msg: impl Into<String>) {
    push_log(format!("[INFO] {}", msg.into()));
}

/// Error log alias
pub fn p2plog_error(msg: impl Into<String>) {
    push_log(format!("[ERROR] {}", msg.into()));
}

