//! Notification policy and payloads (US-027 sounds, US-028 desktop alerts).
//!
//! Rust decides *what* is worth notifying about and builds the display text;
//! the frontends only decide whether the conversation is on screen and hand
//! the payload to the platform. That keeps the "new message → notification"
//! rule identical in the TUI, Android and the browser.
//!
//! A [`Notification`] is attached to the incoming-message event envelope, so
//! every transport receives exactly the same title/body without re-deriving
//! display names or truncating text in Dart.

use serde::Serialize;

/// One notification for an incoming message.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Notification {
    /// Sender (or group + sender) display label.
    pub title: String,
    /// Short, single-line message preview.
    pub body: String,
    /// Stable key of the conversation, for focus suppression:
    /// `broadcast`, `dm:<peer-id>` or `group:<group-id>`.
    pub conversation_key: String,
    /// Whether a sound should accompany this notification.
    pub sound: bool,
    /// Whether a desktop/system notification should be shown.
    pub desktop: bool,
}

/// Persisted delivery channels (US-027 / US-028).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct NotificationSettings {
    /// Play a sound on a new message. On by default; no permission needed.
    pub sound: bool,
    /// Show a desktop/system notification. Off by default because the browser
    /// and Android 13+ both require an explicit permission grant first.
    pub desktop: bool,
}

impl Default for NotificationSettings {
    fn default() -> Self {
        Self {
            sound: true,
            desktop: false,
        }
    }
}

/// Read the current delivery channels from persisted settings.
#[must_use]
pub fn settings() -> NotificationSettings {
    NotificationSettings {
        sound: crate::settings::notification_sound(),
        desktop: crate::settings::notification_desktop(),
    }
}

/// Persist both channels in one call. Both writes succeed or the first error
/// is returned, so a partial settings update surfaces to the caller.
///
/// # Errors
/// Returns a human-readable error if either database write fails.
pub fn set_settings(sound: bool, desktop: bool) -> Result<(), String> {
    crate::settings::set_notification_sound(sound)?;
    crate::settings::set_notification_desktop(desktop)
}

/// Build the notification for an incoming message event.
///
/// Returns `None` when both channels are disabled (nothing to deliver) or the
/// event kind is not a user message (call/control events are handled by their
/// own UI). Display-name resolution stays in Rust so TUI and Flutter agree.
#[must_use]
pub fn for_message(
    event_type: &str,
    peer_id: &str,
    nickname: Option<&str>,
    content: &str,
    group_id: Option<&str>,
) -> Option<Notification> {
    // Reject control/call events before any DB access: `conversation_key` is
    // pure, while `settings()` below reads two persisted values. A receipt or
    // call signal must never pay for a settings lookup it cannot use.
    let conversation_key = conversation_key(event_type, peer_id, group_id)?;
    let channels = settings();
    if !channels.sound && !channels.desktop {
        return None;
    }

    let sender = nickname.filter(|name| !name.is_empty()).map_or_else(
        || crate::nickname::get_peer_display_name_or_short(peer_id),
        ToString::to_string,
    );
    let title = match group_id {
        Some(id) if !id.is_empty() => {
            format!(
                "Group {} · {sender}",
                id.chars().take(8).collect::<String>()
            )
        }
        _ => sender,
    };

    Some(Notification {
        title,
        body: preview(content),
        conversation_key,
        sound: channels.sound,
        desktop: channels.desktop,
    })
}

/// Stable focus-suppression key for a message event. `None` for any event kind
/// that is not a user message, so control/call events never notify.
fn conversation_key(event_type: &str, peer_id: &str, group_id: Option<&str>) -> Option<String> {
    match event_type {
        "broadcast" => Some("broadcast".to_string()),
        "dm" => Some(format!("dm:{peer_id}")),
        "group_message" => group_id
            .filter(|id| !id.is_empty())
            .map(|id| format!("group:{id}")),
        _ => None,
    }
}

/// Terminal control sequence that delivers one notification in the TUI.
///
/// An optional bell (US-027) is followed by an OSC 777 `notify` sequence
/// (US-028, supported by kitty, iTerm2, GNOME Terminal and `WezTerm`). Titles
/// and bodies are sanitized so control characters and the `;` field separator
/// can never inject a second OSC command or corrupt the frame.
#[must_use]
pub fn terminal_sequence(n: &Notification) -> String {
    let mut out = String::new();
    if n.sound {
        out.push('\u{7}');
    }
    if n.desktop {
        out.push_str("\u{1b}]777;notify;");
        out.push_str(&osc_field(&n.title));
        out.push(';');
        out.push_str(&osc_field(&n.body));
        out.push('\u{7}');
    }
    out
}

/// Flatten a value for use inside an OSC 777 field: strip control characters
/// and replace `;` (the field separator) with a space.
fn osc_field(value: &str) -> String {
    value
        .chars()
        .map(|c| if c.is_control() || c == ';' { ' ' } else { c })
        .collect()
}

/// Single-line preview of a message body, bounded so a notification never
/// dominates the screen (or the OS notification shade).
fn preview(content: &str) -> String {
    const LIMIT: usize = 140;
    let flat: String = content
        .chars()
        .map(|c| if c.is_control() { ' ' } else { c })
        .collect();
    if flat.chars().count() <= LIMIT {
        return if flat.is_empty() {
            "[new message]".to_string()
        } else {
            flat
        };
    }
    let head: String = flat.chars().take(LIMIT.saturating_sub(1)).collect();
    format!("{head}…")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn preview_flattens_controls_and_bounds_length() {
        assert_eq!(preview(""), "[new message]");
        assert_eq!(preview("line one\nline two"), "line one line two");
        let long = "x".repeat(300);
        let result = preview(&long);
        assert_eq!(result.chars().count(), 140);
        assert!(result.ends_with('…'));
    }

    #[test]
    fn for_message_is_none_for_control_events() {
        // No DB access is attempted for non-message kinds, so this is safe
        // without a test database.
        assert!(for_message("receipt", "peer", None, "hi", None).is_none());
    }

    #[test]
    fn conversation_key_maps_message_kinds() {
        assert_eq!(
            conversation_key("broadcast", "peer", None).as_deref(),
            Some("broadcast")
        );
        assert_eq!(
            conversation_key("dm", "peer42", None).as_deref(),
            Some("dm:peer42")
        );
        assert_eq!(
            conversation_key("group_message", "peer", Some("grp1")).as_deref(),
            Some("group:grp1")
        );
        // A group event without an id cannot be focused — never notify.
        assert!(conversation_key("group_message", "peer", None).is_none());
        assert!(conversation_key("call_invite", "peer", None).is_none());
    }

    #[test]
    fn terminal_sequence_encodes_sound_and_desktop_channels() {
        let sound = Notification {
            title: "Alice".to_string(),
            body: "hello".to_string(),
            conversation_key: "dm:peer".to_string(),
            sound: true,
            desktop: false,
        };
        assert_eq!(terminal_sequence(&sound), "\u{7}");

        let both = Notification {
            title: "Group ab;cd".to_string(),
            body: "line\ntext".to_string(),
            conversation_key: "group:grp".to_string(),
            sound: true,
            desktop: true,
        };
        assert_eq!(
            terminal_sequence(&both),
            "\u{7}\u{1b}]777;notify;Group ab cd;line text\u{7}"
        );
    }
}

//! Peer management, session tracking, and port persistence

use crate::{
    generated::models_insertable::NewPeer, generated::models_queryable::Peer,
    generated::schema::peers::dsl::peers, logging::p2plog_debug,
};
use diesel::{
    ExpressionMethods, OptionalExtension, QueryDsl, RunQueryDsl as _, SelectableHelper as _,
};

/// Peer row returned by `load_known_peers()`.
#[derive(Debug, Clone, diesel::QueryableByName)]
pub struct KnownPeer {
    #[diesel(sql_type = diesel::sql_types::Text)]
    /// Unique libp2p peer identifier
    pub peer_id: String,
    #[diesel(sql_type = diesel::sql_types::Timestamp)]
    /// Timestamp when this peer was first observed
    pub first_seen: chrono::NaiveDateTime,
    #[diesel(sql_type = diesel::sql_types::Timestamp)]
    /// Timestamp when this peer was most recently observed
    pub last_seen: chrono::NaiveDateTime,
}

/// Save or update a peer in the database.
///
/// If peer already exists (by `peer_id`), updates `last_seen` and, when a
/// non-empty `addresses` list is given, the stored addresses. Inserting with an
/// empty address list therefore *never* wipes previously learned addresses:
/// several callers only know a peer id (nickname edits, connection events,
/// incoming messages) and must not clobber the last known dial addresses.
/// Otherwise inserts a new peer record with current timestamp.
///
/// # Arguments
/// * `peer_id` - Unique peer identifier
/// * `addresses` - List of multiaddrs where this peer can be reached
///
/// # Returns
/// The saved or updated Peer record
///
/// # Errors
/// Returns an error if the database operation fails.
pub fn save_peer(peer_id: &str, addresses: &[String]) -> color_eyre::Result<Peer> {
    let conn = &mut crate::sqlite_connect()?;
    let addresses_str = addresses.join(",");
    let now = chrono::Utc::now().naive_utc();

    // Generate a petname only for a brand-new peer. Re-seen peers keep the name
    // already stored in the database. Silent peers that predate this feature
    // (NULL generated_nickname) get a petname lazily via get_peer_display_name.
    let generated_nickname = {
        let exists = peers
            .filter(crate::generated::schema::peers::peer_id.eq(peer_id))
            .count()
            .get_result::<i64>(conn)?
            > 0;
        if exists {
            None
        } else {
            let name = crate::nickname::generate_self_nickname();
            p2plog_debug(format!(
                "[Nickname] generated petname '{name}' for new silent peer {peer_id}"
            ));
            Some(name)
        }
    };

    let new_peer = NewPeer {
        peer_id: peer_id.to_string(),
        addresses: addresses_str.clone(),
        first_seen: now,
        last_seen: now,
        peer_local_nickname: None,
        self_nickname_for_peer: None,
        received_nickname: None,
        generated_nickname,
    };

    let peer = if addresses_str.is_empty() {
        // No addresses provided: keep whatever the peer's row already stores.
        diesel::insert_into(crate::generated::schema::peers::table)
            .values(&new_peer)
            .on_conflict(crate::generated::schema::peers::peer_id)
            .do_update()
            .set(crate::generated::schema::peers::last_seen.eq(now))
            .returning(Peer::as_returning())
            .get_result(conn)?
    } else {
        diesel::insert_into(crate::generated::schema::peers::table)
            .values(&new_peer)
            .on_conflict(crate::generated::schema::peers::peer_id)
            .do_update()
            .set((
                crate::generated::schema::peers::addresses.eq(&addresses_str),
                crate::generated::schema::peers::last_seen.eq(now),
            ))
            .returning(Peer::as_returning())
            .get_result(conn)?
    };
    // A save may assign a new petname (brand-new peers) or touch rows that feed
    // the display-name cache, so drop any memoized name for this peer.
    crate::nickname::invalidate_display_name(peer_id);
    Ok(peer)
}

/// Record a peer-session sample (how many peers were connected).
///
/// Called on every connection/disconnection (TUI and mobile), so
/// `get_average_peer_count` reflects real usage instead of an empty table.
///
/// # Errors
/// Returns an error if the database operation fails.
pub fn record_peer_session(concurrent_peers: i32) -> color_eyre::Result<()> {
    use crate::generated::schema::peer_sessions;

    let conn = &mut crate::sqlite_connect()?;
    diesel::insert_into(peer_sessions::table)
        .values(peer_sessions::concurrent_peers.eq(concurrent_peers))
        .execute(conn)?;
    Ok(())
}

/// This install's own peer ID as a string, or `None` when no identity is stored.
///
/// The local device has a `peers` row (the `device_bindings` foreign key needs
/// it) but it is never a peer of itself, so the roster loaders filter it out and
/// the TUI's live add path skips `state.local_peer_id`.
#[must_use]
pub fn local_peer_id_string() -> Option<String> {
    crate::db::existing_local_peer_id().map(|id| id.to_string())
}

/// Load all known peers, ordered by most recently seen first.
///
/// This install's own device is excluded: its row exists only so the
/// device-binding foreign key can reference it.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn load_peers() -> color_eyre::Result<Vec<Peer>> {
    let conn = &mut crate::sqlite_connect()?;
    let peers_list = peers
        .order(crate::generated::schema::peers::last_seen.desc())
        .select(Peer::as_select())
        .load(conn)?;
    let local_peer = local_peer_id_string();
    Ok(peers_list
        .into_iter()
        .filter(|p| {
            local_peer
                .as_deref()
                .is_none_or(|local| local != p.peer_id.as_str())
        })
        .collect())
}

/// Load all known peers, combining both the `peers` table and any peer IDs present in `messages`.
///
/// This fixes older databases where messages may exist but the `peers` table is empty.
/// Ordering is by most-recently-seen first (max of `peer.last_seen` and latest message timestamp).
/// This install's own device is excluded (see [`load_peers`]).
///
/// # Errors
/// Returns an error if the database query fails.
pub fn load_known_peers() -> color_eyre::Result<Vec<KnownPeer>> {
    use diesel::sql_query;

    let conn = &mut crate::sqlite_connect()?;
    let sql = r"
WITH msg_peers AS (
    SELECT
        peer_id AS peer_id,
        MIN(created_at) AS first_seen,
        MAX(created_at) AS last_seen
    FROM messages
    WHERE peer_id IS NOT NULL
    GROUP BY peer_id
),
peer_peers AS (
    SELECT
        peer_id AS peer_id,
        first_seen AS first_seen,
        last_seen AS last_seen
    FROM peers
),
merged AS (
    SELECT peer_id, first_seen, last_seen FROM peer_peers
    UNION ALL
    SELECT peer_id, first_seen, last_seen FROM msg_peers
)
SELECT
    peer_id,
    MIN(first_seen) AS first_seen,
    MAX(last_seen) AS last_seen
FROM merged
GROUP BY peer_id
ORDER BY last_seen DESC
    ";

    let rows = sql_query(sql).load::<KnownPeer>(conn)?;
    let local_peer = local_peer_id_string();
    Ok(rows
        .into_iter()
        .filter(|p| {
            local_peer
                .as_deref()
                .is_none_or(|local| local != p.peer_id.as_str())
        })
        .collect())
}

/// Save the last used TCP and QUIC ports to the database.
///
/// # Errors
/// Returns an error if the database update fails.
pub fn save_listen_ports(tcp_port: Option<i32>, quic_port: Option<i32>) -> color_eyre::Result<()> {
    let conn = &mut crate::sqlite_connect()?;
    diesel::update(crate::generated::schema::identities::table)
        .set((
            crate::generated::schema::identities::last_tcp_port.eq(tcp_port),
            crate::generated::schema::identities::last_quic_port.eq(quic_port),
        ))
        .execute(conn)?;
    Ok(())
}

/// Load the last used TCP and QUIC ports from the database.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn load_listen_ports() -> color_eyre::Result<(Option<i32>, Option<i32>)> {
    let conn = &mut crate::sqlite_connect()?;
    let result = crate::generated::schema::identities::table
        .select((
            crate::generated::schema::identities::last_tcp_port,
            crate::generated::schema::identities::last_quic_port,
        ))
        .first::<(Option<i32>, Option<i32>)>(conn)
        .optional()?;
    Ok(result.unwrap_or((None, None)))
}

/// Calculate the average peer count across all recorded sessions.
///
/// # Errors
/// Returns an error if the database query fails.
pub fn get_average_peer_count() -> color_eyre::Result<f64> {
    let conn = &mut crate::sqlite_connect()?;
    let sessions = crate::generated::schema::peer_sessions::table
        .select(crate::generated::schema::peer_sessions::concurrent_peers)
        .load::<i32>(conn)?;
    if sessions.is_empty() {
        return Ok(0.0);
    }
    let sum: f64 = sessions.iter().map(|&c| f64::from(c)).sum();
    Ok(sum / f64::from(u32::try_from(sessions.len()).unwrap_or(u32::MAX)))
}

/// Record that a broadcast we sent was transmitted to each of `peer_ids`.
///
/// This replaces the dormant `peers.broadcasts_sent` aggregate counter with a
/// per-message, per-peer record (`broadcast_recipients`), so the peers table can
/// show, for each peer, how many broadcasts *we* sent to it. `sent_at` is the
/// transmit time; `confirmed_at` stays `NULL` until that peer acknowledges the
/// broadcast (back-filled by `messages::save_receipt` on a kind-0 receipt).
/// Insert is idempotent per `(msg_id, peer_id)` (a retransmit must not double
/// count).
///
/// # Errors
/// Returns an error if the database operation fails.
pub fn record_broadcast_recipients(msg_id: &str, peer_ids: &[String]) -> color_eyre::Result<()> {
    use crate::generated::schema::broadcast_recipients;
    use diesel::insert_into;
    use diesel::prelude::*;

    let conn = &mut crate::sqlite_connect()?;
    let timestamp = crate::current_timestamp();
    for pid in peer_ids {
        insert_into(broadcast_recipients::table)
            .values((
                broadcast_recipients::msg_id.eq(msg_id),
                broadcast_recipients::peer_id.eq(pid),
                broadcast_recipients::sent_at.eq(timestamp),
            ))
            .on_conflict((broadcast_recipients::msg_id, broadcast_recipients::peer_id))
            .do_nothing()
            .execute(conn)?;
    }
    Ok(())
}

