//! Broadcast-chat and direct-message pane rendering.

use crate::tui_render::{bordered_block, render_unread_banner};
use crate::tui_render_state::{
    TuiRenderState, broadcast_receipt_prefix, calc_visible_list_items, dm_receipt_prefix,
    reaction_suffix,
};
use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    widgets::{Block, Borders, List, ListItem, Paragraph},
};
use std::collections::VecDeque;

/// Render chat messages with scroll support and receipt markers
pub fn render_chat_content(f: &mut ratatui::Frame, area: Rect, state: &mut TuiRenderState) {
    let usable_height = usize::from(area.height.saturating_sub(2));

    let (visible, effective_offset) = calc_visible_list_items(
        &state.messages,
        state.auto_scroll.chat,
        state.chat_scroll_offset,
        usable_height,
    );

    let visible_messages: Vec<ListItem> = state
        .messages
        .iter()
        .skip(effective_offset)
        .enumerate()
        .take(visible)
        .map(|(visible_idx, msg)| {
            let global_idx = effective_offset.saturating_add(visible_idx);
            let msg_id = state
                .message_ids
                .get(global_idx)
                .and_then(|id| id.as_deref());
            let prefix = broadcast_receipt_prefix(msg_id, &state.broadcast_receipts);
            let reactions = reaction_suffix(msg_id, &state.reactions);
            ListItem::new(format!("{prefix}{msg}{reactions}"))
        })
        .collect();

    let messages_list = List::new(visible_messages).block(
        Block::default()
            .title("Broadcast Chat")
            .borders(Borders::ALL),
    );
    f.render_widget(messages_list, area);

    render_unread_banner(f, area, state.chat_unread_count, state.palette.accent());
}

/// Render DM conversation with split view (broadcast messages on top, DM on bottom)
pub fn render_dm_content(
    f: &mut ratatui::Frame,
    area: Rect,
    peer_id: &str,
    state: &mut TuiRenderState,
) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(area);

    let default_rect = Rect::default();
    let broadcast_area = *chunks.first().unwrap_or(&default_rect);
    let dm_area = *chunks.get(1).unwrap_or(&default_rect);

    let broadcast_usable_height = usize::from(broadcast_area.height.saturating_sub(2));
    let dm_usable_height = usize::from(dm_area.height.saturating_sub(2));

    let short_id = crate::get_peer_display_name_or_short(peer_id);
    let dm_title = if state.typing_peer_ids.contains(peer_id) {
        format!("DM: {short_id} — typing…")
    } else {
        format!("DM: {short_id}")
    };

    // Keep the wire ids aligned with the visible broadcast rows so this pane
    // shows the same reaction chips as the Chat tab and Flutter (US-008).
    let mut broadcast_messages = VecDeque::new();
    let mut broadcast_ids = VecDeque::new();
    for (idx, (msg, sender_id)) in state
        .messages
        .iter()
        .zip(state.message_peer_ids.iter())
        .enumerate()
    {
        if sender_id.as_ref().is_some_and(|id| id == peer_id) {
            broadcast_messages.push_back(msg.clone());
            broadcast_ids.push_back(state.message_ids.get(idx).and_then(Option::as_deref));
        }
    }

    if broadcast_messages.is_empty() {
        let broadcast_para = Paragraph::new("No broadcast messages")
            .block(bordered_block(format!("Broadcast from {short_id}")));
        f.render_widget(broadcast_para, broadcast_area);
    } else {
        let (broadcast_scroll_offset, broadcast_auto_scroll) = {
            let (offset, auto_scroll) = state
                .dm_broadcast_scroll_state
                .entry(peer_id.to_string())
                .or_insert((broadcast_messages.len(), true));
            (*offset, *auto_scroll)
        };

        let (visible, effective_offset) = calc_visible_list_items(
            &broadcast_messages,
            broadcast_auto_scroll,
            broadcast_scroll_offset,
            broadcast_usable_height,
        );

        let visible_broadcast: Vec<ListItem> = broadcast_messages
            .iter()
            .zip(broadcast_ids.iter())
            .skip(effective_offset)
            .take(visible)
            .map(|(m, id)| {
                let reactions = reaction_suffix(*id, &state.reactions);
                ListItem::new(format!("{m}{reactions}"))
            })
            .collect();

        let broadcast_list = List::new(visible_broadcast)
            .block(bordered_block(format!("Broadcast from {short_id}")));
        f.render_widget(broadcast_list, broadcast_area);
    }

    let (scroll_offset_val, auto_scroll_val) = {
        let (offset, auto_scroll) = state
            .dm_scroll_state
            .entry(peer_id.to_string())
            .or_insert((0, true));
        (*offset, *auto_scroll)
    };

    if let Some(msgs) = state.dm_messages.get(peer_id) {
        let (visible, effective_offset) =
            calc_visible_list_items(msgs, auto_scroll_val, scroll_offset_val, dm_usable_height);

        let visible_msgs: Vec<ListItem> = msgs
            .iter()
            .skip(effective_offset)
            .take(visible)
            .enumerate()
            .map(|(visible_idx, m)| {
                let global_idx = effective_offset.saturating_add(visible_idx);
                let msg_id = state
                    .dm_message_ids
                    .get(peer_id)
                    .and_then(|ids| ids.get(global_idx))
                    .and_then(|id| id.as_deref());
                let prefix = dm_receipt_prefix(msg_id, &state.dm_receipts);
                let reactions = reaction_suffix(msg_id, &state.reactions);
                ListItem::new(format!("{prefix}{m}{reactions}"))
            })
            .collect();

        let dm_list = List::new(visible_msgs).block(bordered_block(dm_title));
        f.render_widget(dm_list, dm_area);
    } else {
        let dm_para = Paragraph::new("No direct messages").block(bordered_block(dm_title));
        f.render_widget(dm_para, dm_area);
    }

    render_unread_banner(
        f,
        dm_area,
        state.dm_unread_count.get(peer_id).copied().unwrap_or(0),
        state.palette.accent(),
    );
}

//! Groups-list and group-chat rendering.

use crate::tui_helpers::peer_table_visible_range;
use crate::tui_render::{bordered_block, render_unread_banner};
use crate::tui_render_state::{TuiRenderState, calc_visible_list_items, reaction_suffix};
use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::{Modifier, Style},
    widgets::{Block, Borders, List, ListItem, ListState, Paragraph},
};

/// Render the Groups list tab with selection support.
pub fn render_groups_content(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    // One row per group; the block loses 2 rows to borders and 1 to the hint.
    let page_height = usize::from(area.height.saturating_sub(3)).max(1);
    let total = state.group_summaries.len();
    let selected = (total > 0).then(|| state.group_selection.min(total.saturating_sub(1)));
    let (start, end) = peer_table_visible_range(0, selected, total, page_height);

    let items: Vec<ListItem> = state
        .group_summaries
        .iter()
        .skip(start)
        .take(end.saturating_sub(start))
        .map(|g| {
            ListItem::from(format!("{} ({})", g.group.display_name, g.member_count))
                .style(Style::default().add_modifier(Modifier::BOLD))
        })
        .collect();

    let list = List::new(items)
        .block(
            Block::default()
                .title(format!("Groups ({total})"))
                .borders(Borders::ALL),
        )
        .highlight_style(Style::default().bg(state.palette.selection_bg()));

    let inner = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(1), Constraint::Length(1)])
        .split(area);
    let list_area = *inner.first().unwrap_or(&area);
    let hint_area = *inner.get(1).unwrap_or(&area);

    let mut list_state = ListState::default();
    list_state.select(selected.map(|sel| sel.saturating_sub(start)));
    f.render_stateful_widget(list, list_area, &mut list_state);

    let hint = if state.is_creating_group() {
        let name = state.input_text.clone();
        let target = if name.is_empty() {
            "enter a group name".to_string()
        } else {
            format!("\"{name}\"")
        };
        format!("creating/joining {target} — Enter confirms, Esc cancels")
    } else {
        "g: create or join group · Enter: open · PgUp/PgDn: page".to_string()
    };
    let hint = Paragraph::new(hint).style(Style::default().add_modifier(Modifier::DIM));
    f.render_widget(hint, hint_area);
}

/// Render a single group conversation (mirrors the broadcast-chat pane).
pub fn render_group_chat_content(
    f: &mut ratatui::Frame,
    area: Rect,
    group_id: &str,
    state: &TuiRenderState,
) {
    // Mirror Flutter's group-chat header: name, member count and short ID.
    let summary = state
        .group_summaries
        .iter()
        .find(|g| g.group.group_id == group_id);
    let (display_name, member_count) = summary.map_or_else(
        || (group_id.to_string(), 0),
        |g| (g.group.display_name.clone(), g.member_count),
    );
    let short_id: String = group_id.chars().take(8).collect();
    let title = format!(
        "Group: {display_name} ({member_count} {}) [{short_id}]",
        if member_count == 1 {
            "member"
        } else {
            "members"
        }
    );
    let usable_height = usize::from(area.height.saturating_sub(2));

    if let Some(msgs) = state.group_messages.get(group_id) {
        let (scroll_offset, auto_scroll) = state
            .group_scroll_state
            .get(group_id)
            .copied()
            .unwrap_or((0, true));
        let (visible, effective_offset) =
            calc_visible_list_items(msgs, auto_scroll, scroll_offset, usable_height);

        let items: Vec<ListItem> = msgs
            .iter()
            .skip(effective_offset)
            .take(visible)
            .enumerate()
            .map(|(visible_idx, m)| {
                let global_idx = effective_offset.saturating_add(visible_idx);
                let msg_id = state
                    .group_message_ids
                    .get(group_id)
                    .and_then(|ids| ids.get(global_idx))
                    .and_then(|id| id.as_deref());
                let reactions = reaction_suffix(msg_id, &state.reactions);
                ListItem::new(format!("{m}{reactions}"))
            })
            .collect();

        let list = List::new(items).block(bordered_block(title));
        f.render_widget(list, area);
    } else {
        let para = Paragraph::new("No messages in this group yet").block(bordered_block(title));
        f.render_widget(para, area);
    }

    render_unread_banner(
        f,
        area,
        state.group_unread_count.get(group_id).copied().unwrap_or(0),
        state.palette.accent(),
    );
}

//! Logs-tab rendering.

use crate::tui_render_state::{TuiRenderState, calc_visible_list_items};
use ratatui::{
    layout::Rect,
    widgets::{Block, Borders, List, ListItem},
};

/// Render log content
pub fn render_log_content(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    let usable_height = usize::from(area.height.saturating_sub(2));

    let (visible, effective_offset) = calc_visible_list_items(
        &state.log_messages,
        state.auto_scroll.log,
        state.log_scroll_offset,
        usable_height,
    );

    let visible_logs: Vec<ListItem> = state
        .log_messages
        .iter()
        .skip(effective_offset)
        .take(visible)
        .map(|line| ListItem::new(line.as_str()))
        .collect();

    let log_list =
        List::new(visible_logs).block(Block::default().title("Logs").borders(Borders::ALL));
    f.render_widget(log_list, area);
}

