/// Shared centered popup geometry for notices and the shortcut-help overlay.
fn render_bordered_popup(
    f: &mut ratatui::Frame,
    text: String,
    width_percent: u16,
    height_percent: u16,
    title: &'static str,
    palette: crate::theme::Palette,
) {
    let area = f.area();
    let w = area.width.saturating_mul(width_percent) / 100;
    let h = area.height.saturating_mul(height_percent) / 100;
    let popup = Rect {
        x: area.x.saturating_add(area.width.saturating_sub(w) / 2),
        y: area.y.saturating_add(area.height.saturating_sub(h) / 2),
        width: w.max(20).min(area.width),
        height: h.max(6).min(area.height),
    };

    f.render_widget(Clear, popup);
    let p = Paragraph::new(text)
        .block(
            Block::default()
                .title(title)
                .borders(Borders::ALL)
                .style(Style::default().bg(palette.popup_bg())),
        )
        .alignment(Alignment::Left)
        .wrap(Wrap { trim: false });
    f.render_widget(p, popup);
}

//! Peer-info tab rendering (mirrors Flutter's `PeerInfoScreen`).

use crate::tui_render_state::TuiRenderState;
use ratatui::{
    layout::Rect,
    widgets::{Block, Borders, Paragraph, Wrap},
};

/// Render the Peer Info tab (mirrors the Flutter `PeerInfoScreen`).
pub fn render_peer_info_content(
    f: &mut ratatui::Frame,
    area: Rect,
    peer_id: &str,
    state: &TuiRenderState,
) {
    let display = crate::get_peer_display_name_or_short(peer_id);
    let local = state.local_nicknames.get(peer_id);
    let received = state.received_nicknames.get(peer_id);

    let (origin, detail) = if local.is_some() {
        ("Local nickname", "You set this nickname for the peer.")
    } else if received.is_some() {
        (
            "Received nickname",
            "Announced by the peer. (Receipt time is not tracked.)",
        )
    } else {
        (
            "Generated petname",
            "No nickname was known, so a petname was assigned locally.",
        )
    };

    let (first_seen, last_seen) = state
        .peers
        .iter()
        .find(|p| p.peer_id == peer_id)
        .map_or_else(
            || ("unknown".to_string(), "unknown".to_string()),
            |p| (p.first_seen.clone(), p.last_seen.clone()),
        );

    // The contact row that owns this device carries the DB-backed message
    // stats (the same numbers its Contacts-tab row shows), so the two views
    // can never disagree.
    let contact = state
        .contacts_all
        .iter()
        .find(|c| c.device_rows.iter().any(|d| d.peer_id == peer_id));

    let mut lines: Vec<String> = Vec::new();
    lines.push(format!("Peer: {display}"));
    lines.push(format!("Peer ID: {peer_id}"));
    lines.push(format!("Origin: {origin}"));
    lines.push(format!("  {detail}"));
    if let Some(n) = local {
        lines.push(format!("Local nickname: {n}"));
    }
    if let Some(n) = received {
        lines.push(format!("Received nickname: {n}"));
    }
    lines.push(format!("First seen: {first_seen}"));
    lines.push(format!("Last seen: {last_seen}"));
    // Live ping sample for this peer (fed by the swarm handler). `n/a` when the
    // peer is not connected or no ping has completed yet.
    let quality = crate::net_diag::peer_quality(peer_id);
    lines.push(format!("Round-trip time: {}", quality.rtt_label));
    lines.push(format!("Ping loss: {}", quality.loss_label));
    let blocked = state.blocked_peers.contains(peer_id);
    lines.push(format!(
        "Blocked: {} (b: {})",
        if blocked { "yes" } else { "no" },
        if blocked { "unblock" } else { "block" }
    ));
    if let Some(contact) = contact {
        lines.push(format!("Direct messages: {}", contact.dm_count));
        lines.push(format!(
            "Broadcasts sent: {}",
            contact.broadcast_sent_to_peer
        ));
    }
    lines.push("Press Enter to open direct message".to_string());

    let para = Paragraph::new(lines.join("\n"))
        .block(Block::default().title("Peer Info").borders(Borders::ALL))
        .wrap(Wrap { trim: false });
    f.render_widget(para, area);
}

//! Contacts-table rendering (stateful `Table` + sort hint).
//!
//! The Contacts tab rows are canonical `ContactRow`s (from
//! `contacts::build_contact_rows`); they render through the same 5-column
//! `PeerTableRow` layout as the old peer list. Expanded multi-device contacts
//! contribute one device sub-row each, so the cursor and the scrolling
//! viewport index into the flattened `contact_table_plan`.

use crate::tui_helpers::{
    ContactTableRowRef, contact_table_plan, contact_table_row, peer_count_display,
    peer_table_column_widths, peer_table_header_labels, peer_table_visible_range,
};
use crate::tui_render_state::TuiRenderState;
use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::{Modifier, Style},
    widgets::{Block, Borders, Cell, Paragraph, Row, Table, TableState},
};

/// Render the Contacts tab with selection support
pub fn render_peers_content(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    // The table body is content_height - 1 (hint) - 2 (borders) - 1 (header)
    // rows tall; a stateful `TableState` scrolls the viewport to keep the
    // selected row visible, so PageUp/PageDown step the selection by a page.
    let page_height = usize::from(area.height.saturating_sub(4)).max(1);
    let plan = contact_table_plan(&state.contacts, &state.expanded_contact_ids);
    let total = plan.len();
    let selected = (total > 0).then(|| state.peer_selection.min(total.saturating_sub(1)));
    let (start, end) =
        peer_table_visible_range(state.peer_table_offset, selected, total, page_height);

    // Materialize only the visible window: display-name lookups are the
    // expensive per-frame cost, so paged rendering stays O(page) no matter how
    // many contacts are known.
    let rows: Vec<_> = plan
        .iter()
        .skip(start)
        .take(end.saturating_sub(start))
        .map(|&row| {
            let mut built = contact_table_row(&state.contacts, &state.expanded_contact_ids, row);
            if row_is_blocked(state, row) {
                built.display_name = format!("\u{2298} {}", built.display_name);
            }
            built
        })
        .collect();

    let header_cells: Vec<Cell> =
        peer_table_header_labels(state.peer_sort_column, state.peer_sort_ascending)
            .into_iter()
            .map(Cell::from)
            .collect();
    let header = Row::new(header_cells).style(Style::default().add_modifier(Modifier::BOLD));

    let body: Vec<Row> = rows
        .iter()
        .map(|r| {
            let cells = [
                Cell::from(r.display_name.clone()),
                Cell::from(peer_count_display(r.dm_count)),
                Cell::from(peer_count_display(r.broadcast_count)),
                Cell::from(r.last_seen.clone()),
                Cell::from(r.first_seen.clone()),
            ];
            Row::new(cells)
        })
        .collect();

    let widths: Vec<Constraint> =
        peer_table_column_widths(&rows, state.peer_sort_column, state.peer_sort_ascending)
            .into_iter()
            .map(|w| Constraint::Length(u16::try_from(w).unwrap_or(u16::MAX)))
            .collect();
    // Mirror Flutter's Contacts count: bare total with no filter, `visible/total`
    // while a search is active. Kept as a single expression so the two frontends
    // cannot drift on the format.
    let title = state.contact_search_total.map_or_else(
        || format!("Contacts ({})", state.contacts.len()),
        |all| format!("Contacts ({}/{all})", state.contacts.len()),
    );
    let table = Table::new(body, widths)
        .header(header)
        .block(Block::default().title(title).borders(Borders::ALL))
        .row_highlight_style(Style::default().bg(state.palette.selection_bg()));

    // Reserve the last row of the block's inner area for a sort hint.
    let inner = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(1), Constraint::Length(1)])
        .split(area);
    let table_area = *inner.first().unwrap_or(&area);
    let hint_area = *inner.get(1).unwrap_or(&area);

    let mut table_state = TableState::new();
    table_state.select(selected.map(|sel| sel.saturating_sub(start)));
    *table_state.offset_mut() = 0;
    f.render_stateful_widget(table, table_area, &mut table_state);

    // Match Flutter's empty-state hint: a no-match search says so explicitly;
    // an empty roster with no query says "No contacts yet.".
    let hint_text = if total == 0 {
        match state.contact_search_total {
            Some(_) => "No contacts match.",
            None => "No contacts yet.",
        }
    } else {
        "e: expand/collapse ×N · 1-5 (n/m/b/l/f): sort · o: order · click header · PgUp/PgDn: page"
    };
    let hint = Paragraph::new(hint_text).style(Style::default().add_modifier(Modifier::DIM));
    f.render_widget(hint, hint_area);
}

/// Whether a flattened Contacts row is muted (US-054).
///
/// A contact row is marked only when *every* device under it is blocked — a
/// partially muted contact shows the marker on its device sub-rows instead, so
/// the row never claims more than is true.
fn row_is_blocked(state: &TuiRenderState, row: ContactTableRowRef) -> bool {
    match row {
        ContactTableRowRef::Contact(idx) => state.contacts.get(idx).is_some_and(|contact| {
            !contact.device_rows.is_empty()
                && contact
                    .device_rows
                    .iter()
                    .all(|device| state.blocked_peers.contains(&device.peer_id))
        }),
        ContactTableRowRef::Device {
            contact_idx,
            device_idx,
        } => state
            .contacts
            .get(contact_idx)
            .and_then(|contact| contact.device_rows.get(device_idx))
            .is_some_and(|device| state.blocked_peers.contains(&device.peer_id)),
    }
}

//! Settings-tab rendering (mirrors Flutter's `_Settings` screen).

use crate::tui_render_state::TuiRenderState;
use num_traits::ToPrimitive;
use ratatui::{
    layout::Rect,
    widgets::{Block, Borders, Paragraph},
};
use std::collections::HashSet;
use std::hash::BuildHasher;
use unicode_width::{UnicodeWidthChar, UnicodeWidthStr};

/// One visual Settings row and the peer it opens, if any.
///
/// Rendering and mouse hit-testing both consume [`settings_visual_lines`], so a
/// wrapped peer row stays clickable on every line it occupies. Rows without a
/// `peer_id` are informational and ignore clicks.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SettingsLine {
    /// Exact text rendered on this visual row.
    pub text: String,
    /// Peer whose Peer Info this row opens.
    pub peer_id: Option<String>,
}

impl SettingsLine {
    /// A plain informational row.
    #[must_use]
    pub fn plain(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            peer_id: None,
        }
    }

    /// A peer row, marked with Flutter's `›` affordance.
    #[must_use]
    pub fn peer(text: impl Into<String>, peer_id: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            peer_id: Some(peer_id.into()),
        }
    }
}

/// Bound devices in deterministic peer-ID order.
#[must_use]
pub fn sorted_settings_device_ids(devices: &[(String, String)]) -> Vec<String> {
    let mut ids: Vec<String> = devices.iter().map(|(peer_id, _)| peer_id.clone()).collect();
    ids.sort();
    ids
}

/// Currently connected peers in deterministic peer-ID order.
#[must_use]
pub fn sorted_settings_peer_ids<S: BuildHasher>(connected: &HashSet<String, S>) -> Vec<String> {
    let mut ids: Vec<String> = connected.iter().cloned().collect();
    ids.sort();
    ids
}

/// The peer `Ctrl+P` opens on Settings: first connected peer, else first bound
/// device. Both lists are sorted by peer ID so the result never depends on
/// `HashSet` iteration order or DB row order.
#[must_use]
pub fn settings_peer_target<S: BuildHasher>(
    connected: &HashSet<String, S>,
    devices: &[(String, String)],
) -> Option<String> {
    sorted_settings_peer_ids(connected)
        .into_iter()
        .next()
        .or_else(|| sorted_settings_device_ids(devices).into_iter().next())
}

/// Format an optional epoch-seconds timestamp as a readable local datetime.
fn format_lost_at(ts: Option<f64>) -> String {
    ts.and_then(|t| {
        chrono::DateTime::from_timestamp(t.to_i64().unwrap_or_default(), 0)
            .map(|dt| crate::format_peer_datetime(dt.with_timezone(&chrono::Local).naive_local()))
    })
    .unwrap_or_else(|| "—".to_string())
}

/// Append one word to a wrapped row, splitting overlong words by display width.
///
/// `has_word` distinguishes the preserved indentation prefix from real content.
/// The indent survives onto the first row whenever at least one character of
/// content fits beside it; otherwise it is dropped rather than emitted alone.
fn push_word(
    word: &str,
    width: usize,
    rows: &mut Vec<SettingsLine>,
    current: &mut String,
    current_width: &mut usize,
    has_word: &mut bool,
    peer_id: Option<&String>,
) {
    let word_width = word.width();
    let separator = usize::from(*has_word);
    if current_width
        .saturating_add(separator)
        .saturating_add(word_width)
        <= width
    {
        if *has_word {
            current.push(' ');
            *current_width = current_width.saturating_add(1);
        }
        current.push_str(word);
        *current_width = current_width.saturating_add(word_width);
        *has_word = true;
        return;
    }
    if *has_word {
        rows.push(SettingsLine {
            text: std::mem::take(current),
            peer_id: peer_id.cloned(),
        });
        *current_width = 0;
        *has_word = false;
    }
    // A word that fits on an indent-only row keeps that indent; an overlong
    // word is split by display width from here instead.
    if current_width.saturating_add(word_width) <= width {
        current.push_str(word);
        *current_width = current_width.saturating_add(word_width);
        *has_word = true;
        return;
    }
    for character in word.chars() {
        let character_width = UnicodeWidthChar::width(character).unwrap_or_default();
        if current_width.saturating_add(character_width) > width {
            if *has_word {
                rows.push(SettingsLine {
                    text: std::mem::take(current),
                    peer_id: peer_id.cloned(),
                });
            }
            current.clear();
            *current_width = 0;
            *has_word = false;
        }
        current.push(character);
        *current_width = current_width.saturating_add(character_width);
        *has_word = true;
    }
}

/// Greedy word wrap used by both the renderer and the click handler.
///
/// Ratatui's `WordWrapper` is private, so Settings owns a small deterministic
/// wrapper instead: words break on spaces, overlong words break by display
/// width, leading indentation stays on the first row, and a peer target survives
/// onto every continuation row.
fn wrap_settings_line(line: SettingsLine, width: usize) -> Vec<SettingsLine> {
    if width == 0 {
        return vec![line];
    }
    let indent: String = line
        .text
        .chars()
        .take_while(|character| character.is_whitespace())
        .collect();
    let body = line.text.trim_start_matches(char::is_whitespace);
    // Keep the `› ` affordance with the first wrapped line, just like leading
    // whitespace. Continuation rows keep only the peer target, so the marker is
    // never repeated on every line of a long name.
    let (prefix, body) = if line.peer_id.is_some() {
        match body.strip_prefix("› ") {
            Some(rest) => (format!("{indent}› "), rest),
            None => (indent, body),
        }
    } else {
        (indent, body)
    };
    let mut rows: Vec<SettingsLine> = Vec::new();
    let mut current = prefix;
    let mut current_width = current.width();
    let mut has_word = false;
    for word in body.split_whitespace() {
        push_word(
            word,
            width,
            &mut rows,
            &mut current,
            &mut current_width,
            &mut has_word,
            line.peer_id.as_ref(),
        );
    }
    if has_word || !current.is_empty() {
        rows.push(SettingsLine {
            text: current,
            peer_id: line.peer_id.clone(),
        });
    }
    if rows.is_empty() {
        rows.push(SettingsLine {
            text: String::new(),
            peer_id: line.peer_id,
        });
    }
    rows
}

/// Append the persisted bootstrap/relay list (US-050 follow-up 1).
///
/// The highlight moves with Up/Down/Home/End on the Settings tab; `b`/`r`
/// open the add prompt for a bootstrap/relay multiaddr and `x` removes the
/// highlighted entry. The node only reads the list at start, so the header
/// says so.
fn render_network_peers(lines: &mut Vec<SettingsLine>, state: &TuiRenderState) {
    lines.push(SettingsLine::plain(format!(
        "Network peers ({}) — applies on next node start:",
        state.network_peers.len()
    )));
    if state.network_peers.is_empty() {
        lines.push(SettingsLine::plain("  — none configured"));
    } else {
        for (index, peer) in state.network_peers.iter().enumerate() {
            let marker = if index == state.network_peer_selection {
                ">"
            } else {
                " "
            };
            lines.push(SettingsLine::plain(format!(
                "{marker} {} {}",
                peer.kind, peer.multiaddr
            )));
        }
    }
    lines.push(SettingsLine::plain(
        "  b: add bootstrap | r: add relay | x: remove | Up/Down: select",
    ));
}

/// The most recent connection we had to report on the Settings tab: this
/// session's last disconnect if any, otherwise the known peer with the newest
/// `last_seen`. Returns `(peer_id, formatted_timestamp)`.
fn last_connected_info(state: &TuiRenderState) -> Option<(String, String)> {
    if let (Some(peer_id), Some(at)) = (&state.last_connection_peer, state.last_connection_lost) {
        return Some((peer_id.clone(), format_lost_at(Some(at))));
    }
    state
        .peers
        .iter()
        .max_by(|a, b| a.last_seen.cmp(&b.last_seen))
        .map(|p| (p.peer_id.clone(), p.last_seen.clone()))
}

/// Append the network-diagnostics block (interfaces, reachability, DHT/relay).
fn render_network_details(lines: &mut Vec<SettingsLine>, net: &crate::net_diag::NetworkDetails) {
    lines.push(SettingsLine::plain("Network details:"));
    lines.push(SettingsLine::plain(format!(
        "  Reachability: {}",
        net.reachability
    )));

    let mut nat = net.nat_status.clone();
    if let Some(addr) = &net.nat_public_addr {
        nat.push_str(" (");
        nat.push_str(addr);
        nat.push(')');
    }
    lines.push(SettingsLine::plain(format!(
        "  AutoNAT: {nat} — probes {} ok / {} failed",
        net.nat_probe_successes, net.nat_probe_failures
    )));
    lines.push(SettingsLine::plain(format!(
        "  Hole punching: {}/{} attempts succeeded",
        net.hole_punch_successes, net.hole_punch_attempts
    )));
    let relay = if net.relay_reservations.is_empty() {
        net.relay_status.clone()
    } else {
        format!(
            "{} ({})",
            net.relay_status,
            net.relay_reservations.join(", ")
        )
    };
    lines.push(SettingsLine::plain(format!("  Relay: {relay}")));

    let dht_state = if net.dht_connected {
        "connected"
    } else {
        "not connected"
    };
    lines.push(SettingsLine::plain(format!(
        "  DHT: {dht_state} ({}, {} routing peers; bootstrap {} ok / {} failed)",
        net.dht_mode,
        net.dht_routing_peers,
        net.dht_bootstrap_successes,
        net.dht_bootstrap_failures
    )));
    // Mirror Flutter: surface the announced flag, not only the status line.
    let announcement = if net.dht_announced {
        format!("Announced ({})", net.dht_announce_status)
    } else {
        net.dht_announce_status.clone()
    };
    lines.push(SettingsLine::plain(format!(
        "  DHT announcement: {announcement}"
    )));

    if !net.external_addrs.is_empty() {
        lines.push(SettingsLine::plain("  External addresses:"));
        for addr in &net.external_addrs {
            lines.push(SettingsLine::plain(format!("    {addr}")));
        }
    }

    lines.push(SettingsLine::plain("  Listen addresses:"));
    if net.listen_addrs.is_empty() {
        lines.push(SettingsLine::plain("    —"));
    } else {
        for addr in &net.listen_addrs {
            lines.push(SettingsLine::plain(format!("    {addr}")));
        }
    }

    lines.push(SettingsLine::plain("  Interfaces:"));
    if net.interfaces.is_empty() {
        lines.push(SettingsLine::plain("    —"));
    }
    for iface in &net.interfaces {
        let mac = iface.mac.as_deref().unwrap_or("no MAC");
        let loopback = if iface.internal { " (loopback)" } else { "" };
        lines.push(SettingsLine::plain(format!(
            "    {} — {mac}{loopback}",
            iface.name
        )));
        if !iface.ipv4.is_empty() {
            lines.push(SettingsLine::plain(format!(
                "      IPv4: {}",
                iface.ipv4.join(", ")
            )));
        }
        if !iface.ipv6.is_empty() {
            lines.push(SettingsLine::plain(format!(
                "      IPv6: {}",
                iface.ipv6.join(", ")
            )));
        }
    }
}

/// Logical Settings rows, before wrapping to the terminal width.
fn settings_logical_lines(state: &TuiRenderState) -> Vec<SettingsLine> {
    let connected = state.peer_count;
    let node_status = if state.runtime.node_running {
        "Running"
    } else {
        "Stopped"
    };

    let mut lines: Vec<SettingsLine> = Vec::new();
    lines.push(SettingsLine::plain(format!(
        "Nickname: {}  (press 'n' to edit)",
        state.own_nickname
    )));
    lines.push(SettingsLine::plain(format!(
        "Peer ID: {}",
        state.local_peer_id
    )));
    match &state.own_user_id {
        Some(user_id) => lines.push(SettingsLine::plain(format!("User ID: {user_id}"))),
        None => lines.push(SettingsLine::plain("User ID: —")),
    }
    if !state.own_user_devices.is_empty() {
        lines.push(SettingsLine::plain(format!(
            "Bound devices: {}",
            state.own_user_devices.len()
        )));
        let mut devices = state.own_user_devices.clone();
        devices.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
        for (device_peer, bound_at) in devices {
            let display = crate::get_peer_display_name_or_short(&device_peer);
            lines.push(SettingsLine::peer(
                format!("› {display} (bound {bound_at})"),
                device_peer,
            ));
        }
    }
    render_network_peers(&mut lines, state);
    let lan_only = crate::settings::lan_only();
    lines.push(SettingsLine::plain(format!(
        "LAN only: {} (press 'l' to toggle; applies on next node start)",
        if lan_only { "yes" } else { "no" }
    )));
    lines.push(SettingsLine::plain(format!(
        "Theme: {} / {} (press 't' for dark/light, 'c' for accent color)",
        if state.palette.dark { "dark" } else { "light" },
        state.palette.accent.as_str()
    )));
    let notification_settings = crate::notifications::settings();
    lines.push(SettingsLine::plain(format!(
        "Notification sound: {} (press 's' to toggle)",
        if notification_settings.sound {
            "yes"
        } else {
            "no"
        }
    )));
    lines.push(SettingsLine::plain(format!(
        "Desktop notifications: {} (press 'o' to toggle)",
        if notification_settings.desktop {
            "yes"
        } else {
            "no"
        }
    )));
    lines.push(SettingsLine::plain(format!("Database: {}", state.db_url)));
    lines.push(SettingsLine::plain(format!("Platform: {}", state.platform)));
    lines.push(SettingsLine::plain(format!("Node: {node_status}")));
    lines.push(SettingsLine::plain(format!(
        "Network name: {}",
        crate::CHAT_TOPIC
    )));
    lines.push(SettingsLine::plain(format!(
        "Network size: {}",
        state.network_size
    )));
    lines.push(SettingsLine::plain(format!("Connected peers: {connected}")));
    if state.connected_peer_ids.is_empty() {
        // Only ever show "currently connected" peers. When none are connected,
        // say when we last were (this session's record, else the most recently
        // seen known peer) instead of listing stale peers as connected.
        match last_connected_info(state) {
            Some((peer_id, ts)) => {
                let display = crate::get_peer_display_name_or_short(&peer_id);
                lines.push(SettingsLine::plain(format!(
                    "  Last connected {ts} to peer {display}"
                )));
            }
            None => lines.push(SettingsLine::plain("  —")),
        }
    } else {
        let connected_peers = sorted_settings_peer_ids(&state.connected_peer_ids);
        for peer_id in connected_peers {
            let display = crate::get_peer_display_name_or_short(&peer_id);
            lines.push(SettingsLine::peer(format!("› {display}"), peer_id));
        }
    }
    render_network_details(&mut lines, &state.network);
    lines
}

/// Exact visual rows for the Settings pane at the given inner width.
#[must_use]
pub fn settings_visual_lines(state: &TuiRenderState, width: usize) -> Vec<SettingsLine> {
    settings_logical_lines(state)
        .into_iter()
        .flat_map(|line| wrap_settings_line(line, width))
        .collect()
}

/// Render the Settings tab (mirrors the Flutter `_Settings` screen).
pub fn render_settings_content(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    let width = usize::from(area.width.saturating_sub(2));
    let text = settings_visual_lines(state, width)
        .into_iter()
        .map(|line| line.text)
        .collect::<Vec<_>>()
        .join("\n");
    let para = Paragraph::new(text).block(Block::default().title("Settings").borders(Borders::ALL));
    f.render_widget(para, area);
}

//! Read-only Shares tab: known shares on the left, the highlighted share's
//! manifest on the right. Mirrors Flutter's list → detail flow without any
//! mutable actions; creation/binding/snapshots stay native operations.

use crate::shares::{Share, ShareGrant, ShareKind, kind_label};
use crate::tui_helpers::peer_table_visible_range;
use crate::tui_render::bordered_block;
use crate::tui_render_state::TuiRenderState;
use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::{Modifier, Style},
    widgets::{List, ListItem, ListState, Paragraph, Wrap},
};

/// One compact row in the shares list.
fn share_row(share: &Share) -> String {
    format!(
        "{} [{}] rev {}",
        share.name,
        kind_label(share.kind),
        share.revision
    )
}

/// Detail pane lines for the selected share, plus the latest share-lane event.
fn detail_lines(share: Option<&Share>, grants: &[ShareGrant], notice: Option<&str>) -> Vec<String> {
    let mut lines = Vec::new();
    if let Some(notice) = notice {
        lines.push(format!("Last event: {notice}"));
        lines.push(String::new());
    }
    let Some(share) = share else {
        lines.push("No shares known to this install.".to_string());
        return lines;
    };
    lines.push(format!("Name: {}", share.name));
    lines.push(format!("ID: {}", share.share_id));
    lines.push(format!(
        "Kind: {} (writes: {})",
        kind_label(share.kind),
        if share.public_write { "allowed" } else { "no" },
    ));
    lines.push(format!("Owner: {}", share.owner_user_id));
    lines.push(format!(
        "Local root: {}",
        share.local_root.as_deref().unwrap_or("not bound")
    ));
    lines.push(format!("Revision: {}", share.revision));
    // Public shares have no ACL rows; mirror Flutter, which hides the Grants
    // section unless the share is private.
    if share.kind == ShareKind::Private {
        lines.push(format!("Grants ({}):", grants.len()));
        if grants.is_empty() {
            lines.push("  none".to_string());
        }
        for grant in grants {
            lines.push(format!(
                "  {} ({})",
                grant.user_id,
                crate::shares::mode_label(grant.mode)
            ));
        }
    }
    match share.manifest.as_ref() {
        Some(manifest) => {
            lines.push(format!("Files ({}):", manifest.entries.len()));
            for entry in &manifest.entries {
                lines.push(format!(
                    "  {} ({})",
                    entry.path,
                    crate::files::format_file_size(entry.size)
                ));
            }
        }
        None => lines.push("Files: no manifest yet".to_string()),
    }
    lines
}

/// Render the Shares tab: a selectable share list and the selected share's
/// metadata, grants summary and manifest file list.
pub fn render_shares_content(f: &mut ratatui::Frame, area: Rect, state: &TuiRenderState) {
    let total = state.shares.len();
    let selected = (total > 0).then(|| state.share_selection.min(total.saturating_sub(1)));

    let panes = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(40), Constraint::Percentage(60)])
        .split(area);
    let list_area = panes.first().copied().unwrap_or(area);
    let detail_area = panes.get(1).copied().unwrap_or(area);

    // The list block loses two rows to borders.
    let page_height = usize::from(list_area.height.saturating_sub(2)).max(1);
    let (start, end) = peer_table_visible_range(0, selected, total, page_height);
    let items: Vec<ListItem> = state
        .shares
        .iter()
        .skip(start)
        .take(end.saturating_sub(start))
        .map(|share| {
            ListItem::from(share_row(share)).style(Style::default().add_modifier(Modifier::BOLD))
        })
        .collect();

    let list = List::new(items)
        .block(bordered_block(format!("Shares ({total})")))
        .highlight_style(Style::default().bg(state.palette.selection_bg()));
    let mut list_state = ListState::default();
    list_state.select(selected.map(|sel| sel.saturating_sub(start)));
    f.render_stateful_widget(list, list_area, &mut list_state);

    let chosen = selected.and_then(|sel| state.shares.get(sel));
    let grants: &[ShareGrant] = chosen
        .and_then(|share| state.share_grants.get(&share.share_id))
        .map_or(&[], Vec::as_slice);
    let lines = detail_lines(chosen, grants, state.share_event_notice.as_deref());
    let para = Paragraph::new(lines.join("\n"))
        .block(bordered_block("Share details".to_string()))
        .wrap(Wrap { trim: false });
    f.render_widget(para, detail_area);
}

//! TUI rendering state abstraction for testing
//!
//! This module provides a render state that can be used by both the binary
//! and integration tests. The binary uses `AppState`, tests use this abstraction.

use crate::PeerRecord;
use crate::types::StringMap;
use std::collections::{BTreeMap, HashMap, VecDeque};

/// App-liveness flags for the renderer (Settings-tab node status + connection).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RuntimeStatus {
    /// Whether connected to the network.
    pub connected: bool,
    /// Whether the node is running (always true in the TUI).
    pub node_running: bool,
}

/// Minimum state needed to render a TUI frame
#[derive(Clone, Debug)]
pub struct TuiRenderState {
    /// Names of tabs for display (Chat, Contacts, Log, plus DM tabs)
    pub tab_titles: Vec<String>,
    /// Currently active tab index
    pub active_tab: usize,
    /// Broadcast messages in chat tab
    pub messages: VecDeque<String>,
    /// Peer ID of each message sender (None = sent by local user)
    pub message_peer_ids: VecDeque<Option<String>>,
    /// Message IDs for sent messages (None if from other peers)
    pub message_ids: VecDeque<Option<String>>,
    /// Receipt status for broadcast messages: `peer_id` -> (`msg_id` -> timestamp)
    pub broadcast_receipts: HashMap<String, HashMap<String, f64>>,
    /// Aggregated reaction chips by wire `msg_id` (US-008).
    pub reactions: HashMap<String, Vec<crate::reactions::ReactionSummary>>,
    /// Known peers (the raw device list backing `contacts`)
    pub peers: Vec<PeerRecord>,
    /// Canonical Contacts-tab rows (from `contacts::build_contact_rows`).
    /// The Contacts tab renders these; `peers` stays only as the device input.
    /// While a search is active this is the filtered view.
    pub contacts: Vec<crate::contacts::ContactRow>,
    /// Unfiltered canonical Contacts rows. Peer Info reads stats from here so
    /// hiding a row in the Contacts search never blanks its stats.
    pub contacts_all: Vec<crate::contacts::ContactRow>,
    /// Unfiltered Contacts count while a search query is applied, `None` when
    /// no filter is active. The renderer shows `Contacts (visible/total)` and a
    /// `No contacts match.` hint when this is `Some` (mirroring Flutter); using
    /// `Option` makes an active search without a known total unrepresentable.
    pub contact_search_total: Option<usize>,
    /// Contact IDs expanded into their device sub-rows on the Contacts tab.
    pub expanded_contact_ids: std::collections::HashSet<String>,
    /// Peers muted on this install (US-054), shown on the Peer Info tab.
    pub blocked_peers: std::collections::HashSet<String>,
    /// How many broadcasts *we* sent to each peer (bulk-loaded from
    /// `broadcast_recipients`), driving the peers-table "Broadcast" column.
    pub broadcast_sent_to_peer: HashMap<String, usize>,
    /// Peer IDs currently connected (subset of `peers`)
    pub connected_peer_ids: std::collections::HashSet<String>,
    /// Direct messages per peer
    pub dm_messages: BTreeMap<String, VecDeque<String>>,
    /// Message IDs for DMs per peer
    pub dm_message_ids: BTreeMap<String, VecDeque<Option<String>>>,
    /// DM receipt status per peer: (`source_peer`, timestamp)
    pub dm_receipts: HashMap<String, (String, f64)>,
    /// Peer IDs currently showing a live typing indicator (US-009).
    pub typing_peer_ids: std::collections::HashSet<String>,
    /// Current input text in message box
    pub input_text: String,
    /// Logs shown in the debug tab
    pub log_messages: VecDeque<String>,
    /// What the shared text input is currently capturing (chat/nickname/group).
    pub input_mode: crate::InputMode,
    /// Peer ID being edited (when `input_mode` is [`crate::InputMode::EditingNickname`])
    pub nickname_peer_id: String,
    /// App-liveness flags (connected + node running)
    pub runtime: RuntimeStatus,
    /// Number of connected peers
    pub peer_count: usize,
    /// Whether mouse is captured (for text input)
    pub mouse_capture: bool,
