            .expect("ws request");
        request.headers_mut().insert(
            "cookie",
            HeaderValue::from_static("p2p_web_session=4102444800.forged"),
        );
        assert!(
            tokio_tungstenite::connect_async(request).await.is_err(),
            "a forged session cookie must be rejected"
        );

        server.abort();
    }
}
